window.QUAN_KU_PART_3 = [
  {"t":"病中六首 其一","p":"","d":"宋代","a":"陈师道","c":["旧岁连新岁，凉床又暖床。山川屏里画，时刻篆中香。", "畏垒安吾土，支离饱太仓。若教身再健，鹤背入维扬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵秦少游王仲至元日立春三首 其二","p":"","d":"宋代","a":"苏轼","c":["己卯嘉辰寿阿同，愿渠无过亦无功。明年春日江湖上，回首觚棱一梦中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏侯彦济武陟尉","p":"","d":"宋代","a":"欧阳修","c":["风烟地接怀，井邑富田垓。", "河近闻冰坼，山高见雨来。", "官闲同小隐，酒美足衔杯。", "好去东篱菊，迎霜正欲开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雪中投宿栖隐寺寺去大冶五千里在乱山中 其一","p":"","d":"明代","a":"袁宏道","c":["下马历巑屼，晶晶四壁寒。山门云占断，佛舍雨浇残。", "茶好临泉试，松宜带雪看。轩窗无一可，孤负此峰峦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词 其七十二","p":"","d":"宋代","a":"宋白","c":["外国人来献宝珠，琉璃双眼赤金须。奇形不欲宫中见，诏遣滕王进画图。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清暑","p":"","d":"宋代","a":"张九成","c":["碧纱灯照素屏风，满院凉生秋意浓。", "谁信人间五六月，清寒如在玉壶中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题画","p":"","d":"明代","a":"林俊","c":["鬓发沧浪老病翁，小山时对桂花丛。白沙翠竹逃名外，一棹江烟水月中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游丝曲","p":"","d":"明代","a":"孙蕡","c":["游丝映户春风荡，雕檐雨挹踟蛛网。春花亦笑绮帐空，故遣飞红入虚幌。", "青楼夫婿醉忘归，魂梦相寻意转迷。恍似妾心怀旧爱，还如君意恋新栖。", "绮疏鹦鹉通人语，戏把枇杷掷金羽。含情暗卜无心负，今夜渠侬到家否。", "游丝罥花风叶叶，吴罗袷薄新寒怯。蜂游亦解钻绮疏，不独房栊出蝴蝶。", "怀人不为青春过，别有閒愁幽思多。君情妾意俱肠断，旧爱新怜奈尔何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寂寞三首 其一","p":"","d":"当代","a":"崔荣江","c":["欲理愁丝绪更多，谁赊一计转平和。无人枕入荻花梦，寒柝声中将夜磨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"村居五首 其三","p":"","d":"金朝","a":"马定国","c":["五月南风化蟪蛄，野塘晚笋未成蒲。柽花落尽红英细，沙渚鸳鸯半引雏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"玉田道中得诗二句因足之","p":"","d":"宋代","a":"韩淲","c":["秋晚晴原上玉田，水边林下过金仙。寺钟欲动黄昏月，野鸟时横碧落天。", "萸糁人家皆取醉，菊花篱槛亦争妍。三叉路入孤村去，九日閒投物外缘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵卢致远见示","p":"","d":"宋代","a":"陈著","c":["新春欲洗旧氛埃，并竹寻溪试一来。", "冻雨忽交疏霰下，严风不放寸云开。", "主人雅量诗相住，老客归心梦亦催。", "滑道何妨徐著步，袖中金薤不虚回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄宋潜溪 其一","p":"","d":"元代","a":"戴良","c":["孤鸿失俦侣，连翩洲渚湄。自知羽翮短，不与同奋飞。", "寄声奋飞者，当慎子所之。烟波渺无从，云路迥难依。", "云路多鹰隼，烟波有虞机。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"二月十六日将赴台留别樊都事仲郛黄理问元徽","p":"","d":"明代","a":"刘崧","c":["本从老圃学携锄，幸际明时出曳裾。滥食祇惭公禄厚，按行常恨吏才疏。", "天寒羸马嘶长枥，日晏慈乌下广除。浅薄将何供补报，萧萧华发不胜梳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠王处士","p":"","d":"唐代","a":"许浑","c":["归卧养天真，鹿裘乌角巾。茂陵闲久病，彭泽醉长贫。", "冠盖西园夜，笙歌北里春。谁怜清渭曲，又老钓鱼人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"葛居士诗","p":"","d":"宋代","a":"张方平","c":["三峰顶上五经秋，妙法白莲清净脩。无数天花常自散，真空性水不停流。", "病痴谁问维摩诘，俗眼徒嗟冉伯牛。别有妙身诸相具，金刚坚固异浮沤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九日宴杜氏庄","p":"","d":"明代","a":"饶相","c":["客里逢佳节，登高集野亭。帽欹须用□，杯倒不教停。", "细雨滋黄菊，孤云掩翠屏。此回开口笑，何日又重经。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋晚山居","p":"","d":"唐代","a":"黄滔","c":["爽气遍搜空，难堪倚望中。孤烟愁落日，高木病西风。", "山寂樵声出，露凉蝉思穷。此时尘外事，幽默几人同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送房孙重奴行","p":"","d":"元代","a":"耶律楚材","c":["汝亦东丹十世孙，家亡国破一身存。而今正好行仁义，勿学轻薄辱我门。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游天平山十六韵","p":"","d":"清代","a":"弘历","c":["吴会众山镇，天平万笏朝。飞来峰拔地，林立石干霄。", "茶坞西邻近，支硎北户招。势连高景秀，气接太湖潮。", "是日春方仲，行时兴倍饶。灵岩盘岭路，功德访云寮。", "芳玉溪梅绽，柔金陌柳摇。行行见别墅，缓缓度横桥。", "宛到前游处，閒看旧咏标。名园实潇洒，古迹半荒寥。", "文正风犹在，梓桑泽未遥。小停憩閒馆，更进步层椒。", "翠樾茈虒密，苍岩突兀峤。庵传远公法，泉溯白翁谣。", "绝顶高无匹，三吴望里要。未称元气复，用是一心焦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山居","p":"","d":"元代","a":"陈高","c":["避喧林下居，抱病山中卧。家贫酒屡空，性懒诗慵课。", "禽声隔树啼，云影当窗过。独有采樵人，时来慰衰惰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"庐山寺","p":"","d":"近代","a":"蒋彝","c":["风枝摇曳似相招，雨经清幽意转绕。", "陶令远公今岂是，共君闯过虎溪桥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"艮岳百咏 清斯亭","p":"","d":"宋代","a":"李质","c":["天波万斛泻镕银，跨水横桥丽构新。但取真堪濯缨意，玉阶金阙本无尘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿苏筑","p":"","d":"明代","a":"释函可","c":["不厌人间水半卮，独将枯杖问须眉。鸡窗冷淡存馀雪，鹿野荒沉出别枝。", "歌满关河聊当哭，食残铁石好支饥。旧时閒梦应频见，却恨残年叹未衰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"行香子 偕卫中亚明兄游云居寺旧址并石经山","p":"","d":"当代","a":"张力夫","c":["苔径残墙，古殿凋梁。柏参天、柿子摇黄。人来此地，欲受灵光。", "怅佛无头、寺无主、世无常。", "陶潜深隐，阮籍疏狂。信当时、费尽思量。但呼知己，畅饮琼浆。", "在白云间、青山上、紫霞旁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"天仙子 立夏","p":"","d":"清代","a":"陈世祥","c":["酒恶更嗔花气袅。起把落花和露扫。黄鹂一个上枝头，来报道。", "添烦恼。今日五更春去了。", "倦眼舒将烟渺渺。是处溪山今绿绕。却拈短棹问桃源，非故道。", "人间杳。繁阴如雨无啼鸟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"永叔自南阳至余郊迓焉","p":"","d":"宋代","a":"梅尧臣","c":["郭门临汝水，镜色入高衢。鞍马过其上，尘襟荡已无。", "及郊逢故友，出涕各沾襦。神物丧头角，空存尾与躯。", "沟木失匠斲，谁施蓝与朱。并辔不能语，斯文其已夫。", "归来授予馆，自为炊彫胡。且勿厌兹会，日月易以徂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重华宫曲宴于阗回长漠咱帕尔","p":"","d":"清代","a":"弘历","c":["朝天兼值预朝正，曲宴宜教沐宠荣。尔父诚为识时务，王臣讵有限禆瀛。", "旧宫小会轻齐史，新域来宾愿武成。入律东风方凑达，春台乐与物咸亨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"视田五首赠八弟无斁 其一","p":"","d":"宋代","a":"晁补之","c":["河流之所濡，一斛泥数斗。我庄当水穷，乃比石田瘦。", "尚无东陵瓜，况有南山豆。天雨不可期，且复鞭牛后。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋兴八首追和杜老 其三","p":"","d":"宋代","a":"王之道","c":["云影曚昽日洒晖，金湖西畔晚阴微。渔舟缭绕青山去，枫叶追随白鸟飞。", "摩诘家风非世有，渊明心性与时违。近来病瘠连诗瘦，翻爱西台字样肥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谒灵泽夫人庙 其二","p":"","d":"近代","a":"汪石青","c":["一锁深宫望翠华，巫云梦断哭天涯。徒劳上将安刘室，终见阿兄负汉家。", "此事已成千古恨，长江犹抱数峰斜。水天岑寂松楸冷，惆怅垂杨宿暮鸦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同贾岛宿无可上人院","p":"","d":"唐代","a":"雍陶","c":["何处销愁宿，携囊就远僧。中宵吟有雪，空屋语无灯。", "静境唯闻铎，寒床但枕肱。还因爱闲客，始得见南能。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别王彦举","p":"","d":"明代","a":"孙蕡","c":["东风吹赴龙头选，又别王郎听雨轩。既拥青绫吟北牖，更张红烛醉南园。", "秋还芸草书香秘，夜久芙蓉漏滴繁。后夜玉堂追往梦，一簪华发共谁言。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偶成三首 其二","p":"","d":"明代","a":"王鏊","c":["漠漠斜晖转树腰，花前柳下步逍遥。忽思右掖门前侣，隐几无言候早朝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"复州十咏 其三","p":"","d":"清代","a":"多隆阿","c":["随缘寓目尽怡情，缓缓扬鞭计路行。衰柳经秋全绕郭，寒溪如带半围城。", "乡人淡泊差无竞，古迹流传尚有名。默想今宵天上月，知他还自照西平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"曾渊子第四十四","p":"","d":"宋代","a":"文天祥","c":["子负经济才，郁陶抱长策。", "安得万里风，南图回羽翮。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赏茶","p":"","d":"宋代","a":"戴炳","c":["自汲香泉带落花，漫烧石鼎试新茶。绿阴天气闲庭院，卧听黄蜂报晚衙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春日投钱塘元帅尚父二首","p":"","d":"唐代","a":"罗隐","c":["正忧衰老辱金台，敢望昭王顾问来。门外旌旗屯虎豹，", "壁闲章句动风雷。三都节已联翩降，两地花应次第开。", "若比紫髯分鼎足，未闻馀力有琼瑰。", "征东幕府十三州，敢望非才忝上游。官秩已叨吴品职，", "姓名兼显鲁春秋。盐车顾后声方重，火井窥来焰始浮。", "一句黄河千载事，麦城王粲谩登楼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"展墓次杨景昌韵","p":"","d":"明代","a":"江源","c":["薄宦羁人不自由，十年湖海负松楸。幸叨五鼎惭终养，三复蓼莪空泪流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"中秋次蘖庵韵二首 其二","p":"","d":"明代","a":"黄淮","c":["读书何幸际昌期，廊庙良材子所宜。职典铨曹才数日，身淹丛棘已多时。", "伤心空负题桥志，对景愁吟陟圮诗。试看徂徕松与柏，霜枝雪干晚离离。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和张倅湖上十绝 其八","p":"","d":"宋代","a":"姜特立","c":["尽将丘壑捲胸中，醉帽归时御晚风。明日府公催吏牍，可堪骑马踏香红。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"牛车","p":"","d":"清代","a":"张湄","c":["短靷高箱服两牛，柴车挽运健于舟。五更残月梦初醒，角韵呜呜生客愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重过何氏北涧","p":"","d":"元代","a":"刘永之","c":["北堂宴罢倚微醺，竹几灯花坐夜分。再酌兰樽浮绿醑，重拈綵笔写清文。", "山寒岚气朝成雨，地湿松阴暮起云。休讶野人留恋久，十年江海厌离群。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"道上口占","p":"","d":"清代","a":"李寄","c":["暂憩征鞍道路中，世閒公道是春风。破垣废井苍苔合，无主桃花分外红。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"瓦庙","p":"","d":"宋代","a":"李廌","c":["柱侧檐攲瓦欲飘，断垣苔涩树萧萧。满庭荒草无香火，惟有禽声伴寂寥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"溪居","p":"","d":"宋代","a":"郭忠谟","c":["凿破青山骨，初营数亩丘。", "泉分幽窦乳，峡束大江流。", "渔唱来花径，山光落钓舟。", "沙鸥惊笑语，片片起沧洲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"扈从御宿池","p":"","d":"唐代","a":"祖咏","c":["君王既巡狩，辇道入秦京。远树低枪垒，孤峰入幔城。", "寒疏清禁漏，夜警羽林兵。谁念迷方客，长怀魏阙情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登舟一夕对酒偶成时从阅云梯关归清江浦丁亥十月 其三","p":"","d":"清代","a":"曾广钧","c":["雁下平芜秋气深，要从湖海试雄心。玉龙灰尽难成烛，彩凤归来不听琴。", "正月繁霜伤小雅，斜飙细雨冻号禽。阻风中酒兼朝夕，转毂光阴思不禁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上安晚节丞相三首","p":"","d":"宋代","a":"释道璨","c":["日食何曾费万钱，只将苜蓿荐春盘。", "俸余不用肥奴马，留买青山取性看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"五塔寺","p":"","d":"清代","a":"金朝觐","c":["五岳真形具，崔巍踞法台。石门时启闭，磴道喑纡回。", "风铎层层系，金身面面开。遥知官路外，瞻仰万人来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉题常君殉节录后 其一","p":"","d":"清代","a":"陈桂森","c":["昔岭寒风落照殷，英魂千古炳人间。屯粮绩著三军幕，陷阵躯捐一剑镮。", "死尚握拳如卞壸，生能噀血亦常山。不徒循吏称遗爱，父老西川泪共潸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"旅中","p":"","d":"宋代","a":"蔡槃","c":["梧叶响荒塘，秋宵不耐长。", "猿啼千嶂外，人在一灯旁。", "雁影溪桥月，钟声野寺霜。", "明朝又何处，烟水正茫茫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别韩参知叔捷十年已偶游罗浮过访赠以诗","p":"","d":"明代","a":"欧必元","c":["蜀锦寄江头，翻思已十秋。谁言方岳贵，犹念布衣游。", "白社招陶令，青门忆邵侯。东山高卧处，今乃在罗浮。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"五和二首 其二","p":"","d":"宋代","a":"刘克庄","c":["颓然一榻懒巾靴，二月东风尚未和。雀闯屋檐来作宿，蜂衔窗纸去为窝。", "牢愁余发五分白，健思君才十倍多。欲访东皋贤鼻祖，几回路与醉乡蹉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九月四日钱少司寇舟抵维扬同年卢都转雅雨放艇真州邀余往会至即同饮官斋更期九日平山堂登高二首 其一","p":"","d":"清代","a":"戴亨","c":["旌节来长水，扁舟发夜分。官斋同宴饮，天象动星文。", "深涧流甘乳，高松养白云。久邀贤地主，相待共清氛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"八月十七日扁舟渡钱塘江 其一","p":"","d":"宋代","a":"沈与求","c":["一言初欲寤明君，去矣终缘丞相嗔。凫雁江湖真我辈，龙蛇山泽定何人。", "市中未识冯延寿，门外已呼祁孔宾。尚有忧时心未歇，西风吹泪湿纶巾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"步虚词十首 其五","p":"","d":"唐代","a":"吴筠","c":["扶桑诞初景，羽盖凌晨霞。倏歘造西域，嬉游金母家。", "碧津湛洪源，灼烁敷荷花。煌煌青琳宫，粲粲列玉华。", "真气溢绛府，自然思无邪。俯矜区中士，夭浊良可嗟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"边思","p":"","d":"宋代","a":"释文珦","c":["胡雁南翔已尽回，闺中不见寄书来。", "穷荒二月无青草，长对东风赋七哀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送李侍御","p":"","d":"唐代","a":"贾至","c":["我年四十馀，已叹前路短。羁离洞庭上，安得不引满。", "李侯忘情者，与我同疏懒。孤帆泣潇湘，望远心欲断。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"兰陵王 午诒赋此调寄宝生，奉同一首，后阕为薛四发也","p":"","d":"清代","a":"樊增祥","c":["海天碧。春雨江南送客。离筵畔，红杏满枝，转盼新烟过寒食。", "衡阳雁向北，不带湘人尺帛。春申浦，波嫩草香，犹认骄骢旧行迹。", "高斋未寥寂，纵不见韦三，犹见秦七。碧桃花下黄藤席。", "还睥睨当世，酌商千古，西窗残烛一剪蜜，替垂泪何益。", "今夕是何夕。且近倚吴歌，遥和湘瑟，吹笙露下双鬟湿。", "自薄倖归去，懒亲钗泽。明珠为泪，共夜雨，枕畔滴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送黄邦瑞还广","p":"","d":"明代","a":"蔡清","c":["抱病日茕茕，君今又远行。斯文谅有味，分手能无情。", "柳色才沾白，稍头又转青。百年真转毂，何以慰平生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水围六首 其五","p":"","d":"清代","a":"弘历","c":["春气乍暄还乍冷，羽禽时去亦时来。空行正复何妨也，南史奚称褚炫才。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"诗三首 其三","p":"","d":"宋代","a":"徐守信","c":["南庄北宅眼前花，好儿好女莫缦誇。我若一朝身死后，又属张三李四家。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"从征诗","p":"","d":"南北朝","a":"傅亮","c":["息徒西楚，伫楫旧乡。止犹岳立，动则云翔。烈烈群师，星言启行。", "泛舟掩河，秣马登芒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和紫阳先生韵八首 其一","p":"","d":"明代","a":"杨爵","c":["省愆终未敢尤人，报国焉知己道真。肯向遭时存外慕，但须临难致吾身。", "拙猷未可轻寒士，迂恤曾何间小臣。莫谓幽圜同永夜，天王明鉴说如神。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"威烈王","p":"","d":"宋代","a":"徐钧","c":["大柄潛移势可忧，朝网未正况诸侯。", "时人只咎轻分晋，不道东西已剖周。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"减兰　见月作二首 其二","p":"","d":"当代","a":"卢青山","c":["山中老衲，石尽趋门知听法。一发犹存，为惜丝毫父母身。", "凄凉不必，死有青蝇为吊客。何况身强，十斗能餐酒万觞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹰","p":"","d":"近代","a":"齐璜","c":["振羽何曾猎一围，无穷搏击只私肥。如今四面全开网，浅草平原一线飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"行者智江归庐山乞颂","p":"","d":"宋代","a":"释心月","c":["庭前荒草正萋萋，却忆丹霞划去时。", "莲社峰高相见了，回来却把圣僧骑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"二郎神 饮李氏康乐园展重阳作，用汤恢韵","p":"","d":"清代","a":"杨玉衔","c":["翠微径仄，怯鬓白、被风飘影。念橘柚新阴，枌榆旧社，门掩裙裾客冷。", "比似侯爪将军树，勿误认、文园秋病。喜百果缀星，千花扶路，如临天镜。", "重省。衔杯笑语，云浓液凝。识棨戟门庭，邯郸客枕，先被流莺唤醒。", "松菊三休，茱萸再醉，犹是龙山风景。人解道，檀锁雕笼鹇放，一帘尘静。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠高峰","p":"","d":"明代","a":"袁宏道","c":["捉得松为柄，粘来纸作衾。山云娇老态，溪水有无心。", "挂锡沉香树，安禅天竹林。西来闲会取，空迹寄飞禽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杉木长涧四首 其四","p":"","d":"宋代","a":"朱熹","c":["阡陌纵横不可寻，死伤狼籍正悲吟。若知赤子元无罪，合有人间父母心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怀天竺磵梅","p":"","d":"宋代","a":"葛天民","c":["根在岩边结，枝从水际横。", "此花殊近道，凡木欠修行。", "密雪笼幽片，疏篁倚瘦茎。", "那时香不浅，忆我话无生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和交代韩公绛端明别后见寄","p":"","d":"宋代","a":"赵抃","c":["关山晴晓过绵州，两蜀人思惠爱稠。去路旌麾朝日下，驾空桥栈接云头。", "初观妙句离怀释，似酌清泉渴恙瘳。孤绪摇摇更东望，西楼千尺止三休。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"深居杂兴六首","p":"","d":"宋代","a":"林逋","c":["松竹封侯尚未尊，石为公辅亦云云。", "清华自合论闲客，玄默何妨事静君。", "鹤料免惭尸厚禄，茶功兼擬策元勋。", "幽人不作山中相，且拥图书卧白云。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书斋漫咏","p":"","d":"清代","a":"安鉴培","c":["茅檐鸡犬静无哗，吟罢长篇兴倍赊。雨过萧萧凉似水，凭栏闲看海棠花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自郧阳回舟再过重滩","p":"","d":"清代","a":"陈浩","c":["送客桃花水，迎人乱石滩。船从千丈落，春到九分残。", "风幔且高卷，云山须再看。去时新绿柳，飞絮已成团。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"青石阻雨","p":"","d":"宋代","a":"李新","c":["茅屋阴多麦化蛾，西山云重雨流禾。", "未闻因也改其乐，解道虞兮奈若何。", "身与前村孤堠远，泪随流水一溪多。", "文章生世元无力，半岁边城伴枕戈。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"罗浮山过访值予远游留诗而去既归复来出荷锄图索题用韵赋赠 其一","p":"","d":"明代","a":"成鹫","c":["昨日别东林，客来烟雨深。主人不可见，谁见主人心。", "独鹤云中语，枯桐弦外音。遥情当良觌，秋水碧千寻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋日登鸡鸣寺五道选一","p":"","d":"近代","a":"林散之","c":["结绮犹歌宴，隋师已入关。可怜陈叔宝，谁谓有心肝。", "湖水波仍碧，枫林叶正丹。迟回秋不尽，微雨过钟山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送焦君实之采石学官","p":"","d":"宋代","a":"陆文圭","c":["江水日以远，山花日又新。", "先吾不复少，后我皆成人。", "之子如良金，出矿以精纯。", "又如出中木，始遇雪发春。", "送子启长途，跋子升华津。", "青云题柱客，白发倚闾亲。", "有志皆腾逸，非才独隐沦。", "山林双鬓古，井臼一生贫。", "宇宙无穷事，行藏各自身。", "因风傅短句，望月吊词臣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"高宗郊前朝献景灵宫二十一首 其八 奉馔用《吉安》。","p":"","d":"宋代","a":"郊庙朝会歌辞","c":["百职骏奔，来相于庭。奉盛以告，登兹芳馨。际天蟠地，默运三灵。", "神兮来歆，祚我休平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"荔子","p":"","d":"宋代","a":"刘子翚","c":["挺秀穷荒叹未遭，昔贤吟赏著风骚。", "纵班卢橘材非偶，不近长安价愈高。", "烟雨万株遥若画，尘埃一骑笑徒劳。", "琱盘此日无遗远，品格妍媸敢自逃。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"弈棋绝句二首 其一","p":"","d":"宋代","a":"洪炎","c":["新秋遣闷只围棋，病不衔杯亦废诗。对局萧然两无语，个中君子有争时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"渔家傲","p":"","d":"元代","a":"欧阳玄","c":["三月都城游赏竞。宫墙官柳青相映。十一门头车马迸。", "清明近。豪家寒具金盘饤。", "墦祭流连芳草径。归来风送梨花信。向晚轻寒添酒病。", "春烟暝。深深院落秋千迥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"金缕曲 感旧，赠余氏兄弟二首，附致云卿丈书后 其一","p":"","d":"清代","a":"易顺鼎","c":["记向郧阳道。有伤心、荒原一带，高楼斜照。差幸当年无意绪，马上征人太小。", "省多少闲凭闲吊。数遍古来飘泊者，到天涯、毕竟输侬早。", "算已是，倦游了。", "君家阁上滩声闹。共商量竹弓射鸭，花绷捕蚤。水远山重知几叠，着个儿时游钓。", "回首觉乱离都好。莫话十年兄弟感，怕江湖、一半垂垂老。", "写不出，旧时稿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上泸州杨尚书四十韵","p":"","d":"宋代","a":"程公许","c":["清莹玻璃水，巉岩石笋峰。孕才供世用，有道致时雍。", "阀阅宋清节，源流唐靖恭。异时先太史，司匦事光宗。", "忠愤排黄闼，忧危溢皂封。扶颠重立极，涉笔但司农。", "馀地勤菑穫，连城荐璧琮。羽毛参薛凤，头角半荀龙。", "赫奕誇分鼎，铿鍧响大镛。云霄才直上，时运快遭逢。", "袖馥麋丸赐，芸翻蠹简重。亨衢无龃龉，按辔独从容。", "监寺虽平进，班行叹乏供。赐茶经幄暝，濡笔殿坳彤。", "晓陛荷囊拥，春墀革履跫。时来如邂逅，虑远妙弥缝。", "霖雨睿思渴，云山归兴浓。入辞亲黼座，宣劝滟金钟。", "可使安耕稼，无劳访枸筇。锦衣华故里，茸纛拂遐冲。", "龙驾攀无及，乌号涕莫从。嗣皇初访落，达孝极思庸。", "故老尤纡眷，庭臣孰比踪。威名震滇僰，治体嗣黄龚。", "白羽閒春燕，黄埃敛夕烽。官刑惩纵暴，民气化醇醲。", "北定风檐敞，西来雪浪舂。凭栏聊放目，忧国若为悰。", "褒诏烦因任，真祠未许慵。定知频侧席，胡不趣追锋。", "念昔联瓜葛，游谈及菲葑。驽骀劳剪拂，矿质费陶镕。", "冰谷窘寒冻，石田加蕴爞。摄斋时缓缓，衔感志忪忪。", "世论方胶柱，人情谨护痈。迟公归燮理，为国扫蒙茸。", "溯日孤忠炯，飞霜两鬓松。欲酬青玉案，何有色丝胸。", "自笑疏顽甚，犹须砭剂攻。兔丝虽小草，千丈托长松。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"诰赠中宪大夫常公殉节诗 其二","p":"","d":"清代","a":"马维驭","c":["国士慨然报国忠，风高昔岭泣英雄。绩传理饷邀荣擢，勇奋捐生契圣衷。", "日落花溪祠宇黯，云移木果塞烟空。西充漫说千秋祀，午夜清魂到海东。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百六十九首 其二十三","p":"","d":"宋代","a":"释智朋","c":["提折脚铛，各出只手。释迦不先，弥勒不后。妙用临机，如盘珠走。", "鼓腹笑复歌，面南看北斗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和刘卿材十咏 其九 龙潭","p":"","d":"宋代","a":"黄庶","c":["寂寞真龙去，雩坛血不乾。世情多冷暖，对此鼻辛酸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽胡茂老枢密 其三","p":"","d":"宋代","a":"李正民","c":["昔日蓬山会，平居笑语亲。薄材陪贾马，高义继雷陈。", "南国居方卜，东山道益振。遽嗟埋玉恨，清泪洒衣巾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游武夷二绝","p":"","d":"宋代","a":"李洪","c":["野水溶溶易满堤，十分强半麦成畦。", "我来宴坐久无语，日蟆昃深莺乱啼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"静宜园二十八景诗 其十 栖云楼","p":"","d":"清代","a":"弘历","c":["过去心难得，未来亦复然。以此例现在，毕竟谁火传。", "高楼号栖云，题句忆昔年。阶畔碎琼声，报我无留迁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和阳念三自武昌至京师","p":"","d":"宋代","a":"张耒","c":["三年别我客荆州，一日长安从我游。", "爱君诗有春草句，使我神游黄鹤楼。", "江山望尔欲穿眼，见我惊嗟秋鬓短。", "扁舟可办吾欲东，年年五湖魂梦中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过南荡三首 其一","p":"","d":"宋代","a":"杨万里","c":["秧才束发幼相依，麦已掀髯喜可知。笑杀槿篱能耐事，东扶西倒野酴醾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏儒释道三教总赠程洁庵：释教十三首 其十一 朝阳补破衲","p":"","d":"元代","a":"李道纯","c":["朝阳补衲假妆么，补了肩头又补腰。补了破时重又补，到头争似赤条条。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"点绛唇（瑞香）","p":"","d":"宋代","a":"王十朋","c":["阑槛阴沉，紫云呈端馀寒凛。卷帘欹枕。香逼幽人寝。", "入梦何年，庐阜闻名稔。风流甚。阿谁题品。唤作熏龙锦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫辞三绝送黄虞部北上 其三","p":"","d":"明代","a":"林大春","c":["夜度箫笙入紫霄，晨飘仙佩杂琼瑶。如今老却纤纤手，肯向人间学舞腰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"黄泥坂词","p":"","d":"宋代","a":"苏轼","c":["出临皋而东骛兮，并丛祠而北转。", "走雪堂之陂陀兮，历黄泥之长坂。", "大江汹以左缭兮，渺云涛之舒卷。", "草木层累而右附兮，蔚柯丘之囱蒨。", "余旦往而夕还兮，步徙倚而盘桓。", "虽信美而不可居兮，苟娱余于一眄。", "余幼好此奇服兮，袭前人之诡幻。", "老更变而自哂兮，悟惊俗之来患。", "释宝璐而被缯絮兮，杂市人而无辨。", "路悠悠其莫往来兮，守一席而穷年。", "时游步而远览兮，路穷尽而旋反。", "朝嬉黄泥之白云兮，暮宿雪堂之青烟。", "喜鱼鸟之莫余惊兮，幸樵苏之我嫚。", "初被酒以行歌兮，忽放杖而醉偃。", "草为茵而块为枕兮，穆华堂之清宴。", "纷坠露之湿衣兮，升素月之团团。", "感父老之呼觉兮，恐牛羊之予践。", "于是蹶然而起，起而歌曰月明兮星稀，", "迎余往兮饯余归。岁既宴兮草木腓，", "归来归来兮，黄泥不可以久嬉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"半闲堂","p":"","d":"近代","a":"梁季子","c":["半闲堂，浪子宰相贾平章。湖山风月原无主，付与平章仔细量。", "朝登多宝阁，夜宴西湖中。指挥铁如意，经纶蟋蟀笼。", "衣香毾㲪暖，席地氍毹红。江南无复一寸乾净赵家土，平章堂上生春风。", "鄂州城破江淮阻，天子诏开都督府。荔子黄柑献伯颜，单舸遁走扬州坞。", "肩舆烈日出循潭，南州之歌尔何堪。箫鼓华堂兴未酣，伤心又见木棉庵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"行年七十二","p":"","d":"元代","a":"陈谟","c":["行年七十二，白发向人羞。肯羡梁江总，空怀齐楚丘。", "绣衣题姓字，皂盖验春秋。一自周原猎，难为渭水叟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"扫蜜","p":"","d":"宋代","a":"方岳","c":["须蜜之人去其国，尽以族行无敢逸。缀如垂瘤大如囊，低压山墙于我室。", "秦人逐客真少恩，客来须看春正酣。咄嗟已办四山壁，正对桃李开茅庵。", "苍头奴解与之语，拥彗招邀聿来宇。相攸新邑经始忙，先作高台奉盟主。", "沈沈夥涉之为王，独无摇毒之虿芒。熙熙登台坐垂拱，花底退衙春昼长。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"画马题 其二","p":"","d":"明代","a":"张穆","c":["濡毫流电绝商量，幻出毛龙白玉光。共爱青丝挽垂柳，莫教容易献昭王。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九叹九首 其三","p":"","d":"元代","a":"刘基","c":["天有田兮不可以耕。山有龟兮不可以知咎徵。剡蒿以为梁兮削菌以居楹。匠石却走兮工垂拊膺。", "登高望远兮观四瀛。水东流兮日西倾。般纷纷兮各有营。我独展转兮从夜达明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"交傍晚凝子华见寄","p":"","d":"宋代","a":"陈著","c":["老矣息林邱，平生不径由。", "知心时一见，安分别无求。", "寒卧死中活，荣华乐处忧。", "世閒何限事，曾看过云不。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三河县","p":"","d":"清代","a":"弘历","c":["近山风转严，当秋树如绮。策渡过三河，马足怯寒水。", "秉穗堆圃场，老幼趁墟市。稍免冻与饥，忧馀亦生喜。", "寻思赤县广，安得皆似此。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蝶恋花 其二十二","p":"","d":"近代","a":"赵尊岳","c":["乍暖还寒春意早。载榼寻芳，香径啼莺小。万一流光轻负了。", "少年能否年年少。", "不解酬春应自笑。飞絮飞花，犹有晴丝绕。未必蓬山无梦到。", "逢花且拌新刍倒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别后寄赵宾旸并杨华父二首","p":"","d":"宋代","a":"方回","c":["虚翁眼暗鲁翁聋，聚散匆匆老病踪。", "近已有人传我死，何期此地与君逢。", "两穷未必时流识，一笑犹为造物容。", "自觉平生豪故在，能挥万字饮千钟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"垂丝海棠","p":"","d":"明代","a":"瞿佑","c":["袅袅春风拂苑墙，天机呈巧织仙裳。玉栏斜搭酣春睡，银烛高烧照晚妆。", "华屋雨寒愁绪乱，绮窗日暖唾茸香。诗成倘有纤毫补，愿醉佳人锦瑟傍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送闵寿卿隐武夷","p":"","d":"明代","a":"徐熥","c":["世人游武夷，往往思卜宅。一出清溪谢白云，山灵无计留双屐。", "始信人间事可哀，幔亭佳宴不重开。浮生只爱红尘老，人世难逃白发催。", "怜君弃家经几载，服食还丹颜未改。已识仙都注有名，尚疑遗蜕函犹在。", "自入闽天誓不还，因缘合在武夷山。独携一杖千峰里，閒放孤舟九曲间。", "此山元是神仙窟，接笋天游双崒嵂。玉女妆残峰顶霞，金鸡叫落滩头月。", "君今筑室此中居，永绝尘缘与世疏。回视形骸同粪土，能将神气返空虚。", "我也行年三十几，半生踪迹多城市。入药空烧九转红，著书枉识关门紫。", "海外徒闻更九州，此身期伴赤松游。何时重预曾孙宴，同醉仙人十二楼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读黄泰泉陈白沙两集 其四","p":"","d":"近代","a":"李洸","c":["困眠饥食滞芳时，往事凄迷恋酒卮。倘许焚香趋静境，无思无虑对枯棋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题邵益斋白云诗卷二绝 其二","p":"","d":"元代","a":"唐桂芳","c":["黄山我号白云翁，云涨千山与画同。试问云山何所似，故人未老一丝风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"种松二首 其一","p":"","d":"宋代","a":"张嵲","c":["寿张种漆将为器，假用终能及里闾。我植青松期偃盖，苍然相对雪霜馀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游宝林招李簿梅尉","p":"","d":"宋代","a":"杨杰","c":["东郭乞求闻晓鸡，篮舆乘兴过泾溪。冰开波面白玉碎，雪压竹梢青凤低。", "仙去空留鍊丹井，境清疑有辟尘犀。子真太白曾孙在，飞棹何妨到水西。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题小景","p":"","d":"明代","a":"刘基","c":["江头日日起西风，江树惊寒叶变红。", "天澹云低何处雁，一行飞下荻花中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"用前韵酬陈判官","p":"","d":"宋代","a":"曹勋","c":["刺桐花发照人明，三看薰风舞绛英。", "海近鱼肥随米贱，山高溪净照人清。", "久闻射策先黄甲，何意栖鸾尚赤城。", "顾我婆娑老林下，看君事业映簪缨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满江红 清江风帆甚快，作此，与客剧饮歌之","p":"","d":"宋代","a":"范成大","c":["千古东流，声卷地、云涛如屋。横浩渺、樯竿十丈，不胜帆腹。", "夜雨翻江春浦涨，船头鼓急风初熟。似当年、呼禹乱黄川，飞梭速。", "击楫誓，空惊俗。休拊髀，都生肉。任炎天冰海，一杯相属。", "荻笋蒌芽新入馔，鹍弦凤吹能翻曲。笑人间、何处似尊前，添银烛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"己亥中元陪祀山陵道中奉和杨学士先生韵（四","p":"","d":"明代","a":"李东阳","c":["十年三赴四陵朝，又逐诸公一举镳。", "龙尾道瞻回辇近，马蹄尘送入山遥。", "天开野色川原净，日出城头雾雨消。", "无数晚花秋树里，未须风物向春饶。¤"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病减枕上五首 其五","p":"","d":"宋代","a":"陈渊","c":["三釜承亲计已疏，万钟行道竟何如。安贫未赴阇黎饭，信命宁裁宰相书。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"将往琼南口占别司香者 其五","p":"","d":"明代","a":"屈大均","c":["多栽香子傍芙蓉，家有香田即素封。欲向东官金桔岭，尽将妻子作香农。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三月廿六日夜同侄端臣端杲观异书效李长吉体","p":"","d":"宋代","a":"范浚","c":["杨花乱落青春暮，燕拂帘旌傍人语。缥壶买酒洗春愁，回风落日檐花舞。", "赫蹄断烂千载书，青灯照字惊蟫鱼。冬烘老生时自哂，安用盘盂学田鼢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"李简夫知易用其父韵见贻且示和陶一编并和二章答之 其二","p":"","d":"宋代","a":"孙应时","c":["閒中笔墨故相宜，遣兴由来不厌诗。日仰慈颜长自爱，年方强仕莫言衰。", "新来定得安心法，此事还胜未病时。肯共切磋须我辈，独无琼玖报先施。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏中庭幽兰寄曾日彰练声伯","p":"","d":"明代","a":"王汝玉","c":["中庭有幽兰，贞独信为美。移根自泽阴，托荫近堂趾。", "敷叶恒披绿，抽茎复攒紫。桃李讵能方，荇茝或可比。", "纫之佩服间，足以赠君子。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"遐方怨 其四","p":"","d":"清代","a":"周岸登","c":["麟髓簏，獭脂筒。剪发涂眉，脱簪非关秋扇风。却怜金井坠芳桐。", "绕阑悲露草，两心红。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"管解元欲见巽伯","p":"","d":"宋代","a":"韩淲","c":["春秋经世志，问取大愚家。盘折入举文，唾手为国华。", "从容试讲评，三传宁浮誇。南渡今百年，中外义非赊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"中秋夜月速儿曹赴任洪西","p":"","d":"明代","a":"区越","c":["直辗冰轮上碧天，了无云物翳光圆。南楼兴动不知老，白酒香腾正满筵。", "丹桂拂天真影见，霓裳炙口竟谁传。痴儿未了公家事，明日沧江送画船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄酬曹伯玉因以招之","p":"","d":"宋代","a":"王安石","c":["寒鸦对立西风树，幽草环生白露庭。", "清坐苦无公事扰，高谈时有故人经。", "思君异日投朱绂，过我何时载渌醽。", "及此江湖气萧爽，最宜相值倒吾瓶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"门有车马客行","p":"","d":"明代","a":"史鉴","c":["翩翩南回雁，哀鸣向秦飞。", "道路非不远，乘时安可违。", "门有车马客，驾言归故庐。", "关中天下险，山河尽城池。", "云胡失保障，匈奴忽来兹。", "传闻入北地，民物多伤夷。", "岂无霍去病，能不以家为。", "胡来闭城守，胡去扬兵追。", "如何秦陇间，到处成疮痍。", "凭君谢诸将，全躯岂男儿。", "努力事扫除，勿令蔓且滋。", "请看麒麟阁，功臣亦人为。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"道无情 秋阳观作，答宣德州道友请","p":"","d":"元代","a":"尹志平","c":["深谢将书来请。才到西岩春令。百鸟正喧呼。乐无余。道众满川和气。醮罢更看天意。缘契合虚谷。任西东。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大雪同杨景韩程子敬登寺楼","p":"","d":"宋代","a":"程公许","c":["雪中佳士集，同倚寺楼看。", "晁荡迷沧海。空明迫广寒。", "重城和气浃，万井语声欢。", "瑞接三冬白，忧宽一寸丹。", "渔船寻剡曲，战马渡桑乾。", "天意俱悭与，无氈分冷官。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和张秘丞灯夕韵四首 其二","p":"","d":"宋代","a":"刘克庄","c":["牧守二期方奉计，末期君已得民和。不愁米送官仓少，但怪莲开陆地多。", "座客共沾眉寿酒，厩人预戒早朝珂。诸公若问龙钟叟，为说腰镰自刈禾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"饮酒二十首同苏翰林先生次韵追和陶渊明 其三","p":"","d":"宋代","a":"晁补之","c":["陶公群于人，而无人之情。诗岂世外语，世语不可名。", "东坡怜此翁，同调但隔生。形光来户屦，真处人不惊。", "得酒自醒醉，放意无亏成。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题壁","p":"","d":"唐代","a":"崇圣寺鬼","c":["禁烟佳节同游此，正值酴醿夹岸香。", "缅首十年前往事，强吟风景乱愁肠。", "策马暂寻原上路，落花芳草尚依然。", "家亡国破一场梦，惆怅又逢寒食天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题刘伯山蕃殖图二首画禾黍稌菽麦 其一","p":"","d":"宋代","a":"杨万里","c":["老子平生只荷锄，误携破砚到清都。归来荒尽西畴却，愧见刘家蕃殖图。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"留题绩溪","p":"","d":"明代","a":"程敏政","c":["绩溪东南来，遥望古仁里。中有程氏居，隐隐入桑梓。", "缅怀道轩翁，吾宗百世士。眼中聚爱楼，遗训耿在耳。", "三男如鼎足，等是克家子。崇坊瞰村巷，华构照山址。", "春霖久初晴，一榻为予启。登堂父兄乐，拥户儿童喜。", "开奁扣宗牒，张燕出肴醴。夜下灯火明，语笑未能已。", "忆当百年前，同饮相湖水。今夕乃何夕，会晤复自此。", "聚散安可常，保族在崇礼。丁宁愿同人，契谊笃终始。", "明发川途长，思情两难拟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"捉搦歌四首 其三","p":"","d":"明代","a":"欧必元","c":["铜青衫子衬杏黄，阿姑二八同烧香。供俸世尊礼佛王，愿得勿嫁如兄郎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"渡开都河","p":"","d":"清代","a":"易寿松","c":["高城绿柳接清波，破晓停车唤渡河。牧野帐分平野阔，沙痕岸剩隔年多。", "此生东去乘槎近，稳坐中流击楫歌。西域兵看银汉洗，海门戍鼓又鸣鼍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"阅丁知县传","p":"","d":"明代","a":"陈献章","c":["模样从看拙，丹青只写真。乾坤如许大，具眼岂无人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"汤时仲小林居","p":"","d":"明代","a":"南洲法师","c":["昔年曾过小林居，门下萧萧古木疏。", "床雨独看先世笏，帐烟还读外家书。", "杏花红褪春犹在，菜甲青稀晓自锄。", "回首长洲多茂草，几时清啸落樵渔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"义舟","p":"","d":"明代","a":"徐庸","c":["巨舟平压水中天，一挂风帆稳济川。沧海自深入自渡，不教来往费青钱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"翟簿示似中秋高作命意着语殆与商素争清读至","p":"","d":"宋代","a":"史弥宁","c":["歌子秋风叠，诵子明月篇。", "信有习鉴齿，胜读书十年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"明发西馆晨炊蔼冈四首","p":"","d":"宋代","a":"杨万里","c":["何须名苑看春风，一路山花不负侬。", "日日锦江呈锦檨，清溪倒照映山红。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"淮阳公署遣怀二首 其一","p":"","d":"明代","a":"王世贞","c":["空馆云常合，荒阶叶易平。风霜私俗吏，天地狭狂生。", "啸引双长铗，愁依一短檠。惜眠晨鼓罢，散食午禽鸣。", "刀笔难违世，文章肯近名。翛然竟何语，奇思独能惊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"客中四时词 其三","p":"","d":"明代","a":"黄仲昭","c":["荷落一池风，菊开三径雨。无穷离别怀，况听寒虫语。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"写昆崙万松图寿一昆老人八十","p":"","d":"明代","a":"张萱","c":["我闻昆崙在西极，天地之脐神仙国。三城五级十二门，鹤驭鸾骖千万亿。", "握契仙人好远游，一朝掉臂黄林陬。开明奔命陆吾遁，却插孤根闽海头。", "冯夷昼立天吴语，巨鳌欲戴昆崙去。老人玉杖试一挥，昆崙永作闽天柱。", "万岁山前紫气浓，老人高卧昆崙峰。偓佺拊背授真诀，独种云间十八公。", "万斛明珠千岁实，忆昔馈尧尧不食。春风日长虬龙枝，擎霄接汉皆千尺。", "兄为栋兮弟为梁，丹青矩矱充明堂。葱峦锦柏亦琐屑，寒河星柘徒夸张。", "明堂孔阳圣人喜，为问老人身姓李。三锡龙章爵大中，地上神仙郁华子。", "杖履烟霞八十春，少微夜夜烛昆崙。不往人间役徐甲，不从柱下作周臣。", "一日餐一松，一松巢一岁。天地为等期，青青长不改。", "弧悬正值小春阳，木公金女纷翱翔。金銮乍祝齐天寿，锦里还飞爱已觞。", "罗浮山下金门隐，遥向南天称子姓。欲随青鸟献珍图，且吮綵毫开异境。", "何日堂前问大还，侧身怅望昆崙山。万头青犊留闽海，李耳原来未出关。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丑奴儿令 其一 两大人之黔中，鼎以试事留湘，赋感","p":"","d":"清代","a":"易顺鼎","c":["膝前长跪魂如醉，感上心头。悲上心头。泪到湘天日夜流。", "照人一样关山月，亲在黔州。儿在潭州。祝汝团圞万古秋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"松芝图","p":"","d":"清代","a":"了亮","c":["悬厓一株松，经霜复经雪。倚涧五茎芝，日月精华结。", "生成栋梁材，品格自高洁。异草本灵丹，服之增颜色。", "援笔入丹青，足称两奇绝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"陶祠","p":"","d":"清代","a":"韩锡胙","c":["层叠山难画，渊明却赋归。兴因新秫酒，家有旧柴扉。", "祠瓦藤穿漏，碑书斧砺稀。滔滔江水阔，谁觉折腰非。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"苏度支挽诗 其一","p":"","d":"宋代","a":"刘攽","c":["翰墨兼能事，功名自壮图。云霄曾几许，意气即通衢。", "埋玉情何已，修文理不诬。敢忘徐稚礼，絮酒望江湖。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晓经潘葑","p":"","d":"宋代","a":"杨万里","c":["油窗著雨光不湿，东风忽转西风急。", "蓬声萧萧河水涩，牵船不行人却立。", "雨中蒿师风堕笠，潘葑未到眼先入。", "岸柳垂头向人揖，一时唤入诚斋集。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂诗绝句十七首 其十七","p":"","d":"宋代","a":"梅尧臣","c":["河畔有钓翁，团泥为瓮缶。坐想秦人声，思倾杜陵酒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乾宁八景 其五 丰台夕照","p":"","d":"明代","a":"张缙","c":["寂寞荒台夕照边，居人犹自说丰年。太平气象何曾减，禾黍芃芃满大田。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"暗香 延平王祠古梅，相传王时物也","p":"","d":"清代","a":"梁启超","c":["东风正恶。算几回吹老，南枝残萼。水浅月黄，长是先春自开落。", "二百年前旧梦，早冷却栖香罗幕。但剩得片片倩魂，和雪渡溪彴。", "依约。共瘦削。便撩乱乡愁，驿使难托，鸾笺罢写。闲杀何郎旧池阁。", "休摘苔枝碎玉，怕中有归来辽鹤。万一向寒夜里，伴人寂寞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"英德道中","p":"","d":"宋代","a":"文天祥","c":["海近山如沃，杼深屋半芜。", "乾坤正风雨，轩冕总泥途。", "自叹鸢肩薄，谁怜鹤影孤。", "少年狂不醒，夜夜梦伊吾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"莺啼序","p":"","d":"近代","a":"宋词","c":["端阳匆匆过了，正满城风雨。佳期近，此时情绪，都在眉头心底。", "真如梦，那堪回首，悲欢十二年间里。算而今尝尽，人间辛酸滋味。", "浦口斜辉，石城春晚，家门何处是。梧桐旧院依然在，楼上灯窗笑语。", "人去也，莫敲绣户，料空锁房中燕子。念此间，几度欢歌，几番悲泪。", "拭乾泪眼，暂抛离愁，后约为君许。因不肯，低头忍辱，蜗居淮海，风雷激起，中年意气。", "功过莫测，投阁未成，囚车示众金陵市。生和死，已作等闲视。", "偏偏难舍君情，未了枕边虚誓。春恩当日，宠柳娇花，记舞筵歌席。", "今相见，洗净铅华，衰颜残鬓，囚窗买粥，蓬头挑水。", "隔楼遥望，咫尺天涯，南农真是伤心地。料从此，团聚无期矣。", "茫茫来日方长，人还不老，心犹未死。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天（同前）","p":"","d":"宋代","a":"向子諲","c":["说著分飞百种猜。泥人细数几时回。风流可惯曾孤冷，怀抱如何得好开。", "垂玉箸，下香阶。凭肩小语更兜鞋。再三莫遣归期误，第一频教入梦来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大田道中怀孟担","p":"","d":"明代","a":"佘翔","c":["几湾流水咽涓涓，五虎山青马首悬。欲访故人过峡口，南鸿犹自带风烟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感咏二首 其一","p":"","d":"近代","a":"单人耘","c":["茑萝绿蒙茸，垂曳书窗外。清晨微雨来，飘洒云如黛。", "纤尘湿不起，寸心稍无碍。天地一浮沤，何由生嗔爱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送高炳如倅天台","p":"","d":"宋代","a":"喻良能","c":["高侯吾所畏，学问觑壶奥。秋水莹精神，春华丽词藻。", "三馆朅来游，两鬓青未皓。何心玩岁月，刻意事探讨。", "二志既崇成，八书可偕考。乌台伫风采，纶闱须典诰。", "引疾遽有祈，勇退一何早。丹丘非大名，泥轼仅小好。", "会看有诏追，岂必俟身到。行矣即轻安，恺悌神所劳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"金陵别施平叔秋官","p":"","d":"明代","a":"李时行","c":["知己难为别，相携白下门。斜阳江上树，野水驿边村。", "旧业归心在，清时直道存。凄凄霜月夜，尊酒共谁论。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题三峡堂","p":"","d":"宋代","a":"张演","c":["群山危立接云天，一水东朝会百川。泱漭堪舆无此壮，崔嵬疏凿定何年。", "千秋跃马兴亡梦，一点飞凫上下船。时有刚风来浩渺，起予高兴九秋边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丰干赞","p":"","d":"宋代","a":"释绍昙","c":["加纱挂头何规矩，眼要看经不识字。", "差般差样制风颠，硬作斑猫骑作虎。", "道是弥陀，有何本据。", "闾丘太守，似苏州子。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次徐监簿韵贺吴侍郎新第落成 其一","p":"","d":"宋代","a":"释善珍","c":["碧落仙人上界还，手携奎壁下天关。百年第宅复金盏，万卷图书围玉山。", "霜压老槐龙卧壑，春催红药凤衔环。时危报主诗人志，好爱苍生莫爱闲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"小重山令 与保庵话扬州湖上旧游","p":"","d":"清代","a":"杜文澜","c":["十载虹桥买醉时。携尊梅树下，说相思。三生杜牧恨来迟。", "红楼外，莺老绿杨枝。", "愁弄玉参差。销魂春去也，鬓丝丝。惜花心事已全非。", "西风怨，惟有白鸥知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"京师九日城南黑窑厂登高","p":"","d":"清代","a":"周远","c":["愁思天涯九日晴，凭高闲望夕阳明。天清万丈秋潭影，风急三关落木声。", "双阙参差连御苑，乱山合沓入边城。悬军绝幕思飞将，闻道河西已厌兵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春早二首 其一","p":"","d":"金朝","a":"段继昌","c":["鱼儿水汎鸭头绿，野马尘飞羊角风。西崦山家篱落背，杏梢初见一分红。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"暇日同郑以孝游定光庵坐志喜亭上以池清龟出曝松暝鹤飞回为韵各赋十首用纪一时之清兴云 其九","p":"","d":"明代","a":"唐文凤","c":["倚阑兴未尽，坐久心忘归。树远碍云出，鸦回背日飞。", "地接市喧近，境留尘迹稀。朗吟下山去，松风凉葛衣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵濮十太尉咏知宗牡丹七绝 其二","p":"","d":"宋代","a":"王十朋","c":["月陂春色满花枝，国色天香照雪肌。当日栽陪恐无地，如今谁保旧园池。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"冯大参汝言出饯临汾驿留别","p":"","d":"明代","a":"谢榛","c":["归鸿不失洞庭群，樽酒天涯此别君。残岁冰霜仍道路，早春书剑又河汾。", "驿亭驻马淹行色，官柳啼鸦送落曛。二十年来频聚散，那堪白首叹浮云。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和前人重九日寄","p":"","d":"宋代","a":"赵抃","c":["丁字溪流甚箭奔，忍看行色夕阳村。三吴望远迷烟棹，九日登高泥酒樽。", "诗得琼瑶今有意，感充怀抱更无言。归欤一曲桐江好，西北通宵欲梦魂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题峻极下院列岫亭诗 其二","p":"","d":"宋代","a":"李廌","c":["山色满亭亭倚空，与君俱在画图中。解道龙腾青壁断，令人却忆漫浪翁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过麻山寺","p":"","d":"当代","a":"李达","c":["逐人山月暮云端，乔木村墟萤火寒。野寺心香桂丛发，步檐天乐鸟声阑。", "藜床卧病何须药？蓬鬓随风莫正冠。已过斋时仍乞饭，摘蔬蒸栗尽清欢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"续催送日鼓谣（邓侍郎崖山作催送日鼓谣文丞","p":"","d":"明代","a":"汪德钧","c":["冬冬晨鼓催，目注东方白。", "日华欲动月无辉，杀气冲天云血色。", "坎坎暮鼓击，日没崦嵫黑。", "朔风吹海毒波翻，旄头错落光芒出。", "日复夜，夜复日，日夜相催鼓声急。", "枕戈不寐食忘餐，力不能支仰天泣。", "主辱臣死古义存，弟妹瓢零敢遑恤。", "整旗收队决雌雄，黄龙孰遣横江中。", "风雷昼晦天地变，君臣不见崖山空。", "至今涛声吼朝夕，半为猿鹤半沙虫。", "当时豪杰能几子，千载不泯惟孤忠。", "催日鼓，送日鼓，调短意长歌愈苦。", "鲛人闻得泪成珠，踯躅白鹇惊堕浦。", "侍郎丞相家国同，当时戮力无尔汝。", "补天炼石竟无功，空余五色神光吐。", "斯人斯作世岂多，合入青编照今古。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"蒋瑎","c":["谁知清淡者，冬月亦登临。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"缪燧为令得御书","p":"","d":"近代","a":"沙曾达","c":["居官定海廿馀年，泽遍黎民惠政编。宠锡御书珍翰墨，入祠名宦媲前贤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅花引 和赵平原催梅 天下同文","p":"","d":"元代","a":"卢挚","c":["绿华缥缈玉无痕。托清尘。拟招魂。放著篮与，懒倦到前村。笑抚高斋新树子，晚妆未，悠悠学梦云。竟日含情何所似，似佳人。望夫君。寒香细月空江上，会有春温。羞涩冰蕤，寂寞掩重门。交下横枝消息动，肯虚负，风流竹外尊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"罗汉洞","p":"","d":"宋代","a":"程公许","c":["中岩洞透牛头洞，后洞门从此处开。", "刹刹尘尘皆住处，胜游何必限天台。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送江陵刘县丞得多字 其一","p":"","d":"宋代","a":"项安世","c":["一语动愁思，良朋能几多。相持看鬓发，容易隔山河。", "旧学纷疑信，新功废琢磨。因君戒行李，令我悟蹉跎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"瓠岱里索题龙舟辞得十二绝 其二","p":"","d":"清代","a":"王坤","c":["居人夙好叶公龙，更与涛头写幻踪。钲鼓喧阗铙吹亲，短歌剧喜问吴侬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书酒家壁","p":"","d":"宋代","a":"范仲淹","c":["当垆一曲竹枝歌，肠断江南奈尔何。游子未归春又老，夜来风雨落花多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"陈氏园亭","p":"","d":"宋代","a":"李光","c":["花径微通竹径幽，暮年清赏在林丘。登临未觉三山隔，俯仰常随万壑流。", "乐土自应多乐事，闲身居此得闲游。酒杯棋局平生事，莫把枯肠数搅搜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次纲官王簿韵兼简伯潜二首 其一","p":"","d":"宋代","a":"廖行之","c":["江上晴光照眼浓，十分春色满城东。客怀何限湘波绿，漕事方殷汉粟红。", "雅有诗情添兴远，可无酒力破愁攻。舳舻早晚蒲帆稳，长啸东南万里风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"行路难 其五十一","p":"","d":"清代","a":"钱澄之","c":["老僧多病苦修偏，课诵行禅夜不眠。更荷慈悲留过客，为怜单被自装绵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南唐后主画竹引","p":"","d":"明代","a":"郑善夫","c":["君不见彭城彭奴元姓李，早入徐家称帝子。又不见九华山下齐丘生，晚入南唐作谋士。", "同时契合风尘里，草昧君臣若鱼水。淮北初收格斗尘，宫中漫得丹青理。", "升元阁上写墨竹，翠葆萧森凤毛起。手书珍重表恩殊，御墨淋漓湿桑梓。", "世代相催犹梦幻，金陵画饼宁复尔。帝王从古多好手，人物绚素无不有。", "前有殷武丁，物色惟传傅岩叟。后有宋道君，鹰犬骅骝歘飞走。", "丹青意气稍或别，治乱兴亡一回首。彭奴彭奴听我歌，淇水才贤本众多。", "但惜九华山，不似傅岩阿。吁嗟乎竹花零乱岁蹉跎，凤凰不来将柰何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"破虏凯歌二十四首","p":"","d":"宋代","a":"周麟之","c":["虏饿曾无一月粮，煮弦烧箭莫弃肠。", "南来本恃清河粟，不意偏师夜绝纲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"黑漆弩 其二 谢熊南沙跋帖","p":"","d":"明代","a":"杨慎","c":["月仪蠹简留君住。索靖是右军师父。笑藏真、酗酒狂僧，说甚龙蛇风雨。", "戏鱼堂、响榻重镌，莫道影留形去。熊朋来，鼎韵钟铭，鉴赏到、西台妙处。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵赵积中慈湖即事","p":"","d":"宋代","a":"王之道","c":["干戈九载予心哀，乱离谁复歌南陔。", "喜君父母老相守，调官仍逐金陵来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"百字令 登莫干山，夜黑风狂，清寒砭骨，率成此调","p":"","d":"清代","a":"吕碧城","c":["万峰泼墨，漾红灯一点，径穿幽筱。翠袖单寒临日暮，来御天风浩浩。", "湍瀑惊雷，筼筜戛玉，仙籁生云表。飞琼前世，旧游疑是曾到。", "昨日绮阁香温，宿酲犹殢，谁换炎凉早。争道才华多鬼气，占尽人间幽悄。", "侵入灵犀，冻馀冰茧，芳绪抽难了。驿程倦影，微茫愁入秋晓。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂三十二首 其二","p":"","d":"宋代","a":"释宗演","c":["空病有为药，有病空为药。空有两俱非，药病何处著。", "无处著，万里秋风飞一鹗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梦臣惠潘谷墨 其二","p":"","d":"宋代","a":"邹浩","c":["潘谷卖墨时，吕翁尝过之。指授长生诀，举世那能窥。", "但称众墨中，谷墨最珍奇。一旦内药成，解去逃喧卑。", "忽忽期月后，来与丹元期。夜饮晓分手，丹元初不知。", "仍留墨数片，属元付其儿。有儿旋其门，顶白元惊疑。", "细诘所以然，始知谷如斯。谷仙今几年，谷墨今在兹。", "静言人间世，舟壑常密移。朱颜兀槁木，绿发垂素丝。", "借令富贵极，毕竟将奚为。谷乎真可人，得墨吾得师。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄懒庵","p":"","d":"宋代","a":"刘子翚","c":["山暝雨连夕，今晨天气清。", "遥怀懒庵人，高卧掩柴荆。", "幽寂性所嗜，萧然寄平生。", "惟应田叟来，对床话躬耕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜话","p":"","d":"清代","a":"沈琮宝","c":["竹篱西畔豆棚东，竟夕盘桓兴自同。为爱清言时娓娓，翻疑夜漏太匆匆。", "几人留恋三更后，千古兴亡一席中。月落参横催曙色，闲谈水乳喜交融。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"疏影 秋柳","p":"","d":"清代","a":"李良年","c":["旗亭陇首。正新霜乍点，斜日风骤。一片秋声，几树萧疏，惊心十里津堠。", "行人欲折还教住，为记得、别离时候。洒渭城、朝雨如烟，曾向画桥分手。", "何处无情玉笛，忍教一夜里，吹堕江口。系马无人，认取寒枝，惟有晚鸦依旧。", "相思最是鸳鸯渡，应渐冷、碧纱窗牖。纵待得、来岁春还，只恐那人腰瘦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登轮感赋","p":"","d":"近代","a":"李叔同","c":["感慨沧桑变，天边极目时。晚帆轻似箭，落日大如箕。", "风倦旌旗走，野平车马驰。河山悲故国，不禁泪双垂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"白云上人精舍寻杼山禅师兼示崔子向何山道上人","p":"","d":"唐代","a":"皎然","c":["望远涉寒水，怀人在幽境。为高皎皎姿，及爱苍苍岭。", "果见栖禅子，潺湲灌真顶。积疑一念破，澄息万缘静。", "世事花上尘，惠心空中境。清闲诱我性，遂使肠虑屏。", "许共林客游，欲从山王请。木栖无名树，水汲忘机井。", "持此一日高，未肯谢箕颍。夕霁山态好，空月生俄顷。", "识妙聆细泉，悟深涤清茗。此心谁得失，笑向西林永。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大雪","p":"","d":"宋代","a":"孔武仲","c":["穷年阙雨谩悲歌，喜见凌晨雪意多。", "天上乱花初剪玉，楼头密影已翻波。", "轮蹄著路织尘断，庭宇无风凛气和。", "寄语云师勤覆护，莫令光景漏银河。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"栽松","p":"","d":"元代","a":"行端","c":["钝钁横肩雪未消，不辞艰步上岧峣。等閒种得灵根活，会看春风长绿条。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"将别故居迁小山堂之西偏感赋 其一","p":"","d":"清代","a":"庄宇逵","c":["庭花晻薆树扶疏，惆怅西风别故居。一宿三如留客舍，此行犹自爱吾庐。", "嬉游少日情无限，歌哭中年泪有余。易衍克家书肯构，孤儿心事痛何如。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"木兰花慢 武邑县王楫善居室，母俎氏出隆平","p":"","d":"元代","a":"王恽","c":["精彩如五六十人。教授马君向予方以善俗任责楫之孝养致乐，实有关於风化者，故作是词以付，俾来者庶有所劝焉烂云衢彩婺，和晓月，满庭闱。正梅粉香飘，林梢紫动，淑景初迟。观津盛传王氏，道孝心、重见老莱衣。和气一家瑞霭，慈颜九十柔仪。香烧静院趁朝晖。未省杖扶持。纵德厚流长，遐龄能健，此事应稀。婆娑绿萱堂背，爱一竿、苍竹六孙枝。照映西山秀色，年年翠点修眉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"放歌行答从弟墨卿","p":"","d":"唐代","a":"李颀","c":["小来好文耻学武，世上功名不解取。虽沾寸禄已后时，", "徒欲出身事明主。柏梁赋诗不及宴，长楸走马谁相数。", "敛迹俯眉心自甘，高歌击节声半苦。由是蹉跎一老夫，", "养鸡牧豕东城隅。空歌汉代萧相国，肯事霍家冯子都。", "徒尔当年声籍籍，滥作词林两京客。故人斗酒安陵桥，", "黄鸟春风洛阳陌。吾家令弟才不羁，五言破的人共推。", "兴来逸气如涛涌，千里长江归海时。别离短景何萧索，", "佳句相思能间作。举头遥望鲁阳山，木叶纷纷向人落。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"豪彘赞","p":"","d":"魏晋","a":"郭璞","c":["刚鬣之族，号曰豪彘。毛如攒锥，中有激矢。厥体兼资，自为牝牡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"拟古","p":"","d":"宋代","a":"苏泂","c":["汉光昔未遇，颇为兄嫂欺。", "谁知韩王信，本是屠沽儿。", "他时筑将坛，意气帝者师。", "中兴屏新莽，长剑诛赤眉。", "皇天生一物，大小随其资。", "倒令饥与寒，何以生育为。", "永言观厥成，圆璧殊方圭。", "天意定不尔，变化应须时。", "少小弄文翰，把笔能哦诗。", "十五学缀文，如茧中抽丝。", "青云付达官，十九名新知。", "南辕异燕路，鄙笑无挈提。", "甘心穷阎中，疏食黄瓜虀区区蠹鱼习。", "槁死不可医。闲斋秉微尚，", "高视圣者师。谩言苦如荼，", "谁信甘如饴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"成都试飞","p":"","d":"当代","a":"魏新河","c":["身共浮云作意飘，江山巴蜀望中遥。横江半寸如毛发，知是成都万里桥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"与契兄","p":"","d":"宋代","a":"赵蕃","c":["因怀碧云友，发兴青林端。", "要尽深幽趣，浑忘下上难。", "泉声流咽绝，松韵响高寒。", "久作庐山别，疑从梦境看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"用寄璧上人韵寄范元实赵才仲及从叔知止兼率山伯同赋","p":"","d":"宋代","a":"吕本中","c":["故人瓶锡各西东，吾道从来冀北空。病去渐于文字懒，南来犹觉岁时公。", "江回夜雨千岩黑，霜着高林万叶红。政好还家君未肯，莫教惭愧北窗风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望罗浮柬王李二君二首 其一","p":"","d":"明代","a":"林大春","c":["高标出岭外，特地起金莲。岱岳连沧海，峨眉入洞天。", "俯看朝日出，侧听夜河悬。倚棹时凝望，玉京飞曙烟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋日咏刀","p":"","d":"清代","a":"玄烨","c":["七宝刀光耀斗牛，建章佩带向初秋。清流越砥方知力，截兕剸鲸断不愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和薛田察院咏雪三首","p":"","d":"宋代","a":"魏野","c":["七字空吟六出花，与君无酒祇烹茶。", "门前俱绝行踪迹，还似袁安卧在家。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天（母侯置酒南教场赏芙蓉）","p":"","d":"宋代","a":"陈耆卿","c":["莫惜花前泥酒壶。沙场千步锦平铺。将军闲试临边手，按出吴宫小阵图。", "清露里，晓霜馀。娇红淡白更怜渠。人间落木萧萧下，独倚秋江画不如。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉制文武诗 其六","p":"","d":"明代","a":"徐溥","c":["覆载中存报主身，庙堂须用读书人。民胞物与皆吾分，一视应同万里仁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"步云鞋 本名软翻鞋赠玄真观单姑等献履鞋","p":"","d":"元代","a":"王丹桂","c":["幸遇教风开。和气洽吾怀。玄真清众总仙才。志谦和、恭顺垂慈惠，殷勤献，步云鞋。", "妙手巧剜裁。珠宝砌双腮。一回朝礼蹑坛台。待他年、真行真功满，超尘世，赴蓬莱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"沁园春 小斋开同心兰一枝，为赋此解","p":"","d":"清代","a":"易顺鼎","c":["草红心耶，花素心耶，同心此兰。正倚篁幽泣，邀回露眼，窥萝靓笑，对亸风鬟。", "何处神君，旧家儿女，一碧湘魂欲化烟。东皇力，让灵均今日，清艳能兼。", "紫钗敲韵珊珊。漫分付、笼鹦说晓寒。尽捧当怨雨，矉原非效，印来香月，梦不成单。", "秋士年华，春人影事，从古双修福慧难。真开也，算相思北渚，称意西天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杭州探梅历游超山西泠烟霞洞灵峰以中有万斛江南愁为韵 其二","p":"","d":"近代","a":"黄浚","c":["空山晚吹香，松竹导清黝。思当如旸台，绣谷奄群有。", "寺门两亩花，宋树以石守。喧寂趣终殊，梅杏非夷丑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵高缙之二首 其一","p":"","d":"宋代","a":"陈造","c":["能事馀千牍，幽期自一丘。向来书襞积，不疗客漂流。", "小挹苏耽鹤，同歌宁戚牛。几时诗酒社，相属话天游。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南归寄乡旧 其九","p":"","d":"明代","a":"陈献章","c":["出处有分付，将非人所能。君看飞鸟辈，谁不顾高腾。", "放意三杯酒，留情半夜灯。韦丹非俗吏，灵澈自高僧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉题少保张公曲阿别墅二首 其二","p":"","d":"金朝","a":"王寂","c":["钟湖亭下水淙淙，绿野平泉未易双。十里藕花红步障，一轩松荫碧油幢。", "洛中独乐有司马，天下不名知曲江。纸尾欲烦贤宅相，雨蓑添我坐篷窗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"揭天谣九首 其一","p":"","d":"明代","a":"周玄","c":["巨灵吹空南斗死，鬼哭如云学流水。桂阑天影白鹤秋，兔光斜坠三泉里。", "泉宫暗虫寒草根，土灯燃露絓黄昏。铁心九回滴秋血，三十六帝闻俱吞。", "帝遣双童去不返，楸梧参差牧马苑。青烟一点吹六龙，芙蓉吐光海波浅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂兴三十九首 其二十九","p":"","d":"宋代","a":"张镃","c":["圣狂霄壤分，其端在一念。去恶向忠义，如病用良砭。", "方贻害于人，蛟虎并凶燄。及其惩艾馀，大节秉无欠。", "卓绝补过功，炳炳照铅椠。乃知春秋意，恶恶待终厌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"燕居","p":"","d":"明代","a":"张元凯","c":["衡门聊偃息，泌水可忘餐。黄鸟林中听，青山江上看。", "云流石几净，花落竹房寒。短发偏宜散，何须制箨冠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送秦炼师归岑公山","p":"","d":"唐代","a":"李群玉","c":["紫泥飞诏下金銮，列象分明世仰观。北省谏书藏旧草，", "南宫郎署握新兰。春归凤沼恩波暖，晓入鸳行瑞气寒。", "偏是此生栖息者，满衣零泪一时干。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送韩一初赴马万户府参议","p":"","d":"元代","a":"周霆震","c":["才俊宜从幕府升，四郊何日保安宁。连营未报休传箭，策马何嫌出戴星。", "苦战城壕霜月白，屡残村落野烟青。军民甚有关心处，佐政行看刃发硎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题九马图","p":"","d":"明代","a":"倪岳","c":["穆王八骏名天下，此马雄瑰岂其亚。渥洼夜堕房星精，神物应随牝龙化。", "纤离騄駬少为贵，三十六蹄更堪诧。想当阊阖辟清晓，霓旌队引銮和驾。", "朝回初遣脱金羁，呈了曾看覆黄帕。天厩深严日正长，奚官出牧乘閒暇。", "晴堤水满柳阴森，芳草蒙茸犹可藉。长嘶深浴各有适，俊骨奇姿本无价。", "祇今承平息边燧，戎垒征鞍不须跨。长嗟健步何由骋，骐骥驽骀等衰谢。", "王良伯乐会有合，足下风云生叱咤。追电终轻万里程，直历蓬瀛蹴嵩华。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题唐十八学士图二首 其二","p":"","d":"宋代","a":"赵佶","c":["儒林华国古今同，吟咏飞毫醒醉中。多士作新知入彀，画图犹喜见文雄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"复次漫兴前韵八首（录四）","p":"","d":"明代","a":"钱谦贞","c":["全袪滓秽长清虚，闻道神仙似我臞。", "颦丑谩劳西子笑，力绵休学北公愚。", "携锄鏚石栽松子，乞竹编笼养鹤雏。", "容膝易安能自审，有人蓬户与桑枢。¤"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和昙颖师四明十题 其二 龙隐潭","p":"","d":"宋代","a":"梅尧臣","c":["老龙恋潭窟，不雨亦不云。吐涎出溪滑，吹腥隔林闻。", "疾雷驱未去，鱼鳖竞纷纷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂咏 其二","p":"","d":"宋代","a":"罗公升","c":["胡羯宁知分，中原欲并驱。设兵生建武，堪与赤眉俱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"古意 其一","p":"","d":"明代","a":"申佳允","c":["纤纤弄玉盆，月挂垂杨树。盆中影似郎，几回捉不住。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蝶恋花 冬日得国内友人书，道时事甚悉，怅然赋此","p":"","d":"近代","a":"汪精卫","c":["雨横风狂朝复暮。入夜清光，耿耿还如故。抱得月明无可语，念他憔悴风和雨。", "天际游丝无定处。几度飞来，几度仍飞去。底事情深愁亦妒，愁丝永绊情丝住。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其二","p":"","d":"宋代","a":"韩缜","c":["唐蒙谕巴蜀，通道至邛僰。列郡徼西南，夷居半岩壁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"早寒","p":"","d":"清代","a":"曹锡宝","c":["策蹇凌霜坂，风高木叶乾。空山秋易老，绝塞气先寒。", "肃肃车徒静，迢迢鼓角残。幸依仙仗近，行路敢云难。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"阅韩芬男为李九倩书少年行","p":"","d":"明代","a":"苏景熙","c":["写字须写意，运笔须运神。韩生乍疑腕有鬼，岂知振动往往恒逼真。", "右军内擪故森严，大令外拓故疏朗。兰亭变转搆别体，洛神遒劲信真赏。", "遗迹至今几千载，六义八法依然在。谁能研精拨镫理，直与点画增光彩。", "宁为凌冬枯树，毋为重台使者。状如算子岂是书，宜先筋骨藏锋下。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"禅人并化主写真求赞","p":"","d":"宋代","a":"释正觉","c":["山林眉目，水月身心。", "雪何早而古岩棱，秋似先而寒潭深。", "机头绵绪，线尾金针。", "谁云道大兮自有知音。神静气清，", "心空眼明。诸尘中豁落，", "万像里峥嵘。去而随，", "来而迎。三世竖，", "十方横。风吹便倒须相信，", "恰恰谁曾与物争。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同外孙文九新春五绝句","p":"","d":"宋代","a":"苏辙","c":["雪覆西山三顷麦，一犁春雨祝天工。", "麦秋幸与人同饱，昔日黄门今老农。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"哈密送长节帅","p":"","d":"清代","a":"方希孟","c":["茫茫大碛四边秋，山满寒城雪满楼。一帜元戎千骑捧，月明笳吹下伊州。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谢薛省判寄惠鹤","p":"","d":"宋代","a":"魏野","c":["早辍仙禽寄逸民，年来亦似厌家贫。", "时时东望长鸣处，应忆朱门旧主人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"新秋瀛台杂咏 其三","p":"","d":"清代","a":"弘历","c":["竹蹊诘曲如诗读，湖石玲珑当画看。屧步不妨过半里，心舒雨后晓秋寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送张令同年赴岭南","p":"","d":"宋代","a":"杨杰","c":["滕王阁上正持杯，候吏先期过岭来。泽国暂抛三径菊，春风须寄一枝梅。", "昔年身到仁宗殿，同日鳞惊禹穴雷。万里青云有前约，莫因蓝绶叹尘埃。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉教和资中八景","p":"","d":"明代","a":"王绅","c":["雨馀山水放清辉，惊见轻岚上翠微。薄影渐因红日淡，馀氛犹逐白云迟。", "如绡漠漠笼僧寺，似雨霏霏护石池。底事往来岩壑上，欲随祥霭出明时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满庭芳","p":"","d":"清代","a":"何振岱","c":["尘境风烟，衰年情绪，消领怎遣人知。古愁今恨，休写向琴丝。", "挨得众喧小息，凡缘外、探点玄机。无须问，欢悲异趣，与世总相遗。", "栖迟。如我愿，孱躯蛰影，默自禁持。任飘零逝水，梦杳书稀。", "留取孤光内照，有寥寂、便是佳时。炉香好，余生寄托，冷暖足因依。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"正绣球花","p":"","d":"宋代","a":"顾逢","c":["正是红稀绿暗时，花如圆玉莹无疵。", "何人团雪高抛去，冻在枝头春不知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"光孝寺铁塔","p":"","d":"明代","a":"陈子升","c":["霸国禅关问大雄，南朝钟梵袭遗风。曾然劫火藏沙界，似立金茎表汉宫。", "狮座何人高说法，貂珰皈佛漫论功。檐铃不动诸天寂，薄暮愁看海日红。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"历城道中","p":"","d":"清代","a":"黄景仁","c":["北游忽不乐，东来揽齐岱。陆尽燕赵交，水送汶泗会。", "只有清济源，伏流隐支派。亦如古达人，心迹有时晦。", "群山尽朝岳，敢向不敢背。峨峨灵威丈，揖我青霞外。", "迓客遣片云，飞来若车盖。挥手暂相谢，冰雪迫徂岁。", "游倦思小休，胜济行未艾。寄语雪中花，石上劳相待。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"太常引 寿高丽王","p":"","d":"元代","a":"程文海","c":["沁园岁岁菊留芳。待此日、庆真王。金鼎燮和元。造寿域、同开八荒。河山带砺，一传千岁，地久与天长。晴日上扶桑。便先照、琼阶玉觞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送户部尚书贡泰甫开司闽中榷盐易米给京师 其二","p":"","d":"明代","a":"贝琼","c":["两隅未挣出师频，圣主经营伏老臣。天河转粟遥通蓟，腊月看花近到闽。", "道上豺狼应避马，山中猿马不惊人。公馀定有诗千首，好托边鸿寄蚤春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闻吕敬夫移居五首 其二","p":"","d":"元代","a":"郭翼","c":["詹尹何劳更决疑，衡门之下可栖迟。竹从少傅韦家觅，树向果园坊里移。", "翡翠小堂巢窄窄，鸥鶄近渚槛垂垂。主人一任悬徐榻，更拟风流醉习池。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三宿岩","p":"","d":"明代","a":"文徵明","c":["积石谁名达磨岩，花间古洞锁苍烟。何能桑下淹三宿，却探仇池自一天。", "古树腾蛟根束铁，春苔蚀雨翠连钱。只应曾见台城事，回首梁王又几年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题步瀛阁","p":"","d":"宋代","a":"邓肃","c":["玲珑画阁入鸿冥，隐约鸿冥入太清。", "紫气氤氲随步去，青霞杳霭逐行旌。", "桃花浪透三山近，龟角屏高七朵横。", "解逐梅仙在尘世，谁知尘世有蓬瀛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"野店多买花木瓜","p":"","d":"宋代","a":"杨万里","c":["天下宣城花木瓜，日华露液绣成花。", "何须堠子强呈界，自有琼琚先报衙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九日登尧山书事","p":"","d":"宋代","a":"夏竦","c":["满头黄菊鬓毛斑，曾议皇王对尔颜。", "今日临风轻霸迹，尧山应合胜牛山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"贺新凉 采石太白楼，用洪稚存、黄仲则两家集中太白墓原韵","p":"","d":"清代","a":"易顺鼎","c":["江月都愁老。何苦向南朝一带，照他凭吊。采石荒矶闲系艇，有客倚阑而眺。", "谁看见吴宫花草。楼影千年流不去，缓商量毕竟诗人好。", "须记取，醉中稿。", "狂吟那顾先生笑。为神州骚沉雅坏，特来相告。更问锦袍归水后，清气收还多少。", "可许我骑鲸三岛。如此江山浑寂寞，但风帆几点和沙鸟。", "怀古意，怎生了。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过金陵四首","p":"","d":"宋代","a":"苏泂","c":["老树前头柿叶红，又骑瘦马立西风。", "江山未必侬能认，却被江山认得侬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋兴九首 其三 拟韦应物","p":"","d":"宋代","a":"秦观","c":["坐投林下石，秋声出疏林。林间鸟惊栖，岂独伤客心。", "物亦有代谢，此理共古今。邻父缩新醅，林下邀同斟。", "痴儿踏吴歌，娅姹足讹音。日落相携手，凉风快虚襟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读史 其四","p":"","d":"宋代","a":"罗公升","c":["德光起龙沙，忽拔汴水帜。赭袍拜千官，始识皇帝贵。", "饮冰一何愚，剖腹有馀秽。可怜无知石，犹纪会同岁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"将别迪化登机口号","p":"","d":"当代","a":"秦鸿","c":["雪岭方传昔我来，青林红柳竞毰毸。天风又送蓬莱去，满注流霞溢此杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题屏间","p":"","d":"宋代","a":"刘宰","c":["野旷乾坤大，身閒日月迟。有生均自得，造物本无私。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"前后蜀杂事诗 其二","p":"","d":"清代","a":"张祥龄","c":["宦寺新颁建节符，天雄进得美人无。牙兵龙虎飞章到，为献秦州花木图。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"金陵杂兴二百首 其三十七","p":"","d":"宋代","a":"苏泂","c":["龙虎江山未改形，临高一目但青青。春风岂是无才思，不洗从来战伐腥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"被花恼 珍丛馆蔷薇","p":"","d":"清代","a":"苏穆","c":["小园竟日惜春归，芳意独留仙馆。万叶千条倚娇软。", "窗前最是，双双蛱蝶，衬舞和愁乱。康欲语，又斜晖，半庭纤影凌波卷。", "长记艳深时，曾赋香痕压檐绽。新娥谩绿，早怯东风，取次相吹散。", "问何人暗遣斗芳菲，欲作弄、柔红梦中幻。拌醉也、莫待飘零清泪盼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅雨","p":"","d":"宋代","a":"苏泂","c":["双飞蛱蝶情何厚，百啭仓庚韵可听。", "肯为螳蜋看黄鹤，忍从燕子乞蜻蜓。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"文溯阁","p":"","d":"清代","a":"金朝觐","c":["星斗焕天章，熙朝制作光。文昭灵宝瑞，书启酉山藏。", "玉检涵蓬观，金题拥墨庄。沿洄宗圣海，条理总皇纲。", "考义详于度，垂谋典以常。是尊天一阁，能益智千囊。", "工轶碑摹篆，劳嗤石作仓。薪传寻坠绪，逸事极穷荒。", "勒鼎功同禹，铭盘志比汤。留都思溯始，方策示无忘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"直夜二首 其一","p":"","d":"宋代","a":"杨亿","c":["月魄生宵晕，风乌送晚凉。飞蝇随镂管，浮蚁溢清觞。", "负郭春耕废，钧天晓梦长。玉签声未断，落宿半宫墙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"纵笔","p":"","d":"宋代","a":"陆游","c":["未说无功爵位叨，昔人所畏在功高。", "印如斗大宁常保，剑拄颐长秪自劳。", "酒社极知身可隐，猎场犹得气差豪。", "世间见透浑无事，狐貉安能诧縕袍！"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再用前韵谢吴竹修","p":"","d":"宋代","a":"陈著","c":["秃髡归阳羡，仙髯卧古藤。前贤成昨梦，后辈嗣谁镫。", "倾盖欣如故，吟坛得共登。春风吹相聚，聊此寄韦冰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"觅蠹椽","p":"","d":"宋代","a":"高登","c":["顾影低徊祇自怜，怕寒时耸作诗肩。全家食粥已数月，坐客无毡今几年。", "君劈槽烧当止酒，我和琴爨况无弦。雪中送炭从来事，况尔羁躬觅蠹椽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"冬至晚起枕上有怀晋陵杨使君 其一","p":"","d":"宋代","a":"范成大","c":["新衣儿女闹灯前，梦里庄周正栩然。骑马十年听晓鼓，人生元有日高眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"早过午桥口占（二首）","p":"","d":"明代","a":"陆容","c":["下马金门步晓凉，海云开白看东方。", "君王自有兴居节，不遣微臣一倒裳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉同尤延之提举庐山杂咏十四篇 其九 简寂观","p":"","d":"宋代","a":"朱熹","c":["高士昔遗世，筑室苍崖阴。朝真石坛峻，炼药古井深。", "结交五柳翁，屡赏无弦琴。相携白莲渚，一笑倾夙心。", "晚岁更市朝，故山锁云岑。柴车竟不返，鸾鹤空遗音。", "我来千载馀，旧事不可寻。四顾但绝壁，苦竹寒萧椮。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十三夕诸君重饯妓筵醉后再作长歌","p":"","d":"清代","a":"姚燮","c":["百年不争一筵短，心近何愁万山远。潮平帆挂人欲离，霜紧天高月将满。", "昨筵饯我城南家，女墙三更多悽鸦。含啼试袖蝶粉湿，剪烛开门萝叶斜。", "今夕高楼控溟渤，明峦如荷媚空阔。沙风笛底吹黄萚，云影樽前堕苍鹘。", "羁身在客难自豪，慨叹当歌那能遏？欢歌已使心不留，还作愁歌暗挑拨。", "诸君爱我如爱心，常恐过劳难自任。又恐一逸易驰逝，便欲置我腔中深。", "百回顾惜到今夕，我负诸君顿言别。明知兰约春可期，已使桃根泪同咽。", "泪亦不得止，歌亦未肯阑。北斗欲没霜柝残，樯乌哑哑催出关。", "寸腑茫茫复何有，为君更尽一杯酒。劳君拔赠插鬟花，算折旗亭可怜柳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪沙","p":"","d":"清代","a":"林少君","c":["麟篆知从九夜扪。诗王金诰佩随身。映梅争羡气氤氲。", "绣纸十番传虎仆，蒸云千首动龙宾。于今坛坫自推君。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"泛舟作河灯戏","p":"","d":"近代","a":"胡雪抱","c":["秋病恹恹百虑煎，偶随菱棹弄平川。灵犀闪烁驯妖夜，玉兔高寒浴魄天。", "云縠翠深飘冷梵，锦漪香重幻新莲。凭虚欲听湘弦去，菱叶纷纶却碍船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答河中梅龙图","p":"","d":"宋代","a":"刘敞","c":["龙池柳色锁春烟，故国风光此地偏。高下楼台浑浸水，往来车马自随船。", "举杯醉舞时相属，倚瑟悲歌忽怆然。安敢为文敌金谷，误烦求友赋新篇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舂夫","p":"","d":"宋代","a":"华岳","c":["秕糠粒粒裹真珠，玉杵舂来白有余。", "待问姮娥借金鼎，等閒令汝作蟾蜍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏梅五十首呈史尚书","p":"","d":"宋代","a":"释绍嵩","c":["梅萼才开已乱飞，清香时被好风吹。", "苦无疏影横斜句，空作主人惆怅诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"村市晓烟","p":"龙游八景","d":"宋代","a":"郑得彝","c":["微茫村市隐江湄，三两人家欲早炊。", "翠箔楼台烟半湿，不知红日上花枝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏史十五首 其十一 光弼","p":"","d":"明代","a":"陶安","c":["谋成后战战功成，持已庄严号令明。以少覆多称第一，凌烟阁上合图形。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"至正改元辛巳寒食日，示弟及诸子侄","p":"","d":"元代","a":"虞集","c":["江山信美非吾土，飘泊栖迟近百年。", "山舍墓田同水曲，不堪梦觉听啼鹃。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆昔花间相见后","p":"贺明朝","d":"五代","a":"欧阳炯","c":["忆昔花间相见后，只凭纤手，暗抛红豆。人前不解，巧传心事，别来依旧，辜负春昼。", "碧罗衣上蹙金绣，睹对对鸳鸯，空裛泪痕透。想韶颜非久，终是为伊，只恁偷瘦。"],"tags":["女子", "追忆", "思念"],"z":"","y":"注释 ⑴蹙（cù促）——收缩，这里指折叠后出现了皱纹。 ⑵裛（yì邑）——沾湿，浸染之意。 ⑶韶颜——年轻美丽的容颜。 ⑷恁（nèn嫩）——这样。","s":"","k":"诗"},
  {"t":"蔡州叶翰林寄示近诗次韵八首 其三","p":"","d":"宋代","a":"程俱","c":["往客霅溪上，舒娥几亏盈。深穷卞山境，胜概不可名。", "柴车逐公游，登皋复临清。夜投阿兰若，松窗待朝明。", "济胜剧许掾，评诗陋钟嵘。灵滋初可抔，龙箨忽已萌。", "斯游今几时，坐想飞泉鸣。尚应几杖间，隐隐金石声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"示儿","p":"","d":"宋代","a":"赵蕃","c":["我昔读书夜达晨，膏烛且尽继以薪。", "年来渐知得力处，箪瓢陋巷忘其贫。", "尔曹有身须自立，幸逃薪水共朝夕。", "不于文章自勤苦，长大始悔何益。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送王益谦之京二首 其一","p":"","d":"明代","a":"乌斯道","c":["笑看车马去堂堂，玩愒人间岁月长。文似健兵能力战，才如良贾只深藏。", "烟波一钓非无具，花柳孤村自有庄。沧海遗珠留不得，随龙飞起落清湘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"留题觉华岛龙宫寺","p":"","d":"金朝","a":"王寂","c":["传闻三山驾空虚，珠宫贝阙神仙都。茫茫弱水限舟楫，人迹不到如有无。", "平生点检江山好，秪有龙宫觉华岛。何年经创作者谁，兴圣帝师孤竹老。", "老人绝俗栖金沙，岁久喜舍来天家。悬崖架壑置佛屋，突兀殿阁凌烟霞。", "乃知造物开神异，故压祇园布金地。四顾鲸波翼宝岩，玻璃环拥青螺髻。", "我生自厌薰膻腥，坐觉两腋生清泠。夜凉海月耿不寐，几欲举手扪天星。", "明朝收帆落尘土，一梦回头散风雨。向令坡老此经行，想不愿为天竺主。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和景贤十一首 其八 读唐史有感","p":"","d":"元代","a":"耶律楚材","c":["林甫滔天圣不知，三郎深恨识卿迟。尘中妃子春罗袜，钱上开元指甲眉。", "七夕殿中祈巧夜，三秋原上摘瓜时。长天忽见飞来雁，垂泪空吟李峤诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满江红 其十四 寄呈荔裳","p":"","d":"明代","a":"尤侗","c":["北望卢龙，痛精卫、魂填溟涨。何幸得、南楼老子，下官无恙。", "千里相思风雨夕，十年重过江湖上。笑故人、只有一杯莼，为君饷。", "飞蝶梦，游丝漾。骑马地，朝鸡唱。算半生白发，星星愁酿。", "笠泽烟波宜载酒，泰山日观聊携杖。再休提、宋玉赋秋风，悲哉状。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"将为南行陪尚书崔公宴海榴堂","p":"","d":"唐代","a":"许浑","c":["朝宴华堂暮未休，几人偏得谢公留。风传鼓角霜侵戟，", "云卷笙歌月上楼。宾馆尽开徐稚榻，客帆空恋李膺舟。", "谩夸书剑无知己，水远山长步步愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"平江颜侍郎","p":"","d":"宋代","a":"周必大","c":["吴门自古俊髦多，中外推公政事科。议礼不妨丰酒课，治繁犹暇讲禅那。", "榻前屡记宣除目，川上遥怜逐逝波。底用镌碑纪廉直，乡评正自不消磨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"新城塔山对雨二首一","p":"","d":"宋代","a":"晁补之","c":["山外圆天一镜开，山头云起似浮埃。", "松吟竹舞水纹乱，坐见溪南风雨来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽刘大监思恭","p":"","d":"宋代","a":"度正","c":["簪绂源流远，诗书气味香。", "啼莺翔涧谷，鸣凤瑞朝阳。", "壮志欣辰告，羸躯痛夕亡。", "万夫今失望，拟欲问苍苍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春暮郊游","p":"","d":"清代","a":"贺国华","c":["寂寂春光昼掩扉，不知春事正芳菲。双柑斗酒偶然出，柳絮梨花无数飞。", "清圳风柔鸠语静，野塘雨足鳜鱼肥。夕阳一路经行处，陌上人歌缓缓归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长溪建善寺四首 龙湫亭","p":"","d":"宋代","a":"刘安上","c":["亭下一杯水，澄泓如有容。不因求得雨，那信有神龙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋怀","p":"","d":"宋代","a":"李若水","c":["西风响窗扉，炎火烦一扫。", "天清露华滋，妍碧谢庭草。", "旅怀良独难。缺月窥檐间。", "呼儿漉新酒，强俗朱衰颜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"澎湖旅思 其四","p":"","d":"清代","a":"翟俦","c":["寒剑萧条天外游，蛮烟番雨几经秋。乾坤共识浮云幻，日月空随大海流。", "骨傲自惭难媚世，病馀那忍独登楼。愁来欲问愁何事，意绪茫茫似十洲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"喜陈兄至","p":"","d":"唐代","a":"白居易","c":["黄鸟啼欲歇，青梅结半成。坐怜春物尽，起入东园行。", "携觞懒独酌，忽闻叩门声。闲人犹喜至，何况是陈兄。", "从容尽日语，稠叠长年情。勿轻一盏酒，可以话平生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登师山诸生有书二首 其二","p":"","d":"元代","a":"郑玉","c":["山前村落乱高低，云意模糊远近迷。万叠峰峦如画展，黄山正在小楼西。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"催会中诸老起钓台仙迹亭","p":"","d":"明代","a":"张天赋","c":["打约曾同洛下英，黄鸡白酒祭山灵。钓台不减灵台乐，试问何时起钓亭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"种梅","p":"","d":"宋代","a":"史文卿","c":["素与梅花自有缘，又移几本种庭前。", "镜中一半閒风月，不属王郎载雪船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"网坛岁杪漫怀","p":"","d":"当代","a":"熊东遨","c":["风雨年来习不惊，惟凭一网寄深情。夜阑忆及闲常事，顿觉潮从枕上生。", "一念初萌谁解我，寒江夜济知苇可。此中缘份是天成，莫更无端问因果。", "新酿梨花酒一坛，又因风雪忆天山。不知星汉云空里，邀得神仙几个还？", "瑶池八骏朝天帝，玉辔金镫添意气。山右狷狂马独来，行空不受丝缰系。", "长白山头雪浪奔，剪梅独许到俞门。人间世态知多少，一掬清泉自养根。", "自种松杉初及额，能从近处瞻高格。半梦长留一念真，足胜万古虚矫客。", "梅云梅雨孰为先，如水交情二十年。窗外晦明何必问，纤尘不染是心田。", "长河自古多姿彩，百折千回终不改。涛声日夜若奔雷，直挟泥沙泻东海。", "一剪烟波一叶舟，自由天地足淹留。当年靓丽渔家女，赢得名声也白头。", "孤月冷霜光自照，岁寒不改苍枝傲。丹田蓄得气如虹，耐寂轩中时一啸。", "陌上风光日日新，半随流水半浮尘。诗家自有奇招在，满插瓶花截住春。", "竹杖芒鞋风貌古，终朝乐与民为伍。偶踏杨花过谢桥，惊起沙鸥前后舞。", "紫金山畔竹梧青，有凤来仪展素翎。自向莲台宣佛号，清吟不许俗人听。", "贺兰山畔逢初雪，一派天声梨蕊裂。信手裁成大气诗，风华何用人称绝？", "宝瑟和谐璧影沉，绕梁三日有余音。把书深柳堂前读，如此风光最赏心。", "青山横断东西陌，酒量诗才俱不恶。几时碰破壁重重，露出全新天一角？", "少年才俊更何人，瓶里青梅瘦入神。点将骚坛风起浪，每从谐谑见天真。", "奇观每伴行舟走，神女峰边蓦回首。何处清光醉煞人，一团月落三江口。", "十里烟霞隔水村，杏帘遥望亦消魂。何时得与清风接，肝胆论文共酒樽？", "篁筠久作巢湖隐，遮莫根前初抱笋？何当再效石风堂，凭虚各把清觞引。", "我兽今朝食肉无，朔风吹雪片帆孤。尘封旧事休翻起，生怕凭空累酒壶。", "江南雨后山河丽，画到传神多写意。眉眼盈盈向我舒，霎时如坐春风里。", "吴郎妙手善调筝，源出潮州韵最清。自抱平常心一颗，也无风雨也无晴。", "吾家有子初擎斧，网上裁诗不辞苦。偶从天外试高飞，风光差似神舟五。", "桃李新开第几枝，圣贤之道有张弛。溪云自是怜风雅，笼住春光也未知。", "静玄老道音违久，或去陶门种杨柳？杨柳新垂万绺丝，丝丝都挽朋侪手。", "绝代箫韶有异音，旧三轮上发长吟。人间已不分清浊，独挽天河自沐心。", "寒山晓听吹清角，冷沁心脾殊未觉。真言尽向酒前倾，平日台词俱省却。", "有子新从塞上归，白衣犹带杏花飞。门墙不待重开启，先放春光到外围。", "一自仙翁乘去鹤，吟坛几度伤寥落。布衣捧剑楚山来，复起春风同乐乐。", "云外传声不惮劳，五更催客月轮高。如今正果修成也，脱尽鸡毛换凤毛。", "度尽洪荒人不识，寒林四顾烟如织。补天功就自安闲，长羡山中老顽石。", "山郭晴晖向晓开，莫教孤负十分才。朵云红白连环出，天放奇花不用栽。", "骚坛亦有杨家将，接力途中扛大棒。活法遥承乃祖来，入时能画新眉样。", "消息年来两未知，满山风露忆军持。夜阑置酒松窗下，细读先生不死诗。", "剪剪春风添烂漫，兰舟划出垂杨岸。凌波抖落隔年霜，依旧身心如菊淡。", "盐车高负日迟迟，古道西风瘦马嘶。伯乐至今犹醉卧，此声听到是何时？", "网坛博得人称许，惊世才华天赐与。不信神通孟老邪，居然有此玲珑女。", "坐对千年一局残，老僧应已破禅关。城南如月之秋夜，细听清风响佩环。", "岁寒枝上同摇曳，逊白输香真浪说。渺渺予怀几个知，算来只有梅关雪。", "扫径思迎二客临，天山约罢约闲吟。隔篱依旧邻翁健，浊酒犹能试一斟。", "长启西南轩一角，略分濠上游鱼乐。天下横流水几何，冠缨只用沧浪濯。", "笔下诗翻旧体新，庆霖豪气逼前人。春来信有于蓝出，先置樽罍到水滨。", "网游时与高人会，家酿长思谋一醉。又到江南欲雪天，不知阿二归来未？", "几年游屐遍东南，何幸新知有大凡。解道相逢便金石，天光云影一湖涵。", "吟坛旧雨连新雨，结个忘年天或许。乖巧林中曲曲溪，娱人只作和谐语。", "打从持棒到天堂，百事都由自主张。食尽蟠桃花又着，四时春色属猴王。", "凭栏四望皆芜草，浅褐深黄俱了了。蓦见松花一叶开，生机在眼休云少。", "雪与梅花次第临，村醪待客敢偏心？送伊归得天山去，一半为君醒后吟。", "赏罢银蟾秋已半，青山欲把衣衫换。古松留住涧边云，好续坐看缘一段。", "不是橱窗塑料花，溪头小草活生涯。若嫌官样文章累，无事多来听咂吧。", "何处莲花清若许，风吹仙袂飘飘举。双舟并桨出烟波，想是龙宫初嫁女。", "极天南北任穿梭，应是诗多偈也多。我愧学禅无一得，佛前初解念弥陀。", "风骚早与神仙各，万里晴空秋一鹤。不受人间宰相招，孤飞自得怡然乐。", "斗牛光焰若鸣雷，又向空山舞一回。如此锋芒如此气，几时交付与钟馗？", "柳叶舒眉娇正舞，桃花脸晕芳初吐。伊谁约得美人来，先是春风后春雨。", "网上谭诗万象和，闲中岁月漫消磨。不愁抗手无寻处，斋主清才个个多。", "自家摇曳凌虚绿，不管陈平分社肉。偶听风传一笛清，果然神韵超凡俗。", "神舟消息有花边：曾到银河觅胜缘。织女牛郎都不问，只同天马结忘年。", "剪剪清风独来往，柳村故旧年年访。溪边偶尔一回头，惹起杨花生异想。", "岂为交情掩异同，延陵犹见旧家风。不嫌广告词繁琐，也并英雄到局中。", "伊家屋傍松篁结，溪有游鳞山有蕨。锄罢梅花鸟不啼，当头一片秦时月。", "网上风光面目奇，千峰万壑转迷离。私家马甲知多少，谁似先生自在披？", "应是庐山缘未了，梦中犹作松边倒。陶家借得酒壶来，便向鄱湖寻野老。", "苏辛李杜不同来，分付园花省着开。天气渐寒心渐暖，菊斋留韵到梅斋。", "开过红桃开白李，家家都在春声里。衔泥燕子故飞飞，来慰高楼人独倚。", "漫道诗花水岸多，远寻荒漠又如何？黄沙万里添生趣，红柳丛中卧骆驼。", "守过千年情入骨，天河又见风吹筏。嫦娥有约不曾来，高卧云头遥梦月。", "高山流水不须琴，少悟因缘亦畅心。诗履正思随老杜，未期筇杖已先临。", "先生家住深山里，日踏青苍行不止。一个诗仙也未逢，还期遍发桃花水。", "柴门无事不常开，难得当年小杜来。早识白鸥湖上意，也应杨柳及时栽。", "写罢芜词还自笑：春迟娇懒凭谁报？小梅窗下月溶溶，疏影一天和梦到。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"零口早行","p":"","d":"金朝","a":"刘昂","c":["马上兀残梦，沉沉天向晨。行云如妒月，古道不逢人。", "野旷耕声远，山高露气新。哦诗无好语，聊尔一吟呻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"哭江进之 其六","p":"","d":"明代","a":"袁宏道","c":["好手经炉冶，匡时正老成。文通才未尽，元静职犹轻。", "妖作长沙鵩，帐空澧水萤。花源留迹处，莎草背阶生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"草堂落成漫志近况 其三","p":"","d":"明代","a":"李之世","c":["屋角平行亦碍眉，巡檐刚觉帽儿欹。童閒洗药晒书后，客韵香恬熟茗时。", "花瘦篱头酣不醒，竹荒墙角俗难医。何如刬却前阶草，一味清虚也亦宜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寒食 其四","p":"","d":"宋代","a":"吕本中","c":["病夫只欲闭柴荆，客至从嗔不出迎。未恨家贫无历日，紫桐花发即清明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南粤辞 其五","p":"","d":"明代","a":"屈大均","c":["足下中国人，今乃反天性。皇帝与抗衡，祸且及真定。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送同年崔先辈","p":"","d":"唐代","a":"许浑","c":["西风帆势轻，南浦遍离情。菊艳含秋水，荷花递雨声。", "扣舷滩鸟没，移棹草虫鸣。更忆前年别，槐花满凤城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄吴宪之侍御 其一","p":"","d":"明代","a":"庄昶","c":["玉节留诗老树滩，可能还忆钓鱼竿。相看云水无三舍，不寄梅花又两寒。", "醉枕柳根容我睡，谏书天下为公看。相思欲采芙蓉寄，只恐江深水冷难。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"云峰雅兴","p":"","d":"元代","a":"叶颙","c":["高卧碧云岑，清谈翠竹林。疏狂交牧圉，勋业谢冠簪。", "江月清吟腑，松风醒醉心。焦桐弦久绝，三弄发奇音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏黄门摄县以纂志见邀局中答梁彦国邓毓元二子","p":"","d":"明代","a":"欧大任","c":["偶来讲肆暂盘桓，祖谢同游自鹖冠。窗外竹声凭槛听，雨中山色隔城看。", "娇莺乍啭衣将换，新火初分食尚寒。自笑校书非寓直，花期犹阻故人欢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"角","p":"","d":"明代","a":"黄衷","c":["哀角因风听，天东月晕生。遥闻鬼方寇，近合水西兵。", "缟练征人妇，青灯独夜情。此中多苦调，休弄早秋声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"玉京秋 湖上看桂","p":"","d":"清代","a":"阮恩滦","c":["烟水远。凉飙动群木，桂花初绽。低云密护，颓阳微渲。", "浅碧深香相半。最留人、风送香暖。凝眸看。几枝斜倚，小山亭畔。", "林外残霞催晚。喜馀芬、常留仙馆。瑶砌珠尘，画栏金粟，十分秋满。", "试问天台，料万树、应亦同时开遍。漫飘散。为惜芳华太短。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"并蒂芙蓉 题蒋南沙相国画并蒂莲花","p":"","d":"清代","a":"顾太清","c":["水净风疏，照碧天倒影，花间无暑。清露洗红妆，爱金蕊交错。", "同心并头两朵，洛浦凌波笑相与。结成伴侣，惜双双、占断风流娇妩。", "渺渺曲塘落日，问何来小鸟，双栖双伫。不肯画鸳鸯，怕花里耽误。", "莲花自然洁净，那管根芽淤泥污。这般态度。愿生生、总开一处。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"渎流","p":"","d":"清代","a":"张问陶","c":["卧听海客说瀛洲，今日抽帆下渎流。浊水一湾村市冷，神鸦千点庙门秋。", "支离欲蓄三年艾，浩荡谁驯万里鸥。此去蓬山应不远，只愁风力引飞舟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"红楼梦曲","p":"","d":"清代","a":"曹雪芹","c":["一帆风雨路三千，", "把骨肉家园齐来抛闪。", "恐哭损残年，", "告爹娘，", "休把儿悬念。", "自古穷通皆有定，", "离合岂无缘？", "从今分两地，", "各自保平安。", "奴去也，莫牵连。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"风云交作戏题","p":"","d":"宋代","a":"陆游","c":["霎脚如龙爪，空中挟雨来。", "何关风伯事，欲到却吹回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"朱鹭","p":"","d":"南北朝","a":"王僧孺","c":["因风弄玉水，映日上金堤。犹持畏罗缴，未得异凫鹥。", "闻君爱白雉，兼因重碧鸡。未能声似凤，聊变色如圭。", "愿识昆明路，乘流饮复栖。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"沪上逢几道有诗酬之","p":"","d":"清代","a":"陈宝琛","c":["桑田三变休龙斗，海上连宵重说诗。此事可怜成古调，馀生相对看枯棋。", "村夫食粟能无健？世路回车又有歧。岁晚卖文充市隐，水乡丹橘问归期。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十六夜祖董生北行","p":"","d":"宋代","a":"黄甲","c":["江南今夕月，清光犹似昨。", "君行背雁飞，明日堪谁酌。", "孤情月正中，照汝颜如削。", "愿君霜树年，遗风远摧薄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"承光殿三首 其三","p":"","d":"清代","a":"弘历","c":["遗迹金元一慨然，踞盘形胜揽全燕。空澄何似瀛池水，玉蝀秋风五百年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送友人南旋","p":"","d":"清代","a":"袁鹏图","c":["欻然声价出江东，力守经师继汉风。香国奇才如子少，天涯涕泪几人同。", "自惭待诏金门侧，常共深谈漆室中。朝野恬熙吾辈老，凭谁上策定和戎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"景安和章来再次韵谢设醴四首","p":"","d":"宋代","a":"陈造","c":["拜赐清诗醒醉昏，恍如帝所听新翻。", "君才炙輠无穷尽，未敢先关月下门。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"唐彦猷谈奉得达二帖赞","p":"","d":"宋代","a":"岳珂","c":["公于国史，以好砚称。", "石焉取斯，盖协其能。", "遒媚之观，在此尺纸。", "善工利器，予鉴如此。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百六十首 其八十九","p":"","d":"宋代","a":"释宗杲","c":["善法堂前瑞气新，天书来自九重城。唯凭一句无私语，上祝吾皇亿万春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"云鬓","p":"","d":"未知","a":"王偁","c":["香鬟三尺绾芙蓉，翠耸巫山雨后峰。", "斜倚玉床春色去，鸦翎蝉翼半蓬松。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"天长道中","p":"","d":"宋代","a":"孔平仲","c":["柔桑满野麦成川，晴色连陂雨在田。顾影寂寥谁与语，据鞍閒暇不妨眠。", "尘劳可厌非今日，老大无堪异昔年。此去聊为上都客，行当货马觅归船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"元宵中都太守放灯作律诗五首 其三","p":"","d":"明代","a":"郑真","c":["北极中天正斗杓，风流人物共今宵。当楼绮彩丹心结，隔幔琉璃翠影摇。", "龙驾共瞻宸阙近，鳌山慢忆海天遥。凭谁记得云中曲，来向人间叶凤韶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三月三日龙门舟次","p":"","d":"明代","a":"郭之奇","c":["三月三日春气足，春浮海外无拘束。千舻百苇载春流，春山春水为谁绿。", "自居涯角四经春，满怀春事畴堪属。清明上巳漫从时，洗旧淘新未免俗。", "无花无酒对烟风，远望高歌尽一曲。岂知歌尽出春愁，一寸柔肠春断续。", "春初春仲又春三，九十春光如转烛。春光于世独何求，久客依人多忤触。", "人生有情空自毒。春去春回那可赎。我亦欲东与春归，安能居此为春促。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨蛮 其十七","p":"","d":"宋代","a":"张孝祥","c":["冥濛秋夕漙清露。玉绳耿耿银潢注。永夜滴铜壶。月华楼影孤。", "佳人纡绝唱。翠幕丛霄上。休劝玉东西。乌鸦枝上啼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和令狐仆射小饮听阮咸","p":"","d":"唐代","a":"白居易","c":["掩抑复凄清，非琴不是筝。还弹乐府曲，别占阮家名。", "古调何人识，初闻满座惊。落盘珠历历，摇珮玉琤琤.", "似劝杯中物，如含林下情。时移音律改，岂是昔时声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雁影","p":"","d":"明代","a":"盛镛","c":["似有疑无认未真，月明紫塞倍精神。三秋写照空中现，万里随行分外亲。", "荻渚烟销怜一片，湘江浪静印全身。穿云何处留痕迹，惆怅挥弦目送人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"与诸昆季言怀 其一","p":"","d":"清代","a":"孙元衡","c":["骐骥仰天鸣，朽索驭刚铁。一驱升崇山，焉知踬于垤。", "脂牵转回肠，孰与较优劣？才老力可尽，名成待九折。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"武夷曲次晦翁棹歌（二首）","p":"","d":"明代","a":"郑善夫","c":["幔亭彩幄会仙灵，紫雾蒙蒙薄太清。", "奏罢人间可哀曲，凤笙龙管杳无声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登岳麓赫曦台联句","p":"","d":"宋代","a":"朱熹","c":["泛舟长沙渚，振策湘山岑。烟云眇变化，宇宙穷高深。", "怀古壮士志，忧时君子心。寄言尘中客，莽苍谁能寻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨","p":"","d":"近代","a":"黄浚","c":["秋林渐绛病方残，一雨平添小榻寒。可惜更无閒客过，清诗吟与阿谁看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宋。羊玄保","p":"","d":"唐代","a":"孙元晏","c":["运命将来各有期，好官才阙即思之。", "就中堪爱羊玄保，偏受君王分外知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"饮建昌山亭寻先题亦潇洒楼遗址，敬次原韵","p":"","d":"清代","a":"许传霈","c":["山色盘苍郁，奔赴严子江。建昌勒其下，江涛气势降。", "独宏保障功，合住神仙宅。烟雨护林峦，蛟龙潜波泽。", "我来九秋节，萧瑟物尽搜。狂飙面疾割，小月斧初修。", "酌酒暮山头，山行何朗朗。吟啸当危栏，万山音环向。", "作赋悲王粲，落帽笑孟嘉。零落有时至，所惜在朝华。", "遗址寻岩阿，真情起林表。犹是好江山，那不乐鱼鸟。", "望云亲不见，卅载系我思。思之不可得，恐为猿鹤嗤。", "舟帆江水流，云雾峰头逐。时乎不再来，宝剑长鸣椟。", "会出造楼手，潇洒见旧胸。先贤与先泽，我自得所从。", "好句留性天，慎勿戕柳杞。把盏竹翠间，敲棋松阴里。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"法华院僧祖月写余真戏赞","p":"","d":"宋代","a":"周必大","c":["老子七十七，到处遮人壁。", "住世更十年，化身千百亿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏金陵曲中遗事 其一","p":"","d":"明代","a":"屈大均","c":["国初南院首皇州，官妓居连十四楼。手帕结成多姊妹，春盘笑为赏灯留。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题画送韩御史旸归省 其一","p":"","d":"明代","a":"杨士奇","c":["秦望山清近若耶，纷纷云树映溪沙。数椽茅屋无尘杂，知是安阳御史家。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"萤二首","p":"","d":"唐代","a":"罗邺","c":["水殿清风玉户开，飞光千点去还来。", "无风无月长门夜，偏到阶前点绿苔。", "裴回无烛冷无烟，秋径莎庭入夜天。", "休向书窗来照字，近来红蜡满歌筵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山居 其六","p":"","d":"宋代","a":"淳藏主","c":["瓦炉爇处清烟霭，铁磬敲时晓韵寒。一穿数珠粗又重，拈来百八不相谩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"王侍读挽辞二首 其一","p":"","d":"宋代","a":"韩维","c":["旧族人犹凤，清班署冠鳌。法书传隶古，才笔拟庄骚。", "赠印官称宠，题旌谥典高。无由攀葬绋，伫立望行艘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠永嘉高生","p":"","d":"元代","a":"郑元祐","c":["高生永嘉秀，秀也实南金。学启麟经秘，雏生凤穴深。", "浪花迎客棹，霜叶变枫林。异日巍科掇，秋期又盍簪？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送黄隐君南归","p":"","d":"明代","a":"谢榛","c":["黄生久不见，一见即言归。落叶世情薄，浮云生事微。", "潮声随晚棹，江色照寒衣。还醉莆中酒，春风自掩扉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郡斋水阁闲书","p":"","d":"宋代","a":"文同","c":["衰后常亲药饵，忧来颇忆林泉。身坐谢庄小阁，心游沈约东田。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长沙行送胡子","p":"","d":"明代","a":"皇甫汸","c":["贾生昔被长沙谪，湘水千年动颜色。吊古空劳忆芷兰，世途久已生荆棘。", "当今天子称圣君，论恩岂复如汉文。垂裳穆穆日南向，锐情稽古非谦让。", "直气常悬青琐间，愁云更郁乌台上。胡郎胸中书万言，夕方拜官朝叩阍。", "刘向况有五行传，挺身悟主争绳愆。即今亦有长沙行，此去应知圣主情。", "早晚定膺宣室召，肯使人徒说贾生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戊申春雨书寓所壁","p":"","d":"明代","a":"顾清","c":["去年秋旱深忧稼，今岁春霖复损苗。圣主不应天有谴，清时宁许物为妖。", "浸淫便恐鱼生釜，漂泊谁将蚁渡桥。江上舍前泥一尺，掩书终夕听飘萧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古十九首","p":"","d":"宋代","a":"释慧晖","c":["故山岌岌锁寒烟，未肯将心轻授传。", "玉女夜寻无字印，石人遥指月明前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄孙三庐江","p":"","d":"明代","a":"程嘉燧","c":["自从君去少经过，霖雨柴门有啸歌。", "怀袖尺书三岁在，江关萧瑟暮年多。", "过淮落木空明月，到海青山祇白波。", "闻道儿郎转聪慧，比来樽酒兴如何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵陈使君咏霰雪三首 其一","p":"","d":"宋代","a":"洪刍","c":["天幕垂云合，山屏拥雪飞。杨公田种玉，渊客泪成玑。", "点缀添梅萼，飘零乱羽衣。清溪横一叶，并载月明归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋日杂咏十首 其九","p":"","d":"宋代","a":"李光","c":["天南谁把尺书传，老眼经秋自不眠。鼓角声回窗未掩，可堪残月到床前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"彭琦初用坡翁纸帐韵惠建昌纸衾次韵一首为谢 其一","p":"","d":"元代","a":"刘诜","c":["雪绵揉碎密萦连，清卧梅花性更便。茸暖何须蛮客帐，座寒但少广文毡。", "窗升红日那知晓，梦压白云疑近天。但恐少陵茅屋漏，雨宵沾破不成眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"风瑟联句","p":"","d":"宋代","a":"谢绛","c":["窃竹漏天风，张弦拟峄桐。", "佳名從此得，妙响未曾穷。", "夜静危台上，人闲皎月中。", "依依听不足，秋露满兰丛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舟中","p":"","d":"明代","a":"许邦才","c":["客子常明发，霜天正寂寥。", "移舟星在水，解缆月随潮。", "往事流波驶，归心帆影摇。", "更堪闻过雁，芦荻共萧萧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"走笔戏赠张文鼎墨梅","p":"","d":"元代","a":"唐桂芳","c":["梅花不是人间白，画工休污琼粉色。淡墨疏疏浅著烟，一枝蘸出临溪月。", "张君好画本诗人，吟魂写影俱逼真。从此玉妃归不得，满纸占断罗浮云。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"岭外怀宣城旧游","p":"","d":"宋代","a":"吕本中","c":["中原未敢说归期，却忆宣城近别离。叠嶂雨来如画里，敬亭秋入胜花时。", "每憎卑湿尤多病，苦爱风光屡有诗。今日衰颓那可说，鬓须经瘴总成丝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蝙蝠洞","p":"","d":"宋代","a":"倪梦龙","c":["悬崖多蝙蝠，往往寿千年。", "自古人难到，如今尔得先。", "所餐崖上乳，不出翁中天。", "自有攀援者，曾看抱扑篇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"老去","p":"","d":"明代","a":"倪钅巨","c":["老去花能遣，愁来酒易亲。", "青苔生户牖，白石冷荆榛。", "总有生平好，谁怜旦暮人。", "樵苏聊自爨，稚子学供薪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"与赵道人","p":"","d":"宋代","a":"王炎","c":["欲上青云却垂翅，归来扫轨空山里。", "道人说相来叩关，酒半醺酣谈亹亹。", "我今布褐终余年，岂论燕颔并鸢肩。", "谓予形是朱顶鹤，两眼藏神高颊颧。", "彭殇寿夭谁无死，不将动目摇湛水。", "道人去后若复来，定应难相壶邱子。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"充叟九兄以书问鄱阳官况因亦问讯","p":"","d":"宋代","a":"毛滂","c":["信来频慰别离魂，苦问官情却懒言。", "多睡正随蝴蝶梦，相怜空愧鹡鴒原。", "幸无俗客干书户，遥想青山对县门。", "定是放衙能少事，悠哉岸帻步槐根。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"绍兴癸丑上巳日","p":"","d":"宋代","a":"曹勋","c":["连岁羌酋不荷戈，今年禊饮喜如何。中兴乐事虽无象，甲子先同晋永和。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏怀诗五首 其一","p":"","d":"魏晋","a":"支遁","c":["傲兀乘尸素，日往复月旋。弱丧困风波，流浪逐物迁。", "中路高韵益，窈窕钦重玄。重玄在何许，采真游理间。", "苟简为我养，逍遥使我闲。寥亮心神莹，含虚映自然。", "亹亹沈情去，彩彩冲怀鲜。踟蹰观象物，未始见牛全。", "毛鳞有所贵，所贵在忘筌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杨六郎庙","p":"","d":"明代","a":"尹耕","c":["尚有杨郎庙，其如宋祚何。", "伤心空战伐，极目且山河。", "云鸟人能说，腥膻恨不磨。", "除凶昭代烈，应慰九原多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨蛮七首 其六","p":"","d":"近代","a":"丁宁","c":["芙蓉两两胭脂涴。西风一夕临青琐。和泪别瑶京。太华残月明。", "岭云三十六。日暮迷金屋。何处问飞鸾。蘅芜澈梦寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"摸鱼儿","p":"","d":"近代","a":"龙榆生","c":["尽无言、暗香徐度，缘何清瘦如许。一枝萧洒春仍在，伴我几番朝暮。", "情自苦。但溉汝寒泉，灯影聊相煦。际天风露。便滋润无缘，伶俜长忍，意象自轩举。", "君试觑。点点丹诚倾注。孤怀脉脉谁语。荒山弃置寻常事，难忘移根前度。", "须记取。叹极意壅培，未是芳期误。流光好驻。爱丽日辉辉，奋飞生翼，重与展衷素。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"洛阳道","p":"","d":"明代","a":"朱诚泳","c":["纵横洛阳道，来往觅行踪。宫车若流水，仗马似游龙。", "戚里传灯火，侯门闻鼓钟。何因人掷果，应为美姿容。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郑梦周死节诗 其一","p":"","d":"明代","a":"南衮","c":["丽季衰微泰运升，群贤攀附总飞腾。从容就死乌川子，启我朝鲜节义兴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答董子元太学","p":"","d":"明代","a":"皇甫汸","c":["山居寂寞谁相问，海内交游半不通。双鲤将心传夜月，一帷垂老闭春风。", "新城闻鹤因兵后，往事看花若梦中。情忝通家生校晚，思君惜未见嵇公。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠郑少尹","p":"","d":"明代","a":"边贡","c":["我正雪中卧，君从天上还。节高元自苦，才大可能閒。", "淅沥听疏竹，苍茫对远山。夜深拚一醉，休当剡溪湾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"渡鄱阳","p":"","d":"清代","a":"严遂成","c":["烟与水无际，迷茫小洞庭。", "潮回三楚白，山压五湖青。", "苇折雁声苦，风多鱼气腥。", "扬舲一极目，何处吊湘灵？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"刘汉臣堂甫北归","p":"","d":"金朝","a":"李俊民","c":["哀哉同队鱼，尽在枯池里。纵免鼎中烹，将见渴欲死。", "造物何不仁，岂独困二子。我虽江湖心，恨无斗升水。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登清凉寺后西塞山亭四首 其四","p":"","d":"明代","a":"顾璘","c":["剑化人亡有故城，东来海气带龙腥。烟花楼阁三千界，锦绣河山百二形。", "老托神京堪自隐，醉眠秋涧不知醒。长江只在朱阑外，莫遣哀歌动杳冥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三印颂示众","p":"","d":"宋代","a":"释正觉","c":["印泥印空印水，疾轩不及掩耳。", "豁然楼阁门开，消得轻轻弹指。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵和王巩六首","p":"","d":"宋代","a":"苏轼","c":["欲结千年实，先摧二月花。", "故教穷到骨，要使寿无涯。", "久已逃天网，何而服日华。", "宾州在何处，为子上栖霞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"五言","p":"","d":"宋代","a":"朱敦儒","c":["天寒犹著絮，雨湿欲蒸书。吴地人情薄，西人客计疏。", "无书堪著眼，有法可安心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蜡除诗","p":"","d":"魏晋","a":"张望","c":["玄灵告稔谢，青龙驾拂轸。鲜冰迎流结，凝留垂檐霣。", "人欣八蜡畅，讵知岁聿尽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋懹","p":"","d":"宋代","a":"陆游","c":["昨者风雨过，浩然天地秋。", "年光双雪鬓，生计一渔舟。", "卖药来查浦，听猿到沃洲。", "平生畏暑毒，八月记初游。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梦行西湖梅花下 其二","p":"","d":"宋代","a":"周紫芝","c":["春云收尽忽斜阳，梦里梅花带雨香。却上小舟谁是伴，回头只有棹船郎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿黄兴岐","p":"","d":"明代","a":"成鹫","c":["先生先子之所畏，忆我为儿始七岁。大人抱我置左膝，隔坐与君论文字。", "我时仅识之与无，侧耳静听无欢呼。上客骐驎笑相许，岂知长大成蹇驴。", "蹇驴畏走三城道，踯躅秋风啮秋草。故人相见惊相识，我渐就衰君已老。", "我衰不足惜，君老头还黑。交游半作乘车人，诸生尽是文章伯。", "先生两眼大如箕，世上红尘污不得。一日读书能几回，山中甲子去复来。", "诗书之外何有哉，眼前穷达皆尘埃。青兕爵，丹砂杯，为君寿，酌君醅。", "饮此不得老，日月重皑皑。海水浅，河水清，美人更筑黄金台。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南歌子","p":"","d":"宋代","a":"石孝友","c":["畴昔飞鸾侣，而今断雁行。西风岭外下斜阳。无赖一钩新月、挂人肠。", "双泪沾襟袖，孤灯封客床。枕余衾剩只残香。别得娇痴不睡、也思量。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚晴","p":"","d":"唐代","a":"杜甫","c":["高唐暮冬雪壮哉，旧瘴无复似尘埃。崖沉谷没白皑皑，", "江石缺裂青枫摧。南天三旬苦雾开，赤日照耀从西来，", "六龙寒急光裴回。照我衰颜忽落地，口虽吟咏心中哀。", "未怪及时少年子，扬眉结义黄金台。洎乎吾生何飘零，", "支离委绝同死灰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重游吴哥窟","p":"","d":"当代","a":"姚佳","c":["枯腾老树碧周遮，上座飞仙去路赊。神庙园林独角兽，梵天风雨七头蛇。", "桑香佛舍春犹远，红色高棉日又斜。安得大鹏金翅鸟，瀛涯胜览接星槎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过陈氏园亭","p":"","d":"明代","a":"郭廑","c":["高士园林好，岩扉昼不扃。绝胜陶令巷，犹是子云亭。", "幔卷飞泉白，窗含远岫青。何时出尘想，来此共谈经。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题赵漕小蓬莱 其二","p":"","d":"宋代","a":"方岳","c":["老夫曾到道家山，太乙青藜夜叩关。著作承明今付子，仙壶元不隔人间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题敦煌县署七年四至之堂","p":"","d":"清代","a":"苏履吉","c":["七年四至此名堂，坐对斯民信悚煌。不改书生真面目，犹怀慈母旧心肠。", "儿童渐忘春增长，父老相看岁健康。愧我去来踪靡定，漫言五载报循良。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜起对月","p":"","d":"明代","a":"田登","c":["良宵耿不寐，皓魄烂华埏。夜气湛以肃，良理复其天。", "神鱼戢比鳞，扬鬐逝故渊。倦鸟惜翮翎，瞻巢愤翩跹。", "物性岂凿意，生遂悉其然。饶饶千金子，堂垂灶突烟。", "狎客坐羽觞，鼓吹滋华年。一朝延比邻，捐崩更播迁。", "执守宜中人，况复非圣贤。如有汶上召，为我谢迂愆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次郑好义见贻韵 其二","p":"","d":"明代","a":"方孝孺","c":["赤骥困皂枥，垂头避驽骀。王良振长辔，蹴踏风云开。", "古来功名际，何代无奇才。当其未遇时，谁免蒙尘埃。", "丈夫亮有命，勿使心颜颓。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"虞美人 泊京口有寄","p":"","d":"明代","a":"曹溶","c":["故园寒食看花客，眠尽云帆窄。王郎难信不风流，惯学吹箫弄酒石城游。", "南朝一抹沈烟雾，唤作销魂路。别来相寄彩笺频，纵使春山无恙也愁人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠萧兵曹先辈","p":"","d":"唐代","a":"许浑","c":["广陵堤上昔离居，帆转潇湘万里馀。楚客病时无鵩鸟，", "越乡归处有鲈鱼。潮生水郭蒹葭响，雨过山城橘柚疏。", "闻说携琴兼载酒，邑人争识马相如。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅岭 其二","p":"","d":"清代","a":"谢锡朋","c":["惯将双屐作生涯，浅水疏篱小住家。自笑得居香雪里，读书倦后便看花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东坡三绝句","p":"","d":"宋代","a":"苏籀","c":["为文赤壁并黄坂，奇韵平生想像中。", "延目练江咨逝水，举头碧落看飞鸿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄题石湖先生范至能参政石湖精舍二首 其一","p":"","d":"宋代","a":"杨万里","c":["万顷平湖石琢成，尚存越垒对吴城。如何豪杰干戈地，却入先生杖屦声。", "古往今来真一梦，湖光月色自双清。东风不解谈兴废，只有年年春草生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"喜雪 其一","p":"","d":"宋代","a":"许及之","c":["静听微雨落乾声，晓见平檐粉似匀。去岁鸳鸯何苦热，今朝鸥鹭太无尘。", "眼空色界聊矜富，酒极诗豪自觉神。踏碎琼瑶无过棹，虚教新酿熟经旬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏五黄元卿招同韩孟郁邓伯乔赵裕子饮渌水草堂","p":"","d":"明代","a":"韩日缵","c":["径辟炎氛隔，亭馀水木清。求羊宁我辈，浮蚁为君倾。", "倒景千林出，迎风一榻轻。须拚十日饮，才惬数年情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感时","p":"","d":"唐代","a":"白居易","c":["朝见日上天，暮见日入地。不觉明镜中，忽年三十四。", "勿言身未老，冉冉行将至。白发虽未生，朱颜已先悴。", "人生讵几何，在世犹如寄。虽有七十期，十人无一二。", "今我犹未悟，往往不适意。胡为方寸间，不贮浩然气。", "贫贱非不恶，道在何足避。富贵非不爱，时来当自致。", "所以达人心，外物不能累。唯当饮美酒，终日陶陶醉。", "斯言胜金玉，佩服无失坠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词","p":"","d":"唐代","a":"李衍","c":["辉辉赫赫浮玉云，宣华池上月华新。", "月华如水浸宫殿，有酒不醉真痴人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄题江山叶氏翠香亭","p":"","d":"宋代","a":"王柏","c":["谁窃清香下广寒，霜风染就粟肤丹。", "须知叶叶苍圭色，花未开时自可观。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"减字木兰花 吴昌硕为祖谋画彊村校词图","p":"","d":"清代","a":"朱祖谋","c":["金风嫡派。一世词流甘下拜。馀事丹黄。远接虞山近半塘。", "故山浮玉。梦里消磨文字福。何日归篷。和尔樵歌一笛风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"醉落魄/一斛珠","p":"","d":"宋代","a":"管鉴","c":["碧云暮合。不教预赏中秋月。凉生楚观风初歇。山影沈沈，相对两奇绝。湘人怅望黄金节。只愁酒散仙舟发。凭谁为与姮娥说。明夜虽圆，空照人离别。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏西施","p":"","d":"宋代","a":"华镇","c":["浣纱溪上浣纱女，野服山花照寒水。含嚬惨淡不胜愁，犹使东邻骇西里。", "山鸟渊鱼无定识，俯见潜逃仰惊起。矜花眷月春复秋，长恐朱颜成暮齿。", "君王抡选入吴宫，吴宫寂寞无桃李。芙容一笑君意倾，宰嚭言行子胥死。", "姑苏台榭游麋鹿，阖闾城阙生荆杞。蛾眉倩盼应自成，筑宫教习胡能美。", "当时掩抑无人顾，今日为君除国耻。君莫怪騄骥盐车弭耳时，谁人不作驽骀比。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"追昔游","p":"","d":"唐代","a":"元稹","c":["谢傅堂前音乐和，狗儿吹笛胆娘歌。花园欲盛千场饮，", "水阁初成百度过。醉摘樱桃投小玉，懒梳丛鬓舞曹婆。", "再来门馆唯相吊，风落秋池红叶多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"途次见西成有象喜而有作","p":"","d":"清代","a":"弘历","c":["暑雨祁寒苦怨咨，金风玉露届秋时。最欣比栉村村象，恰向征途历历知。", "场圃却听耞乱响，原田还看柄多遗。岁丰更切乾乾意，肯为从禽志少移。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"用门牌日有好花迎客笑岁篘新酒奉亲叹为韵为","p":"","d":"宋代","a":"陈文蔚","c":["地僻广乾坤，身闲多月日。", "耕鉴太古民，天然自淳质。", "未怒泥神仙，阅世自长长。", "日用饮食馀，帝力我何有。", "修竹三径幽，青山四时好。", "何须万间厦，一廛可娱老。", "园柑结新实，篱菊开晚花。", "旋篘瓮头酒，不负老年华。", "田夫与野老，一笑相逢迎。", "只说桑麻事，安知市朝争。", "年年愿今日，有酒可留客。", "虽无珍饲馐，随宜具肴核。", "人言鹤发翁，翻作朱颜少。", "把酒更何辞，一对西风笑。", "环堵一亩宫，中有长生计。", "秋月与春花，今年又明岁。", "年高新可庆，家贫儿包羞。", "今年胜去年，粗有酒新篘。", "岁月绵绵永，福禄日日新。", "天开九龄数，眼见四世人。", "共乐堂上亲，旋约山中友。", "虽是盘无馔，未至樽无酒。", "积善虽人为，康宁荷天宠。", "但懈儒素风，日乏甘旨奉。", "子孙虽未贤，粗肯诗礼亲。", "愿言各努力，忠孝以立身。", "人间无事日，箪瓢亦清欢。", "但愿人今日，时时报平安。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏史诗 黄河","p":"","d":"唐代","a":"胡曾","c":["博望沈埋不复旋，黄河依旧水茫然。沿流欲共牛郎语，只得灵槎送上天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"新疆纪事 其二","p":"","d":"清代","a":"刘炳青","c":["拼死沙场革裹尸，从军万里滞归期。春风杨柳关西路，秋月琵琶塞上诗。", "刁斗夜惊胡骑走，鼓鼙声动楚歌悲。可怜绝域乡音渺，纵博封侯奈别离。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"素梅 四五","p":"","d":"元代","a":"王冕","c":["三月春风吹雪消，湖南山色翠如浇。", "一声羌管何人见？无数梅花落野桥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂诗九首 其八","p":"","d":"明代","a":"黄淮","c":["朋友以义合，在古理则然。信义苟不亏，宜同胶漆坚。", "良人与我违，斗杓屡西旋。辞色旷不接，中心常悁悁。", "如何反掌间，弃我如蹄筌。醇酒味不薄，春花色易妍。", "谁云一丝泪，能令金骨穿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"催雪","p":"","d":"清代","a":"周之琦","c":["帘罨重阴，灯晕半花，密坐贪依屏背。语冷宦心情，竹深门闭。", "客似寒鸦瘦影，惯倦羽、相偎银云底。琴边试问，清宵款语，冶游知未。", "燕市。十年矣。是几度分襟，几番搴袂。又朔雪，关山岁华如此。", "尽觅红螺换酒，酿不到、鳞鳞鸳鸯水。料只有、藤角吟笺，犹认月波题字。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"小山戢戢盆池浅","p":"虞美人","d":"宋代","a":"陈克","c":["小山戢戢盆池浅。芳树阴阴转。红阑干上刺蔷薇。蝴蝶飞来飞去、两三枝。绣裙斜立腰肢困。翠黛萦新恨。风流踪迹使人猜。过了斗鸡时节、合归来。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"杂述 其九","p":"","d":"宋代","a":"林泳","c":["唐士有非国语，汉人曾反离骚。依本定非笔杰，爱奇自是人豪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"承知府待制诞生之辰辄广善怀","p":"","d":"宋代","a":"陈与义","c":["岁星欲吐芒不开，昴星避次光低佪。麒麟鸑鷟纷夹侍，善怀菩萨当重来。", "仙公风流今几岁，再托高门瑞当世。买香趁浴惊众聋，要识此僧今我是。", "金粟后身何足言，释迦亲送非虚传。稽首西来大菩萨，住世小劫须千年。", "宰官说法聊应会，馀事文章亦三昧。世间底物堪寿公，本自金刚无可坏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十年1947","p":"","d":"近代","a":"缪钺","c":["十年涉世惜知难，一札沈吟慨万端。敢说滋兰花易发，勿忘采药路常寒。", "风前拾蕊春犹昨，梦起推枰局已残。他日相逢蓬岛路，沧波回首尽漫漫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"敬和老人览镜","p":"","d":"宋代","a":"洪咨夔","c":["西谷柴车手自巾，风吹不到庾郎尘。", "回光返照千江月，复命归根一点春。", "永昼同窗陶处士，凉宵专席竹夫人。", "徐公好丑浑休问，认取青铜镜裹真。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"风流子 倬盦邀集莂圃赏雨中芍药","p":"","d":"清代","a":"郭则沄","c":["盈盈红似滴，蝶魂醉、绕遍翠栏干。正玉妃舞歇，画裙慵整，梦欹罗荐，啼损晶盘。", "为问怨春春解否，无语亸香鬟。凭赏堕琼，小帘扶起，背怜搓锦，流水催残。", "年光梅黄近，钿车断芳事，绮陌阑珊。惆怅凤池曾见，铅泪偷弹。", "怕唾壶点碎，雕筵恨别，带围瘦减，珠箔留寒。消受雾边衰眼，重赋愁鸾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"沁园春 金陵凤凰台眺望","p":"","d":"元代","a":"白朴","c":["独上遗台，目断清秋，凤兮不还。怅吴宫幽径，埋深花草，晋时高冢，锁尽衣冠。横吹声沉，骑鲸人去，月满空江雁影寒。登临处，且摩挲石刻，徒倚阑干。青天半落三山。更白鹭洲横二水间。问谁能心叱，秋来水静，渐教身似，岭上云间。扰扰人生，纷纷世事，就里原无此二字，兹从丁本补何常不强颜。重回首、怕浮云蔽日，不见长安。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"辇下曲一百二首，有序 其八十三","p":"","d":"元代","a":"张昱","c":["高昌之神戴羖首，仗剑骑羊气猛烈。十月十三彼国人，萝卜面饼贺神节。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉和御制南郊七言六韵诗","p":"","d":"宋代","a":"杨亿","c":["洁斋恭己奉苍旻，报本圜坛备物陈。酒缩楚茅三献毕，灰飞嶰管一阳新。", "高空瑞气长随辇，永夕清霜暗湿巾。泰畤迎年严汉祀，六宗祈福盛虞禋。", "鸿恩涣汗沾穷发，睿藻昭回动紫宸。庶汇熙熙蒙帝力，徒知击壤效尧民。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九日","p":"","d":"宋代","a":"翁甫","c":["秋风两度身为客，已见重阳未到家。", "村酒不堪供节事，祗将青眼看黄花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大风二首 其一","p":"","d":"宋代","a":"赵蕃","c":["杯水得风犹渺然，况兹章贡远连天。一穷坐我靡他问，下水宁闻劳挽牵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"予元丰戊午岁自楚至宋由柘城至福昌年二十有五后十年当元祐二年再过宋都追感存殁怅然有怀","p":"","d":"宋代","a":"张耒","c":["宋玉台前官树林，十年孤客独沾襟。白头青鬓隔存殁，落日断霞无古今。", "暮云梁苑雁鹜暗，久泛吴船江海深。阅世悲欢嗟老眼，呼儿取酒十分斟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"一落索","p":"","d":"宋代","a":"陆游","c":["识破浮生虚妄。从人讥谤。此身恰似弄潮儿，曾过了、千重浪。", "且喜归来无恙。一壶春酿。雨蓑烟笠傍渔矶，应不是、封侯相。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"觱发寒威淡远空两峰谁镂玉西东后凋颜色分明在便是当年黄绮翁 其五","p":"","d":"清代","a":"弘历","c":["花树烘霞送尾寒，太平鼓吹满长安。春光六月莲为火，九陌通宵燄是兰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"筑普济堂成述怀七首 其三","p":"","d":"清代","a":"过鸣冈","c":["感伤复感伤，糟糠不下堂。断机犹可续，破镜无圆光。", "孤儿在襁褓，枕块支空床。凉月窥我牖，饥鼠穿我梁。", "呱呱待成立，十指安得将。吁嗟兮少寡，血泪沾衣裳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郁庵藏兵之骆越王弓格剑 其四","p":"","d":"当代","a":"姚佳","c":["吾尝终日而思矣，曳尾涂中徙北溟。流水不言供激荡，春山如笑欲忘形。", "将无同也生何惧，身既死兮神以灵。龙战大荒漂杵血，昆池劫碎一天星。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满江红三首 其一","p":"","d":"清代","a":"项鸿祚","c":["铁瓮城开，何处是，紫髯天下。流不尽，英雄遗恨，寒涛激射。", "双桨吴船轻似燕，千寻浊浪高千马。看危矶，径转妙高台，山如画。", "骤雨歇，长虹挂，风渐紧，云成赭。唤江妃，起舞鱼龙悲吒。", "瓜步洲边新月上，茱萸湾口孤帆卸。听寺楼，钟鼓落篷窗，无眠夜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"端午赠黄守徐君猷","p":"少年游","d":"宋代","a":"苏轼","c":["银塘朱槛麹尘波，圆绿卷新荷。兰条荐浴，菖花酿酒，天气尚清和。", "好将沉醉酬佳节，十分酒、一分歌。狱草烟深，讼庭人悄，无吝宴游过。"],"tags":["端午", "写景", "抒情", "爱国"],"z":"","y":"","s":"","k":"词"},
  {"t":"近于小圃筑堂名曰秀野隔河插木芙蕖旧有诗云","p":"","d":"宋代","a":"张侃","c":["二十四番花信风，凝脂剪翠巧妆容。谁言桃李芳春后，不似沿流锦绣中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"齐后图","p":"","d":"明代","a":"唐寅","c":["百二关河狼虎秦，连环难解献高臣。", "若非纤手抽刀斩，应笑山东后有人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长相思 其二","p":"","d":"唐代","a":"李煜","c":["云一緺，玉一梭。澹澹衫儿薄薄罗，轻颦双黛螺。", "秋风多，雨如和。帘外芭蕉三两窠，夜长人奈何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"又用胡尉韵","p":"","d":"宋代","a":"方岳","c":["便觉寻春负一筹，老怀无复少年游。", "茶桑天似鹅黄酒，杨柳花飞狐白裘。", "试问独醒观众醉，何如一笑失千忧。", "不知多少人间事，付与溪声自在流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十月九日初谒卫真太清宫二首 其一","p":"","d":"宋代","a":"晁补之","c":["虚庭下拜初形肃，秘殿瞻容更魄惊。何必囊函窥至妙，始知尘垢负平生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次和尹世立过访","p":"","d":"明代","a":"李之世","c":["春在林芳雨霭间，聊将澹酌消春閒。盘空衲子挦蔬去，灶湿山童乞火还。", "角韵何人诗骨隽，飞筹偏我酒肠悭。茸茸细草沾游屐，踏破苍苔几径斑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"归雁","p":"","d":"明代","a":"章懋","c":["灵囿池台是旧游，西风万里思悠悠。阵横紫塞霜天晓，影落澄江水国秋。", "栖止更嫌芦荻浅，飞归不为稻粱谋。一封带得边城信，要把平羌报冕旒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"双禽","p":"送兄弟还都至长葛河上四首","d":"宋代","a":"韩维","c":["双双河洲禽，文彩披丹质。", "飞翔不离渚，鸣戏自终日。", "寒鱼伏冰池，岁暮饥尔匹。", "不欲远求林，投身避罗毕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丁亥暮春昭萍雅集次江湖小李兄韵","p":"","d":"当代","a":"熊盛元","c":["回春术与缓和齐，退食山房诵克岐。醇酒青横骚客眼，乱花红浥燕巢泥。", "袂分南浦肠应断，派衍西江责岂辞！问取昭萍今夜月，明年此会更谁题？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病中答馈药二首 其一","p":"","d":"明代","a":"刘麟","c":["坐室延师易，登城取药难。感君传递至，蹴踏试寻山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"元夕二首","p":"","d":"宋代","a":"项安世","c":["堕剑遗弓未乾，断蓬漂梗不知寒。", "月明正在行宫上，犹作瑶墀旧梦看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"辛亥三月二十九日广州之役，余在北京狱中闻展堂死事，为诗哭之，才成三首，复闻展堂未死，遂辍作 其一","p":"","d":"近代","a":"汪精卫","c":["马革平生志，君今幸已酬。却怜二人血，不作一时流。", "忽忽馀生恨，茫茫死后忧。难禁十年事，潮上寸心头。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别仙娥峰","p":"","d":"宋代","a":"王禹称","c":["商山留滞再经春，吟爱仙娥最出群。若有精灵念迁客，暂来河北作行云。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和泾川观音岩韵","p":"","d":"明代","a":"罗玘","c":["此生此日此冯轩，惊见银山大浪翻。石窟定僧如鬼瘦，斗崖悬树与猿攀。", "风雷半夜鲸鲵吼，霜露满天鸳鹤喧。面面云中千岫出，若为龙象筑长垣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆铁机梵音更涉诸子","p":"","d":"明代","a":"释今严","c":["芝焚蕙谢自多情，情尽如何感又生。巨海已看摧劲楫，法门频复坏长城。", "六群但执中边议，五部惟争大小乘。宁似此时荒谬极，辩才高论惜群英。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送邵州判官往南","p":"","d":"唐代","a":"刘长卿","c":["看君发原隰，驷牡志皇皇。始罢沧江令，还随粉署郎。", "海沂军未息，河兖岁仍荒。征税人全少，榛芜虏近亡。", "新知行宋远，相望隔淮长。早晚裁书寄，银钩伫八行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨中花 其一 江亭晚集","p":"","d":"清代","a":"丁澎","c":["望里江城如雾。柳外檐星初吐。婪尾争传，红牙乍拍，飘眇烟深处。", "樽前翠袖双眉妩。香入鹍弦半度。看野鹜多情，芰荷应笑，客且休归去。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过金山和人韵三绝 其一","p":"","d":"元代","a":"耶律楚材","c":["金山突兀翠霞高，清赏浑如享太牢。半夜穹庐伏枕卧，乱云深处野猿号。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"溪上","p":"","d":"唐代","a":"顾况","c":["采莲溪上女，舟小怯摇风。惊起鸳鸯宿，水云撩乱红。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舟过城门村清晓雨止日出 其五","p":"","d":"宋代","a":"杨万里","c":["地锦花铺地锦衣，碧茸上织紫花枝。垂杨舞罢莺停唱，不捲华絪待阿谁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"早朝","p":"","d":"宋代","a":"孙锐","c":["烛光剑佩拥千官，载月临轩拜紫銮。", "仙掌禁寒承露稳，天颜霁晓傍云看。", "朝阳鸣凤谐宫律，沧海□鳌献羽翰。", "咫尺圣明三舞蹈，报恩岂敢负弹冠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅","p":"","d":"宋代","a":"戴复古","c":["孤标粲粲压群葩，独占春风管岁华。", "几树参差江上路，数枝装点野人家。", "冰池照影何须月，雪岸闻香不见花。", "绝似林间隐君子，自从幽处作生涯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山中小景","p":"","d":"明代","a":"全室宗泐","c":["四山一片秋色，野客独坐茅亭。", "渡头红叶如雨，石上长松自青。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"婢态","p":"","d":"宋代","a":"万俟绍之","c":["才入园中便折花，厨头坐语是生涯。", "不时掐数週年限，每事夸称旧主家。", "迁怒故将瓯碗掷，俲{左目右宾}刚借粉脂搽。", "隔屏窃听宾朋语，汲汲讹传又妄加。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋风 其二","p":"","d":"明代","a":"陈邦彦","c":["早稻才收晚稻黄，使船如马信帆樯。时因回合占师律，为辨雄雌识大王。", "何处征途歌葛屦，有人狎坐理霓裳。相思莫遣罗衣薄，河汉西流夜未央。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"正月初四后十余日病嗽不能出杂书十首","p":"","d":"宋代","a":"方回","c":["僦居背古城，楼西耸乔木。", "两年见黄落，雪尽欲再绿。", "往时春鹊雏，理巢乳哺续。", "不归视吾儿，于此拜饥腹。", "穷山况味等，差胜客景独。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"廖传道示旅中述怀借韵奉酬且相慰勉云","p":"","d":"宋代","a":"廖刚","c":["高轩惭愧远相过，道义谈馀旅琐多。灯底自怜干斗剑，壁间谁办化龙梭。", "时来会中青钱选，和寡空为白雪歌。好淬文锋迎紫诏，莫因贤梗叹蹉跎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"五福降中天 丁未除夕示内","p":"","d":"清代","a":"吴绮","c":["牛衣夜半啼寒雪，犹记灞陵憔悴。司马鹴裘，少君鹿毂，岂意行歌黻佩。", "年华欲换，笑五十明朝，买臣非贵。夫婿东方莫羡，此际且相慰。", "绿水青山作吏。一家图画里，欢成队。蜡凤宵嬉，青箱付与天意，凭教儿辈。", "杯从幼起，暖向春归，况当良会。放却眉梢，陶然须共醉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送相里秀才赴举","p":"","d":"唐代","a":"齐己","c":["两上东堂不见春，文明重去有谁亲。曾逢少海尊前客，", "旧是神仙会里人。已遂风云催化羽，却将雷电助烧鳞。", "明年自此登龙后，回首荆门一路尘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"户庭浮瑞气","p":"瑞鹤仙","d":"宋代","a":"佚名","c":["户庭浮瑞气。八日馀寒，新春来至。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"水调歌头","p":"","d":"宋代","a":"郑元秀","c":["园林夸富贵，红绿簇枝头。阳和毓秀，气劘屈贾压曹刘。翰墨场中独步，洒落胸中万卷，横截百川流。邈视青云侣，俯首看瀛洲。", "到如今，萦扃务，尚淹留。庙堂应得好语，早晚觐宸旒。从此立登要路，便可羽仪台阁，指日凤池游。岁岁蟠桃会，椿算八千秋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵 其一","p":"","d":"元代","a":"于立","c":["过雨收残暑，西来水似天。秋风生柁尾，明月落尊前。", "惨澹依山寺，欹斜下濑船。清歌不成调，思尔枕书眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谒中岳祠","p":"","d":"明代","a":"陈琏","c":["巍巍碧殿倚苍冥，玉节金幢拥百灵。乐石镌碑彰瑞应，斋廊画壁杂丹青。", "朝廷锡号恩尤重，使者函香意独精。维岳降神闻自昔，愿生申甫佐明廷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怀友","p":"","d":"明代","a":"止庵法师","c":["三五月明满，三五月明缺。", "行人去未远，忽若三年别。", "此时道路间，北风何猎猎。", "局促瘏马悲，萧条秋草歇。", "所遇非所欢，中怀安可说。", "不念故里闾，甘为苦霜雪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"虞美人（九月饮乘风亭故基）","p":"","d":"宋代","a":"赵彦端","c":["烟空磴尽长松语。佳处遗基古。道人乘月又乘风。未用秋衣沈水、换薰笼。", "两峰千涧依稀是。想像诗翁醉。莫惊青蕊后时开。笑倒江南陶令、未归来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏梅三十首 其十九 红梅","p":"","d":"元代","a":"冯子振","c":["春风昨夜入南枝，浃髓沦肌释冻威。和气晓来无著处，满空飘作綵云飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"遣兴","p":"","d":"当代","a":"卢青山","c":["诗客语天真，还须刻玉心。山泉经百转，出瀑始天成。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九月饯衍圣公于礼部次夏宗伯桂洲韵 其三","p":"","d":"明代","a":"钟芳","c":["堂焕丝纶锦障开，耆英仪度古尊罍。黄花爱客微含媚，意恐开残客倦来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"呈隆兴总管王都水友直 其二","p":"","d":"宋代","a":"汪梦斗","c":["当日凤台下，鹿鸣同著鞭。鱼龙既悬绝，鸡犬竟难仙。", "危叶愁霜病，寒花纷晚妍。幽窗论旧事，客抱固凄然。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次制帅所和前韵","p":"","d":"宋代","a":"王之望","c":["圣主忧勤躬万务，英豪宁许山林住。", "弓旌号召士无留，竹帛功名公所赴。", "天表对扬咨见晚，坤维镇抚歌来暮。", "雪山增生绝纷埃，蜀道非难履平路。", "分陕聊烦摅妙略，秉钧已叹迂高步。", "朱轓抚俗民怀，玉帐折冲荒服惧。", "羽檄不飞烽堠灭，骏骨多收边市互。", "孔明七纵讵非长，户牖六奇真不误。", "农狎其野无外忧，马腾於槽有余怒。", "三陲绝徼皆妥安，诸将雄师今尽护。", "九重益友思直谅，四蜀新声咏宣布。", "帅阃方观勋业成，庙堂行看精神聚。", "嗟我衰迟托末契，辱公敦笃倾殊顾。", "当年献赋诵凌云，上国承颜悦披雾。", "禹门亲睹跃风雷，尧陛初惊承雨露。", "龙颜下瞩顿生光，凤翼高翔从此附。", "称身朝服曳青云，满袖天香携宝炷。", "九霄变化冥鹏升，一纪光阴隙驹鹜。", "绨袍雅意念张禄，襦夸余波依叔度。", "他时入觐对金莲，伴直应随玉堂寓。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题四娱斋 其二","p":"","d":"元代","a":"耶律铸","c":["雪满兰窗雾满阶，恍疑身世在瑶台。琴馀细嚼陶潜句，书罢深倾李白杯。", "流水净拖飞练去，好山晴与翠屏开。百年乐事能多少，何必更歌归去来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送为章","p":"","d":"宋代","a":"许景衡","c":["使君遗爱在甘棠，故老于今尚未忘。椎钝自嗟生太晚，风流犹及见诸郎。", "鸣琴暂肯留山县，飞舄还同指帝乡。回首楼前江上月，夜来无故照离觞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"步蟾宫","p":"","d":"元代","a":"王哲","c":["缘重下手并安脚。顿得来、真真没错。金炉立起琼花作，烧炼出、这般丹药。", "三田九转明光烁。八脉上、四门开却。虚空一点成灼灼，无言说、自然邀约。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题扬子云草玄图","p":"","d":"明代","a":"谢榛","c":["蚕丛之国三秦西，千峰上与青天齐。栈道悬空历万险，巨竹脩藤当昼迷。", "瀑布砰訇响不绝，阴壑直下垂虹霓。班虎咆哮黑熊啼，飒沓风舞双鹍鸡。", "路出剑门沃野阔，锦江秋水明玻瓈。蜀中文物古来盛，两汉名士特标题。", "前有马卿后扬子，高才往往怀金闺。火德中衰世板荡，谁能皓首甘幽栖。", "枫树森森隐茅宇，荒凉门径无轮蹄。草玄拟易坐朝夕，冥心自得穷端倪。", "水有汀洲山有溪，居然此道在盐齑。龙蛇知时蛰深窟，男儿志气何乖睽。", "校书阁下独遗恨，首阳二子光蒿藜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"淮阴杂诗六首 其五","p":"","d":"清代","a":"邹祖符","c":["天花菌子色如银，青玉红樱缀满林。几日濯枝新雨过，鹧鸪声里采林檎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"直宿广文舍下","p":"","d":"宋代","a":"梅尧臣","c":["前夜宿广文，叶响竹打雪。", "昨夜宿广文，窗影竹照月。", "赖此数竿竹，与我为暖热。", "上有寒鹊栖，拳足如瘦蕨。", "平明欲飞去，唶唶若告说。", "我无喜可报，烦尔弄觜舌。", "亦尝苦老鸦，鸣噪每切切。", "为学本为道，穷蹙令素发。", "但能得酒饮，终日自兀兀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵公显见赠 其二","p":"","d":"宋代","a":"张纲","c":["年齐耆旧愧衰阳，懒性唯耽野趣长。了却官租更何事，君王约法已三章。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"睡起","p":"","d":"宋代","a":"陆游","c":["风约飞花满曲廊，萧然无客共焚香。", "瓮醅力重初投枕，鼻鼾声豪已撼床。", "栩栩梦游心自适，昏昏起坐日方长。", "静凭一几吾何恨，笑杀穿帘燕子忙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梦中赋秋望","p":"","d":"宋代","a":"王铚","c":["阁小寒宜远，林荒晚带风。", "遥山秋色外，独树雨声中。", "念起三生异，心伤万境同。", "此邦非我圣，随意作流通。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送张士皋归闽中","p":"","d":"明代","a":"虞堪","c":["阖庐城外草芊芊，西子湖边客上船。二月水生春自泛，三山日落梦相牵。", "鸱夷竟去沧溟远，杜宇还啼锦树妍。我亦欲归愁剑阁，风尘消息在何年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送张符禺吏部","p":"","d":"明代","a":"董其昌","c":["天门新辟日曈昽，茂宰先承湛露浓。巳见玺书褒卓傅，更将玉尺倚林宗。", "千秋良史看驯雉，九品何人鉴画龙。若向河梁听骊唱，鸣琴清响满花封。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"盘山驿","p":"","d":"明代","a":"庞尚鹏","c":["河东伐鼓急徵兵，河西鸣金催筑城。胡马南嘶无宁夕，良田万顷生荆棘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"简斯远兼怀成父","p":"","d":"宋代","a":"赵蕃","c":["闻道篮舆出行田，归来药裹手亲煎。旱而不雨热尤剧，节且立秋凉未便。", "我亦南山成卧疾，弟犹北阙未回船。江南已自伤流落，何况湖南路渺然。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"孟夏十有一日时雨初霁晨登高阁极目四望烟锁日出气象一新复用前韵","p":"","d":"宋代","a":"王十朋","c":["蝶梦惊回听残雨，鸟声唤起欣初晴。梵宫烟火带馀湿，黉舍几席生微清。", "披衣登阁忽四顾，顿觉远目增双明。樵渔欸乃雾中出，舟楫荡漾田间行。", "清和节物满眼界，柳垂暗绿花含情。窗明几净日渐永，天开地廓阴不争。", "俯视沧浪堪濯足，遥看扶桑观日浴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"暑夜玩月不寐","p":"","d":"清代","a":"杨浣芬","c":["皎皎晴天月，今宵喜又圆。无灯辉自满，有树影常穿。", "为爱频留盼，因炎愈怕眠。一轮如赤日，冷署也烘然。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和李祭酒韵","p":"","d":"明代","a":"罗亨信","c":["几年载笔侍明光，盛有才名播四方。超擢荣看登璧水，归田未许老柴桑。", "诸生侍讲闻霏玉，六馆循规戒履霜。造就英才为世用，人思德教永难忘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"点绛唇 喜芍药发芽","p":"","d":"元代","a":"王恽","c":["红叶当＊，朝来拨土红芽秀。画阑晴书。凭暖佳人袖。一粒丹砂，谁点仙根透。从今后。为渠酿酒。去作花闲友。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送王孝廉归柳州兼寄刘司理","p":"","d":"明代","a":"卢龙云","c":["风尘漂泊始龙城，岁月长悬旧友生。拙宦积薪殊未达，故人怀璞晚初成。", "比年抚字能为政，阖郡循良并有声。问讯江头曾种柳，并州他日总多情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"虞美人","p":"","d":"清代","a":"冒广生","c":["鸭炉兽炭销香篆。窣地帘慵卷。梨花寒食又黄昏。偏到黄昏唤起秭归魂。", "鸳屏鸾镜浑如旧。人影幢幢瘦。夜窗闲谱断肠词。剩有一镫如豆证相思。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登崆峒山","p":"","d":"元代","a":"乃贤","c":["缘萝陟层巘，旷望浮云驰。飘风西北来，飒飒吹裳衣。", "气候倏迁变，中怀郁歔欷。路逢一道士，高结冠巍巍。", "恐是广成子，再拜欲问之。长歌入深林，弃我忽若遗。", "哀湍泻石磴，日落松风悲。灵踪邈难及，千载生遐思。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"淳化乡饮酒三十三章","p":"","d":"隋代","a":"佚名","c":["喈喈黄鸟，载飞载止。", "我有旨酒，嘉宾式燕且喜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过西竺新庵","p":"","d":"明代","a":"何巩道","c":["阴阴林莽蔽西堂，树底停车巳自凉。游倦客皆青眼老，吟多僧亦白髭长。", "井窥天色沉秋日，城落帆痕曳夕阳。行到野塘花欲谢，曲栏空倚木樨香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵谢范黄中运管二绝","p":"","d":"宋代","a":"刘宰","c":["刁坞春回花满枝，沈溪梦断水盈池。", "遥知吊古经行处，落纸云烟总是诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同惟敬思伯夜泊浦口","p":"","d":"明代","a":"欧大任","c":["浦口青枫夕照迟，天涯飘泊更何之。船迎张翰因同载，笛遇王猷更一吹。", "渔父每从醒客问，海翁今谢白鸥疑。十年已共江潭远，岂傍啼猿怨竹枝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"证道歌","p":"颂证道歌","d":"宋代","a":"释印肃","c":["莫将管见谤苍苍，井底蛙牛逞巨江。", "乾坤大地一只眼，用来还似一毫芒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫籍监 其四","p":"","d":"宋代","a":"文天祥","c":["军衙马足起黄埃，门掩西风梦正回。自入燕关人世隔，隔墙忽送市声来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其十","p":"","d":"宋代","a":"朱浚","c":["米车已过尘迷路，渔网才收月满船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"渔父歌二","p":"","d":"唐代","a":"欧阳炯","c":["摆脱尘机上钓船，免教荣辱有流年。无系绊，没愁煎，须信船中有散仙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅花四首 其一","p":"","d":"宋代","a":"谢薖","c":["姑射神游阅九关，水精宫殿不胜寒。下窥人世生尘想，故作梅花与俗看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题《各家和＜万岁墙诗＞集录》","p":"","d":"当代","a":"何永沂","c":["山寨飘摇万岁墙，栏杆拍遍雨飞霜。今吾醉里挑灯看，几代诗人血泪藏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠刘山人蔬具为供宾费时山人适招洪广文别","p":"","d":"明代","a":"林大春","c":["问道广文招，此物聊当肉。昨宵当座谈，讵敢然诺宿。", "况复邻家子，伏雌方在掬。墙头遇酒尊，新秋酝已熟。", "但愿天气凉，孤亭夜深酌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"有所叹二首 其二","p":"","d":"宋代","a":"唐庚","c":["耕田佩印两徒然，忆相平津只去年。怪底功名称地狱，谁将官府到天仙。", "是非已付渔樵判，疑信难凭党与传。杯酌岂能通大道，床头当得酒如泉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏日赴监察许君之宴同张监察","p":"","d":"明代","a":"李梦阳","c":["霜府池亭夏亦寒，捲帘河岳火云残。筵开冰动琅玕簟，酒伴瓜行白玉盘。", "蓦石寻花时径往，跃鱼投饵晚留欢。孰教逃暑陪骢马，自分清朝老钓竿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"章靖冯公哀词","p":"","d":"宋代","a":"宋祁","c":["睆箦绵疴革，中楹奠梦还。", "蕝仪犹在野，书副即藏山。", "友酹生刍洁，君恩刻印颁。", "一朝交臂失，宁复易睎颜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"柏堂对月和周升逸","p":"","d":"清代","a":"岑霁","c":["柏堂今夜月，云物不能侵。对此碧空净，闻君《白雪》吟。", "入帘明鹤发，绕树见禽心。坐觉清言久，疏钟报隔林。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重过拂水山居经宿遂撤新楼开竁域主人复申墓田耦耕之约有述","p":"","d":"明代","a":"程嘉燧","c":["隔岁寒梅压路横，过年风槛纸窗鸣。岩扉静掩涓涓户，山阁俄开郁郁城。", "新表伫归华鹤语，生刍与怅白驹行。松堂丙舍仍招隐，投老看君誓墓情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答胡苇杭","p":"","d":"宋代","a":"仇远","c":["久矣相期物外游，长风吹不断闲愁。", "两山翼翼青如舞，霜鬓颾颾白始休。", "蕉鹿梦回天地枕，莼鲈兴到水云舟。", "旧藏方镜明如月，看去看来又一秋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春日吴子雨过山居作","p":"","d":"明代","a":"王宠","c":["雨重烟浓山更深，半窗楼阁昼阴阴。道书一卷香凝榻，岩翠千层鸟堕林。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"桂","p":"","d":"清代","a":"弘历","c":["露重槛风凉，迎阶绿间黄。中秋先报节，隔岁入吟章。", "一例皋涂种，偏依楚畹芳。谁曾到蟾窟，此处满天香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"恭读理斋常太翁老先生殉节录 其一","p":"","d":"清代","a":"曹殿魁","c":["谩言明哲保生全，凡圣分途岂泛然。肘腋难防身外变，肝肠不改性中天。", "夕阳一片悲辽鹤，夜月三更泣蜀鹃。十六年来题旧恨，几行清泪笔头传。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"行次淮安甘蔗因悼同门友被谴没于京","p":"","d":"明代","a":"王恭","c":["伤心不见旧同游，离思萧萧醉未休。暮雨门临青蔗圃，夕阳潮到白沙洲。", "几家烟火遗民在，千里江陵去国愁。莫怪行人倍惆怅，羊昙何事泣西州。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题骖鸾阁","p":"","d":"宋代","a":"莫俦","c":["群山带雨阴云重，沧海连天水气昏。遥想真人乘铁舸，往来三岛鬼神奔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"才临复日","p":"鹊桥仙","d":"宋代","a":"佚名","c":["才临复日，便逢生旦，料想门阑多喜。好将何物寿冰翁，但有个、新词为礼。如今已办，一千馀阕，尽按宫商角徵。一年一阕祝椿龄，自今日、从头数起。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"次韵和文访，并示同社","p":"","d":"近代","a":"连横","c":["寥落存吾志，徬徨看众迷。危言惊市虎，不寐听晨鸡。", "木折风敲户，寒侵雨满蹊。讨春迟旧约，诗卷共提携。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"日暮游东涧 其一","p":"","d":"宋代","a":"释重显","c":["极目生晚照，溪云偶成朵。大朴曾未分，青山自唯我。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"张郎中籍远寄长句开缄之日已及新秋因举目前仰酬高韵","p":"","d":"唐代","a":"刘禹锡","c":["南宫词客寄新篇，清似湘灵促柱弦。京邑旧游劳梦想，", "历阳秋色正澄鲜。云衔日脚成山雨，风驾潮头入渚田。", "对此独吟还独酌，知音不见思怆然。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"饱食卒岁因之自警四首 其三","p":"","d":"明代","a":"郭之奇","c":["日月将穷节，民神合聚时。鱼冰坚泽腹，蚕火照田丝。", "观蜡因人乐，退公或自私。作糜名口教，授粲岂徒期。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"揖舜自爪哇来访，联吟竟夕，余有“得句花间夜报钟”，意未尽，别后再寄","p":"","d":"近代","a":"黄松鹤","c":["天外人怀旧偃松，堂无客到苦尘封。村斋初下清凉榻，野径曾留洒落踪。", "夜半引杯三尺剑，花间得句一声钟。行程险为耽诗误，此去云山又几重。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"论诗次铁庐韵 其八","p":"","d":"清代","a":"丘逢甲","c":["四海横流未定居，千村万落废犁锄。荆州失后吟梁父，空忆南阳旧草庐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"古意十四首 其十","p":"","d":"宋代","a":"章云心","c":["吉凶本由人，往事皆可覆。祸人还自祸，福人还自福。", "于公果传世，李斯竟夷族。豺狼不知寤，纷纷方择肉。", "达者识几微，为之先痛哭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晦窗半梦谢堂雪樵以酬和诗见示步韵为和","p":"","d":"当代","a":"吴金水","c":["云边逸兴接天浓，莫道明时有不容。每遇高朋邀白酒，常闻大吕应黄钟。", "奚囊已被烟霞足，鬓雪还蒙岁月供。他日谁招舞雩会，清风千里亦相从。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"岁暮旅怀五章 其四","p":"","d":"清代","a":"姚燮","c":["非无御冬粮，思我苦萧瑟。结其思我心，照空作明月。", "明月人不见，我独见真切。此光无溢明，但照我心密。", "遂使异地身，如已在家室。吴山何幽深，越山何崷崒。", "倏此一寸心，磊磊与萦结。且复垂重帏，以我梦飞越。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"张固","c":["鹿石晓寒云漠漠，虎溪春浅水潺潺。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戴帅初九日无憀以满城风雨近重阳为韵七首袖","p":"","d":"宋代","a":"陈著","c":["年年好时节，雪月花与风。", "谁知百年内，忧乐元不同。", "方其少壮日，日日醉梦中。", "年年旋衰飒。有景谁复穷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雪中送舒文质归广信","p":"","d":"明代","a":"蓝智","c":["积雪千峰迥，空林一鸟归。", "客愁南浦树，乡梦北山薇。", "风雨荒茅屋，兵戈老布衣。", "饥寒兼盗贼，出处寸心违。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丙午九月十二日新定仰辰台同周自正郑孔新谢振卿扳跻登望浩歌而归","p":"","d":"明代","a":"湛若水","c":["仰辰台上仰辰游，一曲歌声彻九州。感得圣恩深似海，外臣早许作巢由。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"漫作","p":"","d":"金朝","a":"王特起","c":["有时幽鸟话心事，无限秋虫誇口才。北阙上书吾老矣，东篱把菊思悠哉。", "竹林留得巨源在，莲社招入渊明来。不然馀子败人意，怀抱耿耿胡为开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"陶与权南园别业","p":"","d":"元代","a":"黄玠","c":["琼田无恶土，玉树多好枝。鼎角匿犀者，自是名家儿。", "应门有暇日，颇作佳园池。朝临二王书，暮吟三谢诗。", "花边迎小车，竹下理残棋。宾至可命觞，亲在志无违。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄谢左子方声寄沈均德笔二枝","p":"","d":"明代","a":"刘崧","c":["抱病归来卧一窗，思君安得酒盈缸。沈家好笔无钱买，多谢新来寄一双。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"双桂卷为河南吴进士升作","p":"","d":"明代","a":"吴宣","c":["云帘雾箔隔仙都，八月天河见玉肤。忆自二郎相别后，素娥无梦碧鸾孤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅花喜神谱 其七 大开一十四枝","p":"","d":"宋代","a":"宋伯仁","c":["举头见长安，志士欣有托。葵藿一生心，岂容天负却。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏木钵","p":"","d":"清代","a":"弘历","c":["拥肿乖绳墨，谁施月斧修。居然五石瓠，那数一株榴。", "虚满皆如愿，色空莫可求。堪因遗阐士，渡海不惊鸥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读朱晦庵注参同契","p":"","d":"明代","a":"陈献章","c":["神仙不注参同契，火候工夫那得知。千古晦庵拈一语，可怜无及魏君时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过瑞龙观道士","p":"","d":"唐代","a":"钱起","c":["不知谁氏子，炼魄家洞天。鹤待成丹日，人寻种杏田。", "灵山含道气，物性皆自然。白鹿顾瑞草，骊龙蟠玉泉。", "得兹象外趣，便割区中缘。石窦采云母，霞堂陪列仙。", "主人善止客，柯烂忘归年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄郑生二首 其一","p":"","d":"明代","a":"李梦阳","c":["故菊开谁对，新醪怅尔违。耳憎木叶下，心与塞鸿归。", "儿女催蓬鬓，家园滞綵衣。问君称庆暇，何处采山薇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长安四时辞四首 其一","p":"","d":"明代","a":"胡应麟","c":["携手七香车，春风向狭斜。燕姬年二八，烂醉碧桃花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂诗","p":"","d":"近代","a":"黄侃","c":["女萝何袅袅，松柏生崇岗。因缘自同体，欢悦诚难忘。", "常恐寒风至，弱身付严霜。相依虽不久，执节固有常。", "君身上青云，万岁何讵央。妾身委尘埃，还在深根旁。", "脩短自有命，焉能咎穹苍。良辰宜出游，相期得何许。", "或在上宫旁，或在浍之浒。见时舜婆娑，别时泪如雨。", "常恐华色衰，弃捐等尘土。视尔若朝霞，桃李非其侣。", "各保盛年欢，何为有愁苦。莫嫌昼作宵，缱绻常从汝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"岁暮宿锦岩偕邓粤仁兄弟","p":"","d":"明代","a":"甘学","c":["雪夜三人心，抱膝梅花林。梅香不见影，山谷衡门深。", "赓歌李太白，宁怯岩寒侵。豪气凌斗杓，孤兴千仞岑。", "举声叱山鬼，惊起眠枝禽。何如邓二仲，与我雄一襟。", "此事几千古，今作卧龙吟。明发各乃别，载阳复相寻。", "共期登大科，再弄天风琴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"御赐真赞师演成四偈 其四","p":"","d":"宋代","a":"释宗杲","c":["随物现处，廓清寰宇。不动神情，气吞项羽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏怀二首 其二","p":"","d":"宋代","a":"宋祁","c":["尽信书奚信，难言命敢言。竟谁成简册，无客问乾坤。", "值狩麟犹泣，遭君鹤乃轩。滔滔千古事，惟有付芳樽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"香山即景杂咏 其一","p":"","d":"清代","a":"弘历","c":["好山岂虑秋光老，洗尽繁华越雅宜。兴会悠然重九近，底殊五柳得诗时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宿良田草阁","p":"","d":"明代","a":"梁以壮","c":["停鞭只合沽村酒，野菜连根上一盘。邻妇夜舂吟外听，隔山残烧坐中看。", "松梢落月床全白，雪气冲裘影并寒。空有石波老巡吏，对人深解路行难。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题徐氏溪亭二首","p":"","d":"明代","a":"王慎中","c":["浯水日悠悠，虚亭压水头。", "棹歌喧极浦，峰翠漾中流。", "每夜偏多月，长天只似秋。", "更添幽事并，系柳木兰舟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重阳后一日登石钟寺","p":"","d":"明代","a":"梁以壮","c":["渡水闻声见石钟，石钟之上见芙蓉。无多野客乘秋屐，有个僧人制毒龙。", "鸿影不期黄叶到，菊花那许白云封。一尊须补重阳醉，酌对匡山五老峰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水调歌头 送李经历","p":"","d":"元代","a":"唐桂芳","c":["白头閒父老，都说幕中宾。杜门鹤立，风雨不遣客来频。", "果是清心苦节，能障狂澜砥柱，矻立势千钧。吹散浮云了，依旧月如轮。", "忆公馀，携印绶，出城闉。酒船醉舞，江月还似谪仙人。", "好理木天文字，便许玉堂标致，笔下信通神。离恨正无赖，杨柳不胜春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"冬夜八首 其七","p":"","d":"清代","a":"黄文仪","c":["江星云外落，海日地中来。水碧浮天镜，霞红照玉台。", "几株枫树雪，数朵陇头梅。报晓钟初击，霜寒落叶豗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"从军行","p":"","d":"明代","a":"屠滽","c":["马上黄沙拂面行，汉家何日不劳兵。匈奴久自忘甥舅，仆射今谁托父兄。", "云外旌旗婆勒渡，月中刁斗受降城。左贤早待长绳缚，莫遣论功白发生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"小游仙七首 其五","p":"","d":"宋代","a":"周密","c":["一径松花满路香，琤琤玉杵捣玄霜。有时骑鹤月中去，流水白云生晚凉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古十一首","p":"","d":"宋代","a":"释智鉴","c":["云巢梦断月华秋，玉女翻身过斗牛。", "卸却花冠归旧隐，玄途鸟道未容收。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"皇城曲","p":"","d":"元代","a":"袁桷","c":["堂堂瞿昙生王宫，幼年夙悟它心通。梵书未睹口已诵，底用城阙穷西东。", "净居老人幻境异，故作恐怖生愁容。世间习妄了莫喻，要以神化开盲聋。", "岁时相仍作游事，皇城集队喧憧憧。吹螺击鼓杂部伎，千优百戏群追从。", "宝车瑰奇耀晴日，舞马装辔摇玲珑。红衣飘裾火山耸，白伞撑空云叶丛。", "王官跪酒头叩地，朱轮独坐颜酡烘。蚩氓聚观汗挥雨，士女簇坐唇摇风。", "人生有身要有患，百岁会尽颜谁童。西方之国道里通，至今生老病死与世同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送毕文明之寿州","p":"","d":"明代","a":"郑真","c":["浮空鸾鹤影飘飘，肥水青春远见招。剩有周诗留翰墨，可无杜酒劝琼瑶。", "董生孝行今何在，霍叔流风尚未消。落日苍茫赋怀古，彩毫毋惜寄云轺。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送徐水部奉使荆关 其五","p":"","d":"明代","a":"倪元璐","c":["占天太史上星台，楚分媭星逼上台。召去君王如有问，须言红叶是良媒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"至日过徐德章","p":"","d":"明代","a":"何景明","c":["竹门寒旭凤城隈，春气潜浮地底灰。世路十年长不定，客怀此日更难开。", "天边梅柳垂垂发，岁暮阴阳冉冉催。见说吴江酒船到，即𢬵留饮夜深回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠别周别驾王司理入京十四首 其九","p":"","d":"明代","a":"顾璘","c":["行行及辰良，律转寒序毕。东风来几时，江草忽青出。", "幽鹭濯轻澌，疏梅耀迟日。兰棹从此逝，佳兴谅非一。", "倘赋清水篇，贻我慰萧瑟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"命免天津府及顺天府所属积欠诗以志事","p":"","d":"清代","a":"弘历","c":["休助古有云，怀保今所勉。昨岁此地灾，赈赒期均遍。", "巡方兹目睹，幸逭沟壑转。然未经见多，加惠讵宜缓。", "两府界壤连，受沴苦弗浅。三州及八县，旧欠概与免。", "武清独无欠，岂不向隅叹。蠲供十之五，用意旌良善。", "麦收倘得半，庶少济屯蹇。是惟赖天恩，非吾力能办。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宿尼什哈站","p":"","d":"清代","a":"杨宾","c":["水经玄菟黑，山过混同青。漫道无城郭，相看有驿亭。", "糠镫劳梦寐，麦饭慰飘零。明发骑鞍马，萧萧逐使星。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"象川林少参旅顾致谭二守瓶台故人消息","p":"","d":"明代","a":"区元晋","c":["烹鲜手易调商鼎，制锦才堪补舜裳。恰喜薇垣相邂逅，共谈棠泽见声光。", "兵馀败垒愁云黑，乱后遗墟宿草长。闻说海防成峻筑，已曾借手障濒方。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赵城至洪洞道中口占","p":"","d":"近代","a":"张瑞玑","c":["飞絮飞花三月时，东风剪剪柳丝丝。", "断桥流水青山外，匹马寻碑纪信祠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"出婺城","p":"","d":"宋代","a":"苏泂","c":["万顷平田雪，前村昨夜梅。", "梦还荆国旧，吟欠兔园才。", "只作寻诗去，何曾为酒来。", "兹行得奇事，夹道有琼瑰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"八声甘州 上龈牙脱，仅存一枚，独力支唇，闷而有作","p":"","d":"清代","a":"吴重憙","c":["都呼朋引类，独伊人，情深尚坚牢。似霜高木落，观撑一柱，山峙单椒。", "想见灵岩钟乳，滴久宛垂条。障碍有时去，去更无聊。", "未吃红绫饼馅，笑残牙老口，难肆贪饕。效龙须拔去，逊太真豪。", "将无如、东山赌墅，罢残棋、屐折触嶕峣。莫学彼、衰年作戏，孺子牛嘲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谢飞卿饭","p":"","d":"元代","a":"耶律楚材","c":["一鞭羸马渡天山，偶到云川暂解鞍。独守空房方丈稳，更无薄酒一杯残。", "诗书半蠹绝来客，釜甑生尘笑冷官。赖有觉非怜野拙，长须为我馈盘餐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重阳后三日饮彦成宗侯宅","p":"","d":"明代","a":"苏升","c":["九日登台兴未阑，侯门犹得更追欢。秋涵桂树香风远，月入梁园夜色寒。", "白雁先霜何处度，黄花一径借相看。酣来作赋多公等，授简低头愧子安。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨蛮八首 其六","p":"","d":"清代","a":"余一鳌","c":["琵琶隔舫瓜州月，月明风静人离别。别意满侬怀，怀中豆蔻胎。", "郎如风漾絮，妾似花沾雨。雨细蝶飞迟，迟君杨柳枝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"烟浦","p":"","d":"宋代","a":"沈说","c":["烟浦残鸦舞夕阳，风枝病叶似初霜。", "眼中秋中十分净，沙外寒流一线长。", "溪女得鱼烹碎白，田家收谷曬新黄。", "偶寻野趣归来晚，草际萤飞点点光。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再次韵二首 其一","p":"","d":"宋代","a":"陈造","c":["雪神不袖嘘枯手，嗣岁丰登预告成。泚笔径烦书上瑞，载涂况已沸欢声。", "骑驴有客搜新句，扶路何人趁晚晴。一笑与渠分乐事，的知琼露胜宜城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋居杂咏十首","p":"","d":"宋代","a":"李弥逊","c":["穷秋杂花远，眷此霜下杰。", "明金委珞璎，宝璐缀环玦。", "依依风递兰，皓皓日穿雪。", "若无夭冶姿，不受众目悦。", "共杯泛其英，揽之肠为结。", "谁能踵高门，持以浣中热。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"圆山庙","p":"漳南十咏","d":"宋代","a":"蔡襄","c":["风雅遗芬岳有神，此山灵祀越千春。", "彩毫佳句言犹在，翠剡新词意未真。", "绝顶黑林长带雨，曲崖飞磴不留尘。", "瘴云收尽秋田熟，跋境肴浆再拜人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"齐天乐五十首 其十九","p":"","d":"清代","a":"端木埰","c":["几年同儤薇垣值，风流快从觞咏。潭水桃华，幽山桂树，那更深情逸性。", "离怀骤警。况取次东风，一麾先秉。怕是它时，不胜怊怅此情景。", "多君风义近古，有中台宝笈，招共删订。抉汉分章，承云奏雅，羊鹤还愁不竞。", "清言快领。趁明月犹圆，碧天澄镜。四印斋中，一尊相共请。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和龚使君韵","p":"","d":"宋代","a":"文天祥","c":["淡和心事葛天民，回首归来清渭滨。", "长倩君宝孙子行，道原义仲辈流人。", "一生受用忘非是，万事升沉等故新。", "近日贞元朝士少，蒲轮有命出枫宸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感物二首","p":"","d":"唐代","a":"唐彦谦","c":["騄骥初失群，亦自矜趫腾。俯仰岁时久，帖然困蚊蝇。", "豪鲸逸其穴，尺水成沧溟。岂无鱼鳖交，望望为所憎。", "物理有翕张，达人同废兴。幸无怵迫忧，聊复曲吾肱。", "鱼目出泥沙，空村百金珍。豫章值拥辏，细细供蒸薪。", "论材何必多，适用即能神。托交何必深，寡求永相亲。", "鲍叔拙羁鲁，张生穷厄陈。茫然扳援际，岂意出风尘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"净光松风阁","p":"","d":"宋代","a":"叶适","c":["城中云日如火催，净光行食声转雷。", "不知何处白蘋起，便有满坐清风来。", "莫言作楼非急务，翁当运斤儿执锯。", "待得三间着此风，病叟扶携上楼去。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"任秋田明经读书祇园庵柯岩之游拟枉道过访骤雨不果诗以寄怀","p":"","d":"清代","a":"曹寿铭","c":["绝磴苍茫俯碧浔，烟萝寂寞此登临。已餐石气清诗骨，欲就禅花证佛心。", "隔岸云山无鹤导，满湖风雨作龙吟。归舟怅望江头路，杳杳疏钟度水深。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古三十首 其十八","p":"","d":"宋代","a":"释怀深","c":["法身无相，法眼无瑕。因风吹火，借水献花。丝毫不立，万别千差。", "但看来年三二月，衔泥燕子入人家。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿吴隐君希学七秩","p":"","d":"明代","a":"胡应麟","c":["君平曾寄蜀，尹喜尚留秦。杏植三千亩，桃偷七十春。", "壶中长宇宙，屐底半星辰。白日飞鸡犬，无劳颂大椿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晋阳怀古 其六 怀阳谏议","p":"","d":"明代","a":"何乔新","c":["晴壑凝黛色，寒溪漾澄流。眷昔阳谏议，韬光此夷犹。", "贤声彻黼座，徵诏来林丘。遂辞鹿豕群，去与鹓鹭游。", "谓公当謇謇，而公但悠悠。青蝇忽止藩，贤相投荒陬。", "公乃叩阁争，累疏不自休。精忠贯皎日，劲气凌清秋。", "白麻不果降，憸佞恚且羞。公殁数百载，士风日以偷。", "旖旎荃与蕙，兹焉化为茅。朝阳无鸣凤，立仗多骅骝。", "思公不可见，怅然抱孤忧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋华十咏次如山 其四 孩儿菊","p":"","d":"明代","a":"邵宝","c":["菊名非菊恨虚闻，中有幽香为解纷。采采秋风篱落畔，独嫌荒草欲教芸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"金陵秋兴八首次草堂韵 其七","p":"","d":"明代","a":"钱谦益","c":["铃索警传航海功，秋宵蜡炬井梧中。冯夷怒击前潮鼓，飓母谁催后鹢风？", "蛟吐阵烟掀浪黑，猩殷袍血射波红。秦淮卖酒唐时女，醉倒开元鹤发翁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"薄倖 追悼沈姬","p":"","d":"清代","a":"薛时雨","c":["烟波江上。旧曾共、桃根打桨。记王粲、客游无绪，累尔伶仃相向。", "争兰桡、双载人来，经年不载人同往。叹逝水无情，罡风太恶，人与落花并葬。", "生就了、聪明性，应悟彻、尘因俗障。梦中傅幽怨，声声诉出，夜台多少凄凉况。", "一灵无恙。趁归舟、安稳玉箫，重侍韦皋帐。吟成楚些，付与秋坟鬼唱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清平乐","p":"","d":"清代","a":"张尔田","c":["唾绒残线。界破红妆面。浓睡醒来莺语懒。又是斜阳小院。", "麝薰微度罗衣。雨余栀子添肥。贪画远山一角，不知蹙损双眉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"少年游 兰江吟眺","p":"","d":"清代","a":"姚燮","c":["四山眉爽入横漪。画色满江扉。夕日明来，水烟散去，风絮落微微。", "碧遥青远知何极，坐对息尘机。北溆鸥群，西湾渔桨，来往总相依。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舟次邗江感怀","p":"","d":"清代","a":"戴研","c":["寒云萧瑟片帆收，江草江花动客愁。瓜步涛声常带雨，广陵山色易为秋。", "已拚湖海供多病，漫逐风尘故倦游。寂寞仲宣怀故里，不胜摇落赋《登楼》。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送于制干二首 其二","p":"","d":"宋代","a":"释宝昙","c":["一笑无烦论古今，就中首肯即吾真。君今正与司南合，直指何曾更问人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠三乡浮图智聪","p":"","d":"宋代","a":"尹洙","c":["伊昔相逢日，于今二十年。师随安乐住，我岂利名牵。", "自笑真徒尔，何如养浩然。西门女几路，未得赋归田。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"济宁逢春二首 其一","p":"","d":"明代","a":"潘希曾","c":["忽忽浮生已向衰，悠悠拙宦竟何裨。碧山笑我红尘久，青镜输谁白发迟。", "治水可能寻禹迹，转漕亦复托萧规。梦游不觉长安远，应被春风昨夜吹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和陶渊明饮酒 其四","p":"","d":"元代","a":"戴良","c":["一鸟乘风起，逍遥天畔飞。一鸟堕泥涂，噭噭鸣声悲。", "升沉亦何常，时去两无依。我昔道力浅，磬折久忘归。", "迩来解其会，百念坐自衰。惟寻醉乡乐，一任壮心违。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望江南 其十","p":"","d":"清代","a":"董元恺","c":["茶候静，帘卷日初长。片甲味分蝉翼薄，丹丘阴益簟纹凉。", "应唤醒羲皇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"罢徐州，往南京，马上走笔寄子由五首 其三","p":"","d":"宋代","a":"苏轼","c":["古汴从西来，迎我向南京。东流入淮泗，送我东南行。", "暂别复还见，依然有馀情。春雨涨微波，一夜到彭城。", "过我黄楼下，朱栏照飞甍。可怜洪上石，谁听月中声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"证道歌","p":"颂证道歌","d":"宋代","a":"释印肃","c":["第一迦叶首传灯，百万人天耸耳听。", "金色头陀闻不会，拈花起处笑尖新。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水曲纳凉","p":"","d":"明代","a":"何景明","c":["乘月玩清夜，漱流涤烦痾。竹柏夹脩水，微风扬泽荷。", "苔阴皓露溽，素鳞跃于波。柔条纷敛结，劲叶亦陨柯。", "优游荡情志，俯仰丘中阿。虽无朋侪和，兴言自成歌。", "娱乐当及时，千秋岂复多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"相见欢","p":"","d":"清代","a":"易顺鼎","c":["水亭残雪连空。月如弓。添个骑驴人在冻云中。", "吹玉笛。落瑶砌。又悤悤。只有梅花全不忆东风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"为杨廷献题画六首 其五","p":"","d":"明代","a":"张宁","c":["路僻无忙步，林空有远情。幽寻行复坐，诗绪乱还清。", "水到荒矶绝，云依野树生。何时休世念，来与尔同盟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"念奴娇 咏玫瑰花","p":"","d":"清代","a":"陈维崧","c":["陡惊春去，算风光此际，又逢樱笋。拂晓谢娘帘阁畔，忽逗卖花声韵。", "篮底氤氲，担头狼籍，紫艳浓香喷。佳人竞撚，看来和露尤俊。", "最爱别样心情，天然梳掠，偏厌红英衬。揉得花魂魂尽碎，另作一番安顿。", "焙入衾窝，薰归裙缝，细细调红粉。玉郎不觉，错疑戴向云鬓。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次介叔韵","p":"","d":"宋代","a":"刘跂","c":["酒船定向江东去，知有风流贺季真。北岭南冈元自熟，短杨高柳迩来新。", "老吾官职浑无味，壮子文章最有神。知欲弦歌且三径，徵君莫自傍风尘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"进帆石门怀古","p":"","d":"明代","a":"陈子升","c":["卢城伤飒沓，郁水引游衍。虽非千里驾，发棹自成远。", "郊原互盘纡，洲渚迭溶演。水波舷下割，日影帆上转。", "巀嶪开一门，澄鲜豁双眼。层阿蔓绿萝，阴石滋斑藓。", "坎流知所止，井汲当自选。怀金泉靡堙，不易心弥显。", "讵以朵颐龟，取笑饮河鼹。亮为江海人，独契蘧生卷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其一","p":"","d":"宋代","a":"梁周翰","c":["谁似金华杨学士，十联诗在御屏间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂二十四首","p":"","d":"宋代","a":"释智遇","c":["出山而见，入户而知。", "鸡棲凤巢，邻壁之辉，", "何必区区点缀伊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病中雨夜寄悯茎上人二首 其二","p":"","d":"明代","a":"何吾驺","c":["永夜禅心寂似冰，未须善识为传灯。漏残无耐穿窗雨，拈韵题诗寄老僧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"跋希远细雨图","p":"","d":"宋代","a":"曹勋","c":["牵风藻荇舞清漪，浪板无声细雨时。", "小大自殊同队乐，密图劝学助韩诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"崤函怀古","p":"","d":"清代","a":"刘东里","c":["两峰高矗郁苍苍，旧说山河百二强。天转星辰迎夏后，山排风雨扈周王。", "神皋东据《西都赋》，鬼哭今留古战场。欲吊兴亡千载事，淡烟衰草又斜阳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠卫武孟 其一","p":"","d":"明代","a":"殷奎","c":["桑海茫茫不可论，衣冠乡里几家存。咸阳渡口秋风里，惊见开禧执政孙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春尽同诸公游紫岩各赋六言","p":"","d":"宋代","a":"吴芾","c":["一径草深迷路，万点花飞到天。明日定知春去，祇今便是残年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋夜宿殊胜寺","p":"","d":"明代","a":"李时行","c":["看竹过山寺，开樽值素秋。风清众籁寂，水落寒岩幽。", "僧定月当户，鹤归云满楼。醉来卧松石，天地等浮沤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送张黄门经载使云贵","p":"","d":"明代","a":"罗钦顺","c":["峥嵘双阙中霄起，谏垣近在红云里。元气潜随北斗移，龙司出内虞廷理。", "地分清切须英豪，遐想虞廷梦亦劳。簪缨于我诚何有，却恐言高位不高。", "同年磊落张经载，封事频投心欲惫。弘恭恻目惮更生，潞公敛衽钦唐介。", "世道明须我辈扶，当机缘底太模糊。轻裘骏马长安道，合有人间大丈夫。", "如君夙夜宜青琐，春风忽泛湖南舸。黯薄淮阳计不疏，褒求金马谋全左。", "也知今日重安边，边务惟应足食先。要令万灶貔貅饱，须杜千仓雀鼠穿。", "青袍拂曙辞金殿，出门步步频留恋。已料先声动五溪，即看行色摇芳甸。", "日暖官河柳絮飞，清尊欲尽思依依。往来万里多闻见，奏草能令在外稀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书房","p":"","d":"宋代","a":"戴炳","c":["书房清晓焚香坐，转觉幽栖趣味真。怪石一根云态度，早梅半树雪精神。", "池鱼自乐谁知我，林鸟相忘不避人。得丧由来天自定，莫将闲虑恼闲身。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"黔娄妻","p":"咏史八首","d":"宋代","a":"蒲寿宬","c":["明知正不足，不若斜有馀。", "破衾有何好，锦绣乃不如。", "卓哉归人言，贤于五车书。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"漫兴 其四","p":"","d":"清代","a":"林占梅","c":["饭馀聊息苦吟身，学罢熊经学鸟伸。晴日半窗花影碎，凉阴一院蝉声频。", "闭门但作仇书客，入座时为战茗人。漫道悠悠过岁月，閒中随处见天真。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"除夕和陈峰湖","p":"","d":"明代","a":"黄衷","c":["尘世都交等大傩，微名应未怨蹉跎。灯花夜色寻常动，榆荚春光积渐多。", "霜里乌啼天已白，眼前民瘼鬒先皤。丁宁莫作罗浮梦，惭愧山中看奕柯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"黄菊二十首","p":"","d":"宋代","a":"史铸","c":["满地黄花得意秋，移来庭槛助清幽。", "自级禀性天生异，不与繁华混一流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清明诗","p":"","d":"宋代","a":"赵鼎","c":["乡书难附北归云，燕子犹寻旧主人。流水迢迢长念远，飞花糁糁又伤春。", "向来轩冕非吾意，何处园林托此身。只有长歌一樽酒，暮年风味最情亲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"莺掷垂杨","p":"蝶恋花","d":"宋代","a":"李久善","c":["莺掷垂杨，一点黄金溜。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"暇日寓怀寄朝中亲友","p":"","d":"唐代","a":"薛能","c":["命与才违岂自由，我身何负我身愁。临生白发方监郡，", "遥耻青衣懒上楼。过客闷嫌疏妓乐，小儿憨爱□貔貅。", "闲吟一寄清朝侣，未必淮阴不拜侯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"兰溪郊行","p":"","d":"元代","a":"曹伯启","c":["羸骖乘暇阅山乡，风景无边眼力强。千里稻云蒸大冶，一年梅澍积深塘。", "虎狼窜伏天刑近，鸡犬舒徐日驭长。微禄每惭无补报，欲将心事效平阳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丙午乡试领荐乡人聚观于会江门外马上口占一绝","p":"","d":"明代","a":"邹智","c":["龙泉庵上苦书生，偶窃三巴第一名。天下许多难了事，乡人何用太相惊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题烟波泛舟图","p":"","d":"明代","a":"刘基","c":["旧游忆鼓湘湖棹，日净风微江练平。", "小艇曲穿花底出，游鱼相伴镜中行。", "别来漫想心徒切，画里重看眼亦明。", "素石苍松是何处，愿从巢父濯冠缨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"为超然道人作云卧庵 其一","p":"","d":"宋代","a":"韩驹","c":["窣堵西头屋数楹，知君卧占一溪云。老夫亦有缘云兴，应为情亲肯见分。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"證道歌 其四十五","p":"","d":"宋代","a":"释印肃","c":["调古神清风自高，忘荣傲世性坚牢。示一往还无个事，见人摇手莫忉忉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"村姑二首 其一","p":"","d":"宋代","a":"宋伯仁","c":["翠鬟双妥未梳头，纺纬车边坐欲羞。几度采桑归较晚，阿娘疑看落花愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清平乐　四月十夜坐肖处作《语不得语歌》，十一夜追赋，其年韵","p":"","d":"当代","a":"卢青山","c":["棋茶都罢，几句家常话。最好相看千哑哑，一任腹中涛打。", "春窗月泻烟笼，零零碎碎时钟。忽尔一声长叹，索然处汝霜风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"减字木兰花 其二十二","p":"","d":"宋代","a":"沈瀛","c":["琴心和止。姹女与君相对喜。窗牖藏风。每唤其名应即通。", "玉英金酒。更唤黄婆同饮寿。莫讳人何。见说婴儿屋里多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"首夏即事与丘与权同韵作","p":"","d":"宋代","a":"苏颂","c":["朱曦渐永烦暑添，薰风当昼飘前檐。", "庭幽门邃搴帷帘，景物轩豁欣窥觇。", "方池绿莹波文恬，两傍森森生苇蒹。", "新荷未展排青尖，上下交映开鉴奁。", "园林果实繁李棎，原野麦秀胜稻稴。", "群飞众走羽毛彡，求阴息影愁烹焰。", "江南郁蒸非类痁，时虽早热人心恹。", "忻忻笑语喧闾阎，言此丰岁将饫餍。", "正阳用事何太廉，乃使阴沴相陵詹。", "正当汗浃絺衣粘，凄风忽生增纩缣。", "淫霖旬日横流沾，市井郊郭皆渰淹。", "林实坠落谁撦挦，麻麦散乱如删鎌。", "斯民愁嗟言成谵，我时忧思坐间檐。", "方食不知味苦甜，整齐几案抽书签。", "发策一以天人占，少阴乘阳时最嫌。", "小人当此多欺憸，君子遇之难怀谦。", "天道虽远诚可瞻，上曰高明下沈潜。", "四时中分寒与炎，一气不可相并兼。", "推本事理知悉纤，灾害所起由渍渐。", "岂非奸孽当除歼，又非直道伤诐譣。", "孰居鼎鼐调梅盐，孰任阃闑怀韬吟。", "圣皇言动谋於佥，布为利泽濡苍黔。", "将消祲沴频深砭，感召冲气安危阽。", "嗟嗟直口不可钳，谁当一探龙颔髯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"淮阴寄门人赖韦兼酬诸生","p":"","d":"清代","a":"魏禧","c":["闻说淮东形势地，三城万瓦夹江滨。小山赋后谁招隐，漂母祠前早闭门。", "日月苦消行路客，篮舆长忆执经人。深秋木叶知多少，扫径相迟薜荔村。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"柳条","p":"","d":"明代","a":"屈大均","c":["柳条长不已，总是欲牵肠。历乱还飞絮，氤氲更作香。", "无情化萍藻，有意拂鸳鸯。攀折那能去，依依此夕汤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和虞沧江赋梅 其五","p":"","d":"宋代","a":"吴泳","c":["吟成亟取夜钟敲，淡月笼窗昏晓交。真态莫将形色看，当如相马得蒲梢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"田家岁晚","p":"","d":"宋代","a":"张侃","c":["田家舂米盛土仓，祠灶新鲙鲤与鲂。粥分口数顾长健，不卖痴呆侬自当。", "爇火照天田蚕好，打灰如愿从所祷。一声竹爆阳春回，城里看灯归已晓。", "我生把笔作耕锄，年馀三十腹空虚。不如尔农随分足，只怕门前人催租。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和薛仲止渔村杂诗十首 其四","p":"","d":"宋代","a":"刘黻","c":["非远城中欲避尘，渔村邻里笑言真。自从范子扁舟后，肯著蓑衣有几人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山家","p":"","d":"清代","a":"陈毓秀","c":["陡绝忽夷旷，山农占几家。远峰青露髻，晚稻白开花。", "沙软牛羊卧，溪深鹅鸭哗。亭能宽著我，坐此揽烟霞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"疟起舍弟尚未已示道原","p":"","d":"宋代","a":"王安石","c":["侧足呻吟地，连甍瘴疟秋。", "穷乡医自绌，小市药难求。", "肝胆疑俱破，筋骸漫独瘳。", "惭君远从我，契阔每同忧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂诗 其三","p":"","d":"明代","a":"李时勉","c":["麋鹿食田谷，自向田中聚。饱来山上眠，岂念耕者苦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游龙子祠","p":"","d":"清代","a":"董文涣","c":["清溪路尽只桃花，茅舍无多逐岸斜。偶趁樵风忘路远，眼随飞絮过邻家。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偶吟","p":"","d":"唐代","a":"白居易","c":["好官病免曾三度，散地归休已七年。老自退闲非世弃，", "贫蒙强健是天怜。韦荆南去留春服，王侍中来乞酒钱。", "便得一年生计足，与君美食复甘眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"金缕曲","p":"","d":"清代","a":"金兆蕃","c":["谁谓无神助。谢封姨、回帆送到，行舟留住。纵目南楼年最少，便已头颅如许。", "又何况、当时琳瑀。屈指晨星犹有几，只尊前、磊落人三五。", "今昔恨，那堪诉。", "征袍今昔殊缁素。定难分、江头涕泪，洛中尘土。茗盏诗囊相料理，怕道须溪春去。", "更青兕、几番风雨。莫话年来经历事，枉茹冰、饮雪论辛苦。", "将进酒，为君舞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄题宇文之邵公南止亭","p":"","d":"宋代","a":"冯山","c":["公南九亭名止止，亭不妄作名何为。群公赋咏得深趣，清绝正与斯人宜。", "铺张止义到无说，使我下笔先迟疑。圣贤出处无定辙，俯仰轻重争毫釐。", "云行非行止非止，由赐狂病渊骞痴。公南少年负才术，试仕吐出胸中奇。", "一言龃龉便投袂，自道岂欲求人知。公卿文章强且起，举手谢绝无还期。", "传家万卷书史乐，负郭五里松楸悲。岷峨嘉景照研席，事搅辄醉醒仍诗。", "有时日晏卧不动，郁郁经济埋如脾。", "太师竹洞枕温落，龙图药圃临清伊。二公止迹不止道，力与名教相扶持。", "今君所处近伊洛，道在不必分高卑。文章自可敌行事，荀孟皆我知为谁。", "亭非俗亭止非止，人物不到西南欺。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"园景十二咏 其八 牡丹台","p":"","d":"清代","a":"胤禛","c":["叠云层石秀，曲水绕台斜。天下无双品，人间第一花。", "艳宜金谷赏，名重洛阳夸。国色谁堪并，仙裳锦作霞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山馆","p":"","d":"宋代","a":"潘玙","c":["山馆坐秋雨，风吹霁景开。", "夕阳明远水，落叶走空阶。", "白发人谁健，黄花节又催。", "看云动孤酌，聊以尉吟怀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"刊名","p":"","d":"明代","a":"卢若腾","c":["我生大乱际，不幸兼两累；人识我姓名，我复识文字。", "虽无金石词，亦或动痂嗜；而皮裹阳秋，未免触猜忌。", "耿耿王烈妇，从容死就义；立碑表贞姱，叙述颇详备。", "巍巍太武山，孕毓多瑰异；警句颂山灵，标之山头寺。", "我名署其后，今皆遭劓刖。若笑文字劣，何不以名示？", "姓名果不祥，何不并人弃？阴阳避就间，毕竟同儿戏。", "木伐迹且削，大圣有斯事；似我今所遭，未须生忿恚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送王嘉叟编修出佐南昌","p":"","d":"宋代","a":"陆游","c":["玉殿求衣早，鸾台退食迟。", "君看多故日，宁是弃言时。", "小作南州计，方观急诏追。", "归来上霄汉，莫遣此心移。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠汕头工艺美术陈列馆","p":"","d":"现代","a":"老舍","c":["潮汕文化最风流，", "虹彩霞光映碧秋。", "品罢功夫茶几盏，", "欣看珠玉满琼楼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过洞庭","p":"","d":"清代","a":"张镛","c":["楚望无崖说洞庭，桃花春涨杳冥冥。巴陵地失波中白，彭蠡湖边天上青。", "不见帆樯惟北斗，即无风雨亦南溟。此身恍惚如春梦，愁绝君山渺一星。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"月中柳　湖上春行，同毛稚黄作","p":"","d":"明代","a":"沈谦","c":["少年曾共踏青游。酒满十三楼。香尘不断吼骅骝。", "芳草蓝深，夭桃红浅，白了人头。", "山如屏障周遭在，难抵住、一段闲愁。停杯无语思悠悠。", "飞絮蒙天，游丝著地，不要遮留。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过长安车中口占","p":"","d":"当代","a":"秦鸿","c":["太华依稀迟曙色，长安仿佛负唐暄。班扬李杜千秋下，遥望车流尚武门。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其六","p":"","d":"宋代","a":"释延寿","c":["绕绣屏飞花外蝶，隔金笼语柳中莺。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送人","p":"","d":"宋代","a":"释德洪","c":["相送复相别，不异云间月。无心去复来，有魄圆还缺。", "此别兴何如，西风秋月初。暮鸿千里至，能寄八行书。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"己未九月予赴鞫御史闻","p":"元丰己未三院东阁作","d":"宋代","a":"苏颂","c":["早年相值浙江边，多见新诗到处传。", "楼上金蛇惊妙句，卷中腰鼓伏长篇。", "仳离岁月流如水，抑郁情怀积似烟。", "今日柏台相望处，隔垣音响莫由宣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"留别安庆李太守","p":"","d":"唐代","a":"储光羲","c":["明牧念行子，又言悲解携。初筵方落日，醉止到鸣鸡。", "过客来自北，大军居在西。丘家如讨逆，敢以庶盘溪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游麻姑山","p":"","d":"宋代","a":"李潜真","c":["凌晨特跨赤龙车，御气乘风下九衢。", "金阙殿前朝玉帝，丹霞洞口谒麻姑。", "朱弦未达钟期耳，青鸟空传汉殿书。", "铁笛一声谁会得，独飞踪迹到仙都。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郭山人游囊杂咏六首 其六 觚","p":"","d":"明代","a":"欧大任","c":["山都洗我觚，贮月饮涧下。风来吹有声，笑学昔人挂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上方峰","p":"","d":"明代","a":"王履","c":["金仙不可觅，徙倚娑罗阴。", "壁底野情重，峰端烟树深。", "暗凭悬锁处，遥寄上云心。", "待念飞黄子，忘形却试寻。", "铁锁高悬直壁青，上方形胜杳冥冥。", "西玄空通隔世路，金仙已跨摩云翎。", "觱沸音中怅年晚，娑罗影里问谁经。", "爱河未上超然岸，只到峰根看画屏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"绝句","p":"","d":"近代","a":"罗元贞","c":["风狂雨暴肆摧残，百孔千疮共黯然！一举十年成浩劫，盖棺功罪果空前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寓意","p":"","d":"明代","a":"郑崐","c":["锦衣公子意翩翩，下马人争接玉鞭。", "昔日青娥今白发，强操檀板向歌筵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"食笋时方正月 其二","p":"","d":"明代","a":"袁宏道","c":["縠水温风解冻时，家家馔得雪玻璃。凭将野意酬君子，饱食西窗读楚辞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"复斋奚左藏挂冠 其二","p":"","d":"宋代","a":"释居简","c":["特操刚明与俗乖，溪山亦复外形骸。子狂正作岂矫世，我醉欲眠聊纵怀。", "勇赋一归尤果决，光寒千丈不沉埋。从来林下何曾见，仅有先生闼可排。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游峨岭遂至赵秋谷饴山旧园","p":"","d":"清代","a":"赵国华","c":["四山松影罨城庐，一路泉声曳笋舆。南郭堞横青黛里，北亭觞尽白头余。", "几人下马寻秋草，当日谭龙已索居。太息荆坡无恙在，未应竟自付樵渔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"除夕","p":"","d":"宋代","a":"王铚","c":["一岁尽今夕，既往那可追。", "疏梅吐幽艳，轻冰释寒澌。", "新陈自相代，长年万古悲。", "亦复强取醉，椒盘杂儿嬉。", "天回万象春，除尽群阴卑。", "地除众枯槁，从今作华滋。", "一除不可复，绿发成鬓丝。", "此是有尽处，那知无尽时。", "凡所未除者，所愿皆除之。", "晚景安分守，幻身绝思维。", "生死我所明，圣贤吾所师。", "优游观物变，翼戢仍鲜差。", "山岳惟尘尔，寸心不可移。", "浩歌自达晓，自信何用疑。", "楼头画角声，已逐东风吹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和子瞻沿牒京口忆西湖寒食出游见寄二首","p":"","d":"宋代","a":"陈襄","c":["春阴漠漠燕飞飞，可惜春光与子违。", "半岭烟霞红旆入，满湖风月画船归。", "缑笙一阕人何在，辽鹤重来事已非。", "犹忆去年题别处，鸟啼花落客沾衣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"归途次韵","p":"","d":"宋代","a":"黄彦平","c":["寒食犹须数日间，楚亭才隔几重山。", "归时合有桃花否，试擘华笺问曲栏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"子夜歌十二首 其八","p":"","d":"明代","a":"于慎行","c":["谁令冰不寒，谁令火不热。雨霜涂前除，侬思底得绝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望祀蓬莱","p":"","d":"宋代","a":"林希逸","c":["祀事非常典，君王望紫蓬。仗从天阙下，山在水云中。", "采药何时返，鸣鞘秩礼隆。灵无先沛雨，船有引回风。", "夷见燔柴去，仙难架海通。札书终不验，空翠锁祠宫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"元宵中都太守放灯作律诗五首 其五","p":"","d":"明代","a":"郑真","c":["烛花暗结竹窗低，星月光寒思欲迷。深念老兄居海峤，更怜舍弟客青齐。", "云天杳杳王乔鹤，草屋栖栖祖逖鸡。想见孱然小儿女，凄凉慈母共中闺。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂十七首","p":"","d":"宋代","a":"释师范","c":["诸佛不出世，祖师不西来。", "颟顸一句子，南岳对天台。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"岁暮绝句四首","p":"","d":"宋代","a":"晁说之","c":["迟迟来日去何疾，六十五见此日除。", "明发束修能有几，太平田舍读残书。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽河东夫人","p":"","d":"明代","a":"龚鼎孳","c":["岂少完人传，如君论定稀。朱颜原独立，白首果同归。", "绝脰心方见，齐牢宠不非。可怜共命鸟，犹逐绛云飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谩成三首 其三","p":"","d":"宋代","a":"阮阅","c":["太白仙人白玉篇，逸才清思两难全。如今貂尾容相续，只恐巴吟不足传。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清平乐 当湖秋泛","p":"","d":"清代","a":"黄燮清","c":["旧游在否。零落双红袖。水阁疏廊仍种柳。柳是十年前有。", "一枝枝舻横塘。一声声笛邻墙。一点点蘋秋意，一丝丝蓼斜阳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丑奴儿慢二首 其一 见榴花作","p":"","d":"清代","a":"张惠言","c":["柳绵吹尽，楼外旧愁如梦。又镇日门随雨闭，帘借烟笼、却怕凭阑，相思无字问残红。", "新阴绿处，几时轻逗，芳意千重。玉勒俊游，从他幽独，不到山中。", "况满地、浮英浪药，还做春容。只有斜阳，年年识得换熏风。", "春余心事，凭将杜宇，深诉花工。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自安仁至豫章途中杂兴十九首 其二","p":"","d":"宋代","a":"赵蕃","c":["漠漠平芜远际天，青山若个暗霾烟。行人更说桥新断，试遣招呼与借船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谢朱推梅栽","p":"","d":"宋代","a":"胡寅","c":["南国虽云有学堂，了无松菊径徒荒。", "瘴痕元爱冰花洗，衰鬓聊依玉树芳。", "便觉小池招秀影，更令寒月映新妆。", "从今剩醖萸香酒，指拟春风摘子尝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"北游诗二十一首 其三 立秋","p":"","d":"明代","a":"张元凯","c":["蝉声呜咽柳阴残，节序惊心强自宽。把盏沧江忘日暮，湿衣清露动宵寒。", "凉风汉苑悲团扇，明月湘皋泣紫兰。最是关河摇落易，天涯无奈欲归难。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"刘明远会宿翁灵舒西斋","p":"","d":"宋代","a":"徐照","c":["秋色侵肌骨，还将鬓色侵。", "自来难会宿，安得废清吟。", "竹露滋丛菊，邻钟觉曙禽。", "城中同此月，不起故山心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"为《白鹤滩日记》杀青 其二","p":"","d":"当代","a":"张伯元","c":["我有一张琴，寻常不发音。每当秋水静，来印碧潭心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"彭蠡湖乡思","p":"","d":"明代","a":"谭以良","c":["肠断南天欲尽头，紫荆无语对高楼。还将病眼三更泪，滴破沧浪万里流。", "湖雁一声彭蠡月，梅花三度象城秋。倚门定有慈颜望，曾着斑衣此日否。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"严滩过子陵钓台","p":"","d":"清代","a":"慧霖","c":["自著羊裘老富春，画工辛苦绘功臣。先生到处堪高隐，天上宵来卧故人。", "七里江声终不断，四围水鸟亦相亲。利名淘尽尘中事，留得乾坤一钓纶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆梅和韵","p":"","d":"清代","a":"毕慧","c":["记得孤山竹外阴，横斜水畔径深深。南枝梦断空明月，东阁诗成见素心。", "腊雪乍添新艳采，春风仍到故园林。冷香得句愁难和，合付金徽托远音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"叹仰流通","p":"金刚随机无尽颂","d":"宋代","a":"释印肃","c":["江上数峰青，露出卷心经。", "明明没个字，向道祗如今。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过武山览余襄公候潮处","p":"","d":"明代","a":"苏亦堪","c":["万派朝宗水直催，襄公曾此候潮来。乘风势涌翻鳌呿，映日光涵漾蚌胎。", "二气吹嘘穷睇眄，四贤勋业极崔嵬。临流慨想遗徽在，龙穴风生雪浪开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清平乐","p":"","d":"宋代","a":"朱雍","c":["雪开瑶径。素蕊迎春影。楼上玉声三弄定。无奈幽香翻阵。", "凌晨不事铅华。化工却付春花。流水残阳江上，清随月色低斜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"六十初度自寿四首 其二 阮郎归","p":"","d":"明代","a":"王鏊","c":["行年六十鬓斓斑。皇恩特放还。高堂设席对青山。", "秋来正未閒。", "阴忽霁，暑新寒。笙歌夜未阑。傍人莫笑老嗤顽。人生到此难。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋怀","p":"","d":"宋代","a":"欧阳修","c":["节物岂不好，秋怀何黯然！", "西风酒旗市，细雨菊花天。", "感事悲双鬓，包羞食万钱。", "鹿车何日驾，归去颍东田。"],"tags":["秋天", "写景", "抒怀", "思归"],"z":"秋怀：秋日的思绪情怀。\n节物：节令风物。\n酒旗：酒店悬挂于路边用与招揽生意的锦旗。\n包羞：对所做事感到耻辱不安。\n鹿车：用人力推挽的小车。《风俗通义》说因其窄小，仅载得下一鹿，故名。\n颍东：指颍州（今安徽阜阳）。欧阳修在皇祐元年（1049）知颍州，乐西湖之胜，将卜居，不久内迁。翌年，约梅圣俞买田于颍。","y":"这节令风物有哪一点使人不称心？可不知怎的，我面对这满眼秋色，却禁不住黯然神伤。\n西风猎猎，市上的酒旗迎风招展；细雨濛濛，到处有金色的菊花怒放。\n想到国事家事，愁得我双鬓灰白；白白地耗费朝廷俸禄，我心中感到羞耻难当。\n什么时候能满足我的愿望——挽着鹿车，回到颍东，耕田植桑。","s":"","k":"诗"},
  {"t":"墨池","p":"","d":"宋代","a":"宋京","c":["君不见子云草玄西郭门，一径秋草间朝昏。何须笔冢高百尺，池墨黯黯今犹存。", "童乌侯巴竟零落，玄学无人终寂寞。汉家执戟知几年，垂老身没天禄阁。", "俗儿纷纷重刘向，思苦言艰动嘲谤。汉已中天雄亦亡，不较空文从覆酱。", "如今却作给孤园，吐凤亭前池水寒。安得斯人尚可作，会有奇字令君看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"马逸","p":"","d":"现代","a":"聂绀弩","c":["脱缰羸马也难追，赛跑浑如兔与龟。", "无噩无嘉无话喊，越追越远越心灰。", "苍茫暮色迷奔影，斑白老军叹逝骓。", "今夕塞翁真失马，倘非马会自行归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题何德儒所藏顾周道水石图","p":"","d":"明代","a":"谢肃","c":["沄沄石下波，郁郁波上林。过桥仙客忽长啸，一鹤来自蓬山岑。", "蓬山岑，不难至。聊栖瀛海内，自适沧洲意。恍如出硖石，群枫落影洪流碧。", "又似泊金山，回潮激树崩厓间。江淮风景真绝奇，来往扁舟荫清樾。", "鸟飞鱼泳醉吟中，回首兹游几秋月。虎头子，天机精，剪彼水石来轩楹。", "使我一见气峥嵘，龙蛇起陆雷霆惊。尔宜藏此画，慎莫时时挂。", "光气一冲天，超然便神化。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"飞来寺 其一","p":"","d":"明代","a":"郭棐","c":["扁舟又度飞来寺，惭见江鸥数往回。览胜沈卿原有赋，留题罗隐是仙才。", "层崖古树云同绽，绝壁悬流雪作堆。如此山川足行乐，几时高步钓鱼台。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送李经","p":"","d":"金朝","a":"李纯甫","c":["髯张元是人中雄，喜如俊鹘盘秋空。怒如怪兽拔古松，老我不敢婴其锋。", "更著短周时缓颊，智囊无底眼如月。斫头不屈面如铁，一说未穷复一说。", "勍敌相扼已铮铮，二豪同军又连衡。屏山直欲把降旌，不意人间有阿经。", "阿经瑰奇天下士，笔头风雨三千字。醉倒谪仙元不死，时借奇兵攻二子。", "纵饮高歌燕市中，相视一笑生春风。人憎鬼妒愁天公，径夺吾弟还辽东。", "短周醉别默无语，髯张亦作冲冠怒。阿经老泪如秋雨，只有屏山拔剑舞。", "拔剑舞，击剑歌，人非麋鹿将如何。秋天万里一明月，西风吹梦飞关河。", "此心耿耿轩辕镜，底用儿女肩相摩。有智无智三十里，眉睫之间见吾弟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"谌祜","c":["隔云烽火山河旧，列土旌旗雨露深。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南朝","p":"","d":"宋代","a":"石延年","c":["南朝人物尽清贤，不是风流即放言。三百年间却堪笑，绝无人可定中原。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"立春日胥江驿东方舟友人时丁未冬十二月二十一日也 其一","p":"","d":"明代","a":"张萱","c":["阔岸移青翰，荒邮滞碧幢。已知春信好，渐觉病魔降。", "土脉占微动，鸥群泛自双。一尊聊共适，落日尚牵江。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"碧云即事","p":"","d":"宋代","a":"刘宰","c":["块坐经年不入山，山僮拍手笑衰颜。", "登高犹喜心期在，望远还惊目力悭。", "云气苍茫自羁旅，烟波飘荡几惸鳏。", "朝来旧雨添新雨，谁识安危指顾间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怀翁宏","p":"","d":"唐代","a":"王元","c":["独夜思君切，无人知此情。沧州归未得，华发别来生。", "孤馆木初落，高空月正明。远书多隔岁，独念没前程。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其二","p":"","d":"宋代","a":"张致远","c":["三寺楼台烟雾里，一川芦苇画图中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜半闻雨声清甚","p":"","d":"宋代","a":"韩淲","c":["雨声催我梦华胥，清气于人便有馀。惟适之安非素隐，不容何病是閒居。", "茶烟未了归真觉，香雾初横切太虚。却忆华山陈处士，惘然推枕听阶除。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"村居杂兴六首 其六","p":"","d":"明代","a":"顾清","c":["灵均沈湘陶令死，篱下寒香久无主。江边一笑倚清秋，烂漫西风几今古。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题高君宝绀泉","p":"","d":"宋代","a":"文天祥","c":["渟渟岩下泓，澄碧落梧影。", "寒瑶披清飙，残月照濎濙。", "俯渊测浮云，流日荡苕颖。", "向来沧浪歌，孺子不可诇。", "载沾衣上尘，怀古意深永。", "招招素心人，相期发深省。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈四首 其三","p":"","d":"宋代","a":"释思慧","c":["一切法无差，云门胡饼赵州茶。黄鹤楼中吹玉笛，江城五月落梅花。", "惭愧太原孚上座，五更闻鼓角，天晓弄琵琶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送李运使学士赴阙十咏 其四","p":"","d":"宋代","a":"赵抃","c":["压境号民苏，连甍竞乐输。万桑丰岁计，一节赴朝趋。", "安稳舟无恙，雍容骑甚都。赠言聊纪盛，为颂愧非夫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"马上见卖白莲者三首 其一","p":"","d":"宋代","a":"陈造","c":["引息度奇暑，风日正交战。淮乡六月春，嫣然担头见。", "香凝素囊拆，湿馀清露泫。丰肤专正色，一忠百佞贱。", "祝融乃司花，慰我红尘面。买归一杯适，得共黄葵荐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和张仁溥赋雪","p":"","d":"宋代","a":"吴泳","c":["北风声熄南山微，谁息风雅呼於时。", "歌黄三章未纯古，叙白一段空爱奇。", "台高皆羡雨花落，檐短独愁冰柱垂。", "墨客如林笔如冢，莫於诗上更题诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过未央宫遗址","p":"","d":"明代","a":"程诰","c":["木落汉宫秋，寒虫苦悲咽。", "君看草色丹，犹染淮阴血。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"庐山瑶草四时春","p":"少年游","d":"宋代","a":"晁补之","c":["庐山瑶草四时春。烟锁上宫门。记得南游，偶寻飞涧，一洗庾公尘。", "香炉高咏君家事，文彩近前人。它日骑鲸，尚怜迷路，与问众仙真。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"丙申江右上巳年会适十周年雅集奉和熊社","p":"","d":"当代","a":"李映斌","c":["独抱骚心不可降，十年鸥影掠沧江。幽兰翠渚鱼吹浪，高阁朱华气溢窗。", "尚古歌吟遗劫烬，隔尘山水驻仙邦。弟兄远志酬何易，但有良宵潋滟缸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉和袭美太湖诗二十首。孤园寺","p":"","d":"唐代","a":"陆龟蒙","c":["浮屠从西来，事者极梁武。岩幽与水曲，结构无遗土。", "穷山林干尽，竭海珠玑聚。况即侍从臣，敢爱烟波坞。", "幡条玉龙扣，殿角金虬舞。释子厌楼台，生人露风雨。", "今来四百载，像设藏云浦。轻鸽乱驯鸥，鸣钟和朝橹。", "庭蕉裂旗旆，野蔓差缨组。石上解空人，窗前听经虎。", "林虚叶如织，水净沙堪数。遍问得中天，归修释迦谱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"正月十八日甘棠院 其一","p":"","d":"宋代","a":"蔡襄","c":["上元才过去寻春，红白山花粲粲新。似喜使君初病起，隔栏相向笑迎人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"京邸忆卿云洞作","p":"","d":"清代","a":"齐彦槐","c":["大道径其上，大川贯其中。洞门高十丈，跨水如长虹。", "绝壁柏倒垂，托根自鸿濛。岂有雨露到，万古常青葱。", "人经乱流间，小语铿洪钟。似掌一片石，宽可百余弓。", "名曰仙人田，阡陌横且纵。仙人犹力耕，我辈胡独慵。", "田尽得井穴，烛之光熊熊。深窈不可测，或是蛟龙宫。", "涉险生归心，西入出从东。夕阳照湍濑，炯若金在镕。", "钟乳类飞禽，影动群翻风。此景别来久，追写不能工。", "何当饮云光，一洗尘埃胸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"新除广东常平之节感恩书怀","p":"","d":"宋代","a":"杨万里","c":["巳愧双旌古晋陵，更堪一节古羊城。", "偶逢旧治年频熟，忽署新衔手尚生。", "山与君恩谁是重？身如秋叶不胜轻。", "向来百链今绕指，一寸丹心白日明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"凤凰台上忆吹箫 感怀","p":"","d":"当代","a":"袁思古","c":["怨蕴离骚，人怀楚泽，先朝事误纵横。对新亭挥泪，消息堪惊。", "依旧天涯烽火，疆场未肯早休兵。江山肚、古今一辙，供给纷争。", "苍生。频年憔悴，到处是哀鸿，一片商声。叹渔樵歌断，怅望升平。", "人世红尘如梦，所争者、半是虚名。试问英雄多少，千古谁荣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏史二十七首 其十四","p":"","d":"明代","a":"王夫之","c":["代契丹憎延广，为司马爱谯周。一线容头活计，二毛肉袒风流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"中夜","p":"","d":"清代","a":"纪炅","c":["老话侵中夜，微霜落半秋。黄花知月令，白发恋人头。", "丹粒应难熟，笙歌最易休。弦光浑未湿，桂影叠山楼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宪圣慈烈皇后挽诗二首","p":"","d":"宋代","a":"程珌","c":["西浒俱来日，乐朝极盛时。", "彫弓平黑海，彩笔照丹墀。", "垄起先裁费，丹成不用医。", "人间空怅望，风月宴瑶池。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题无学卷兼柬三怀上人时同寓匡庐 其二","p":"","d":"明代","a":"邹元标","c":["持经为母到西台，五两风轻一苇开。月照蒲团猿鹤静，好骑白鹿再归来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂诗","p":"","d":"宋代","a":"陈瓘","c":["床头史记千番纸，世上兴亡一窖尘。", "惟有炳然周孔道，至今余泽浸生民。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天","p":"","d":"元代","a":"姬翼","c":["贩骨来来几万生。煎熬窟里谩峥嵘。百年不觉消疣赘，千载无能息劓黥。", "翻欲浪，起心兵。迷绳自缚聚愁城。几将浊水浇胸臆，倒语颠言贺太平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游春","p":"","d":"元代","a":"张玉娘","c":["护槛花浓梦欲攲，五更清露锁寒扉。明朝恐负寻芳约，拂晓平瞻霁影依。", "贴翠自怜羞舞镜，送春无奈听啼规。金莲破藓留芳迹，梨萼翻风作雪飞。", "沙上晴凫窥浅渚，松边黄蝶绕疏篱。催吟片雨云俱黑，狂絮欺人故点衣。", "心事肯随流水尽，新愁不与酒尊宜。青梅已结梢头实，驿使难传陇外枝。", "笑折野花轻插鬓，却嫌溪柳妒修眉。因过竹院参禅意，觅得云林旧日诗。", "听彻游郎歌古调，停看渔父下苔矶。紫山迢递行应好，苍磴萦回出每迟。", "罗袖翩翩香气满，绿阴冉冉鸟声微。等閒无限伤春思，芳草天涯肠断时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"紫薇花","p":"","d":"清代","a":"张鹏翮","c":["绿阴深处夕阳斜，烂漫还开两树花。晴日午风偏觉媚，红霞一片落谁家？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"黄德让病后苦吟因赋诗以释之","p":"","d":"元代","a":"徐贲","c":["不废诗篇病后身，思花怀月亦劳神。凭君暂歇行吟兴，药具方书正可亲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题宾虹山水障","p":"","d":"清代","a":"黄节","c":["旧忆淞江经岁别，春阴无俚叹宾虹。生平能事都如此，浦溆渔舟着意工。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"顺风过湖二首","p":"","d":"宋代","a":"项安世","c":["维舟六日傍明山，待得风来始破颜。", "一抹平湖三十里，听渠微横未须关。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"逍遥咏 其十四","p":"","d":"宋代","a":"赵炅","c":["燕雀不生凤，阴阳一气全。无穷深可及，境象理推迁。", "奚益其形化，平章语默玄。终身何所役，道本岂私焉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送司训王恭之任闽清","p":"","d":"明代","a":"陈琏","c":["新拜儒官出帝京，过家奉檄为亲荣。方辞北阙三千里，此去南闽几月程。", "菡菼滩声和雨响，武夷山色与云平。闽清学者从来盛，坐拥皋比称宦情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次徐漕韵贺留守刘观文祷雪感应","p":"","d":"宋代","a":"许及之","c":["雪霜之忍有至慈，一片到地五谷滋。所以腊中重三白，史讥失时书直辞。", "我公卧护北门北，百姓爱公如爱日。及冬祷雪乃爱民，若有鬼神宜率职。", "要晴要雨天必从，玉山何独閟烛龙。一夜风师擘冰絮，坐使东国成雪宫。", "晓起清愁无复有，如在春风饮醇酒。欲歌零雨劳公归，正尔补天须妙手。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戏题重台梅","p":"","d":"宋代","a":"张镃","c":["只将单萼缀层花，弱骨丰肌自一家。", "载朵折来谁可称，宝钗双燕绿云斜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠皖山道士","p":"","d":"宋代","a":"宋无","c":["世人曾不识，头带树皮冠。", "间种药来卖，醉将琴去弹。", "鹤术仙果下，猿穷玉书看。", "莫服丹砂好，恐师生羽翰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"路入剡中作","p":"","d":"唐代","a":"方干","c":["截湾冲濑片帆通，高枕微吟到剡中。掠草并飞怜燕子，", "停桡独饮学渔翁。波涛漫撼长潭月，杨柳斜牵一岸风。", "便拟乘槎应去得，仙源直恐接星东。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"遣怀兼怀姜凤阿内翰二首 其一","p":"","d":"明代","a":"王樵","c":["浅疏难应俗，忧喜只随人。到处身如寄，何时我是真。", "兴来还自败，老去欲谁亲。回首高阳里，荀家有二仁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闻里中有买得扶桑花者 其四","p":"","d":"明代","a":"徐渭","c":["鹤林寺里别袈裟，又幻扶桑到若耶。溪女惜香还菡萏，海人浇醉歇枇杷。", "似闻此地春犹雪，悔上孤帆晓载霞。腊社少年貂帽上，簪红莫忘遍茶花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题兴宁县东文岭瀑泉，在夜明场驿之东","p":"","d":"宋代","a":"杨万里","c":["笋舆路转崖欹倾，只闻满山泉水鸣。", "卷书急看已半失，眼不停注耳细听。", "石如铁色黑，壁立镜面平。", "水从镜面一飞下，蕲笛织簟风漪生。", "石知水力倦半壁，锺作天一泓水行。", "到此欲小憩，後水忽至前水惊。", "分清裂白两泒出，跳珠跃雪双龙争。", "不知落处深几许，千丈井底碎玉声。", "安得好事者，泉上作小亭。", "酿泉为酒不用麴，春风吹作蒲萄绿。", "醉写泉声入枯木，何处更寻响泉曲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"封太常博士丁公挽诗","p":"","d":"明代","a":"陈琏","c":["一自声名达九重，祇承敕命见褒崇。冰衔方睹容台秩，墓域俄成马鬣封。", "宿草萧萧经暮雨，白杨飒飒动悲风。无由远致生刍奠，引睇天南意不穷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题元人名绘集锦卷 其六 赵丹林陆羽烹茶图","p":"","d":"清代","a":"弘历","c":["古弁先生茅屋间，课僮煮茗霅云閒。前溪不教浮烟艇，衡泌栖迟绝往还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题三沙","p":"","d":"元代","a":"郯韶","c":["三洲宛在碧波中，海色晴霞绚烂红。夜半鸡鸣先见日，天边月晕又生风。", "鲛女机丝花隔雾，龙君城阙水为宫。谁持玉节寻真去，直过扶桑弱水东。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"漫兴","p":"","d":"近代","a":"惺伯民","c":["鼙鼓中原震不宁，杜鹃啼血晚风腥。老天欲丧斯文未，劫运翻从改步丁。", "榴火薰人头转白，柳丝系我眼谁青。黄钟毁弃寻常事，闭户陶然醉六经。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和文与可洋川园池三十首 其十一 二乐榭","p":"","d":"宋代","a":"苏轼","c":["此间真趣岂容谈，二乐并君已是三。仁智更烦诃妄见，坐令鲁叟作瞿昙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"萧宅二三子赠答诗二十首。井请客","p":"","d":"唐代","a":"卢仝","c":["我生天地间，颇是往还数。已效炊爨劳，我亦不愿住。", "君有造化力，在君一降顾。我愿拔黄泉，轻举随君去。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"相思歌","p":"","d":"明代","a":"霍与瑕","c":["楫舟下香山，行行翠微里。春尽夏方初，万绿檠新洗。", "点点绿中红，如珠缀云绮。借问道傍翁，云是相思子。", "昔有一佳人，望夫大江沚。相思复相思，相思无时已。", "閒倚相思根，泪滴相思底。东风送郁陶，挂作相思蕊。", "散作相思花，结作相思子。莹润比珊瑚，红琛斗洵美。", "从此落人间，缘鬟仍充耳。化石亦成台，古来诚有此。", "茉莉与素馨，馨香何足恃。嗟嗟此相思，千年心不死。", "我亦相思人，昔涉相思涘。曾唱相思歌，细写相思指。", "无路寄相思，空结相思痞。徘徊相思下，相思聊复尔。", "岁岁更年年，丹心照流水。湘竹已全斑，重华何日起。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆秦娥 其二","p":"","d":"清代","a":"郑元昭","c":["雨潇潇。琐窗默坐愁春宵。愁春宵。离人情绪，红杏花梢。", "鱼书烟水愁迢迢。黛眉深浅无心描。无心描。容光易减，镜里昏朝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"仲春","p":"","d":"宋代","a":"吴涛","c":["雨馀寒气浅，园林作春媚。不知海棠花，新来著花未。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"又次韵","p":"","d":"元代","a":"张雨","c":["别后惊心岁已驰，几回草梦绕春池。新诗远寄迢遥驿，旧约重看绝妙碑。", "鳌禁风清班缀玉，龟溪雪冷鬓垂丝。何时共执论文酒，坐对西窗待月迟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"廓然得石门信叹其踵席非其人用韵酬之二首 其一","p":"","d":"宋代","a":"释德洪","c":["相对天涯岁月新，石门消息远难真。乘闲且觅几场笑，疾恶休生一念瞋。", "衬鹭芙蕖方破暖，藏鸦柳色又残春。光阴如此空搔首，行诵知归倦鸟频。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"相如二首 其二","p":"","d":"宋代","a":"陈造","c":["逸德狂情赖补苴，文君端合婿相如。白头曲里殷勤意，不愧先生谏猎书。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"回首","p":"","d":"近代","a":"洪存恕","c":["回首此神州，纷争岁月稠。绾符雄割据，秉秫困诛求。", "鸟死功成羿，龙兴德迈周。野人何企羡，一饱抵封侯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杨员外","p":"","d":"明代","a":"时太初","c":["群盗南奔日月昏，诸公臣节不须论。白头惟有杨员外，不负从来天子恩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和永叔春雪","p":"","d":"宋代","a":"刘攽","c":["陬筒吹灰变冥朔，生气萌泉天不觉。凝阴忽升气横厉，重云大同势绵邈。", "通衢漫漫走流沙，近甸稍稍堆乔岳。焚炉姹女姿飞扬，匝野神奸谁彫琢。", "刀圭不惜透墙隙，捷业俄然垂屋角。户斜尺剑未及收，窗缺连环如可握。", "鲜妆宫女喜深印，红手庠童斗坚搦。暝鸡误晓屡咿咿，饥雀冲人犹啄啄。", "虽怜林篁有摧折，却喜陇苗就优渥。贫庐败褐憎破牖，富屋珍裘转深幄。", "使君高义仍泛爱，颍士多文方力学。猎师得隽鲜弃薧，厨酿荐甘清间浊。", "气随阳春破凝烈，巧夺钧工畏名貌。吾知郢人不复歌，古声比今为拙朴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"罔极篇十四章 其八","p":"","d":"当代","a":"林恭祖","c":["嗟乎予弗子，羁角泣呱呱。壮岁飞流影，乡心绕玉壶。", "未听慈母语，长作浪人徒。回首悲何恃，天涯阮籍途。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨蛮（和令狐公子）","p":"","d":"宋代","a":"王灼","c":["风柔日薄江村路。一鞭又逐春光去。胡蝶作团飞。竹间桃李枝。", "醉魂招不得。一半随春色。桃李□无多。其如风日何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"喜雪","p":"","d":"宋代","a":"范纯仁","c":["久旸逢腊雪，酌酒动欢诚。密势迷城郭，馀霏冒栋楹。", "河光平曳练，岳色远堆琼。已报丰年瑞，三登贺太平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠刀镊王诚三首 其二","p":"","d":"宋代","a":"徐元杰","c":["汝家住近里仁坊，不恋妻儿恋侍旁。父子性天非可夺，亲亲仁也盍揄扬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丹井陈子白母挽词二首 其一","p":"","d":"宋代","a":"林亦之","c":["哀曲梧桐夜，何年苜蓿盘。敬夫前辈重，好客妇人难。", "十月明朝尽，孤坟落日寒。鹿门催作黍，此意竟长叹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"西江月 简于右任","p":"","d":"当代","a":"章士钊","c":["谁把诗余漫要，却惊句子难工。文章底事信天翁。", "天与还须人动。", "活法全凭悟入，骚心疑有神通。自怜头脑太冬烘。", "烘似烟花着梦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秦淮晚眺","p":"","d":"元代","a":"张翥","c":["赤栏桥下暮潮空，远火疏舂晻霭中。新月半天分落照，断云千里附归鸿。", "严城鼓角秋声早，故国山川王气终。莫讶时来一长望，越吟荆赋思无穷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鸡鸣山短歌","p":"","d":"清代","a":"杜堮","c":["饮马下白登，挥辔出开平。每有早行人，至此闻鸡鸣。", "岧岧飞狐岭，黯黯沙城戍。亦有投止客，夜听鸡鸣去。", "鸡鸣星始稀，寒霜拂人衣。关河不可极，游子常怀悲。", "鸡鸣天下晓，西风吹白草。行路古今难，人共沙场老。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"越十日陪使君汪内翰复来","p":"","d":"宋代","a":"黄公度","c":["雅制初仍旧，佳名留至今。", "城依刺桐古，亭入芰荷深。", "尊俎宾僚集，旌麾刺史临。", "自公多暇日，及此豁尘襟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚登净远亭二首","p":"","d":"宋代","a":"杨万里","c":["重阳才过便新寒，去岁如今暑尚残。", "云外鴈来元不觉，一声唤我举头看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"五福降中天 代寿赵次丈八十","p":"","d":"清代","a":"奭良","c":["万家生佛红云矗，赢得家家欢跃。蒱酒刚斟，桂轮犹满，嵩岳乔松蔚茂。", "画堂深静，只鸿案雍和，凤雏娇小。那有宾筵，客履淡淡旧怀抱。", "仿佛托根仙李，百三旬、压倒香山老。潞国精神，汾阳富贵，漫数东都梁灏。", "天锡纯嘏，一片婆心，吉星缭绕。百拜深深，嫛倪常惠保。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"永和宫词廿七首 其九","p":"","d":"明代","a":"吴伟业","c":["奉使龙楼贾佩兰，往还偶失两宫欢。虽云樊昵能辞令，欲得昭仪喜怒难。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感花 其四","p":"","d":"宋代","a":"吴芾","c":["纵令日日醉春风，已恨花无十日红。何事东君长作恶，不容春色丽晴空。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感兴二十七首 其二十五","p":"","d":"宋代","a":"方一夔","c":["雄蜂采花粉，雌蜂衔花汁。粉以作黄蜡，汁以蒸白蜜。", "不辞盗我廪，但规安我室。吾穷还可忍，岁岁看分出。", "不见岐周人，先世但积德。土地付獯狄，自爱豳沮漆。", "儿孙遍天下，鲁卫酆郇毕。勿言天未定，此理终可必。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"释道臻","c":["疑君魂梦在清都。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"曲江见杏花","p":"","d":"明代","a":"朱诚泳","c":["隔岸依稀见早霞，酒帘摇处两三家。马头駊騀行来近，始见前村有杏花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次高左藏使君韵","p":"定风波","d":"宋代","a":"黄庭坚","c":["万里黔中一漏天，屋居终日似乘船。及至重阳天也霁，催醉，鬼门关外蜀江前。", "莫笑老翁犹气岸，君看，几人黄菊上华颠？戏马台南追两谢，驰射，风流犹拍古人肩。"],"tags":["励志"],"z":"","y":"","s":"","k":"词"},
  {"t":"族叔祖示四绝句次韵 其二","p":"","d":"宋代","a":"张守","c":["不乐从军学仲宣，那能辟谷慕飞仙。直缘衰病干明主，乞得南窗一觉眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"庆寿寺","p":"","d":"明代","a":"陈琏","c":["暇日行经凤阁西，喜瞻佛刹与云齐。高僧屡致金襕赐，华扁曾承御墨题。", "烟满禅房香蔼蔼，雨荒鹤径草萋萋。偶来林下寻碑看，祇树阴中听鸟啼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"凭栏人 牧羊人","p":"","d":"当代","a":"黄绮","c":["芳草青青不辨天。云拥山羊白玉团。羊群胜似仙。", "笑回头，遗牧鞭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鼓笛慢/水龙吟","p":"","d":"宋代","a":"佚名","c":["雪霏冰结霜凝，是谁透得春工意。南枝向暖，江边岭上，独先众卉。闲态幽姿，绿窗红蒂，粉英金蕊。念冰肤秀骨，人间要见，除非是、真仙子。羌管且休横吹。待佳人、新妆初试。鸾台晓鉴，人花相对，何须更比。疏影横斜，暗香浮动，月低风细。又岂知，渐结枝头翠玉，有和羹美。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋答尹宪副先生 其一","p":"","d":"明代","a":"罗钦顺","c":["顿收佳什见情亲，一字都来不犯尘。秋院挥毫风正爽，晓窗开卷墨犹新。", "论心每忆同游处，矫首难忘奉别晨。门带清流山附屋，暮年新酒共谁频。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和刘后村梅花百咏 其六十六","p":"","d":"宋代","a":"方蒙仲","c":["生涯冷淡乐者少，声色希夷见若无。洛下只知海棠会，岭南竞作荔枝图。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水龙吟 道运","p":"","d":"元代","a":"丘处机","c":["混元南岳初开，瑞云透出昆仑表。星移电转，阴升阳降，红光缥渺。鹤舞鸾翔，看乌龟共，赤龙蟠绕。尽鸿ㄨ一气，烹成造化，神仙道，片时了。云散十方三岛，洞天深、月明风袅。此时占得，长生门户，遐龄体调。吟咏从佗，海移山变，石枯松老。伴烟霞独向，非非境外，恨知音少。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"止斋曲廊初成","p":"","d":"宋代","a":"陈傅良","c":["但酒胜如水，但花胜如草。", "小廊曲通幽，竹椽亦良好。", "止斋十数间，足以便衰老。", "檐低远风露，地窄易汛扫。", "浅溪浮薄觞，短屏糊旧稿。", "著书仅玄易，过客多韦缟。", "於中榜退思，谁其谅深抱。", "吾思亦已晚，吾退盍更早。", "怀哉彭泽令，仰止商山皓。", "维渊有潜龙，维岳有藏宝。", "煌煌暮春堂，三字落穹昊。", "昭回际南极，镇抚及东岛。", "胡然乃在斯，夙夜惧不保。", "鬼神无世情，呵护必有道。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"辛巳除夕","p":"","d":"当代","a":"钱钟书","c":["不容灯火尽情明，禁绝千家爆竹声。", "几见世能随历换，都来岁尚赚人迎。", "老饥驱去无南北，永夜思存遍死生。", "好办杯盘歌拊缶，更知何日是升平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈一首","p":"","d":"宋代","a":"吴处厚","c":["是身如泡幻，尽非真实相。况兹纸上影，妄外更生妄。", "到岸不须船，无风休起浪。唯当清静观，妙法了无象。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"陇州神泉铺后池","p":"","d":"宋代","a":"李复","c":["山腰绿映女郎祠，祠下泉通竹下池。时有游鯈自来去，祗应曾见理钩丝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题魏少府破屏风","p":"","d":"明代","a":"柳应芳","c":["依倚忘年岁，中伤冀尔容。", "乍通宵案烛，不掩午堂钟。", "射雀犹存影，弹蝇已失踪。", "勿言新可代，官冷若为供。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"法会因由分第一","p":"金刚随机无尽颂","d":"宋代","a":"释印肃","c":["欲穷千里目，野干浑狐族。", "大家归去来，莫道盆光覆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鞦韆","p":"","d":"明代","a":"李待问","c":["画架齐芳树，垂云拂夕阴。长安女儿戏，年少岁时心。", "燕掠风前舞，莺翻垣外音。小楼看不厌，惆怅落花深。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大同路石佛谷过啼哭岭","p":"","d":"元代","a":"蓝仁","c":["云京石寺游，西北上丰州。山险为啼哭，路艰成阻脩。", "闻名心已碎，未见泪先流。万里江南客，那堪过岭头。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"中秋日侍皇太后宴","p":"","d":"清代","a":"弘历","c":["月到今宵满，秋当此日中。佳筵开虎帐，皓魄丽璇空。", "欢赏陪王母，关山入桂宫。舒华泠坂露，弄影荡林风。", "午夜蟾应冷，千年镜早砻。持将对慈寿，辉映一般同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题涉江词寄千帆教授四首 其四","p":"","d":"近代","a":"周采泉","c":["奇光异彩豁吟眸，哀乐中年集百忧。七字便堪千载诵，有斜阳处有春愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"癸未至节以病晚起走笔戏书纪事排闷十首","p":"","d":"宋代","a":"方回","c":["云无事书者，泥屦隔墙声。", "小市扃虚肆，荒庖绝美烹。", "流涎淮蟹紫，入梦海柑頳。", "莫殢闭关卦，兵戈商不行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"李氏孝义","p":"","d":"明代","a":"陶安","c":["鲁之为国多秀民，礼教遗俗醇乎醇。中有孝子全性真，务学唯先厚天伦。", "骨肉之爱始自亲，厚我能施睦宗姻。母氏派出虞公臣，秉节操心异于人。", "夫也竟终阃幕宾，江东客途孤怆神。归家奉舅颜和訚，舅兮不知儿陨身。", "不将脸照桃花春，柏舟为誓甘苦辛。灯窗课读勤绩纫，渐见四子英甡甡。", "重闱鹤发馀九旬，孙枝满眼皆儒珍。盈门弦诵延缙绅，簦笈远至咸循循。", "表厥宅里墨榜新，光映岱岳黄河津。良也孝义盖有因，积善有报祯祥频。", "后贤思齐世蹈仁，河岳久长能与钧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宬皇史","p":"","d":"明代","a":"皇甫汸","c":["宬皇史，函帝籍。金为匮，石为室。签汇绨缃部甲乙。", "迩文华，充武库。简鸿儒，雠豕误。于万斯年守之锢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"塘上杂诗四首 其二","p":"","d":"明代","a":"程汉","c":["少年卖畚事康卑，出入南陵郭外溪。自昔家空渔浦上，于今人老栅塘西。", "浮烟直港乘槎小，斜日疏篱晒网低。向夕烹鱼谁可问，山厨不见旧山妻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古二十四首 其十七","p":"","d":"宋代","a":"释胜","c":["有喝端如探竿草，无师血脉通红线。当阳不识李将军，徒学穿杨一枝箭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送西秦张仲实游大涤洞天","p":"","d":"宋代","a":"林昉","c":["此时仙兴发，九锁访名峰。", "玉洞昼飞鼠，石池春浴龙。", "异人花外见，道士酒边逢。", "余欲采芳茗，白云何所从。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"种花","p":"","d":"明代","a":"苏仲","c":["偷得清閒半日光，薙荒除草接花忙。新怀蒋诩开幽景，老梦林逋逐暗香。", "雨过滑泥牢著屐，月临疏影近移床。东风许弄年光兴，拍掌儿歌可侑觞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"将赴江浙大府校进士试会疾止建安驿上后山东眺郡城作十二韵","p":"","d":"元代","a":"范梈","c":["青云建安郡，人物故钟秀。承旭开芳树，凌虚列遥岫。", "溪声涌夜长，石角吐秋瘦。渔沙府图谶，仙室川浸溜。", "征尘汩炎毒，服事弥奔奏。淡淡鸿鹄举，苍苍鹰隼候。", "山英茗在瀹，馆饭菰登豆。勤渠相国谊，忝窃大夫后。", "顾惟论贤能，奚取推寡陋。吾欲敕五丁，雷电激宇宙。", "疾飞移万壑，及此洗昏疚。起为梅子真，南厓扫丹臼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上谷秋日杂书四首 其一","p":"","d":"明代","a":"程可中","c":["列壁风鸣汉帜摇，居庸天迥锁云标。雨余新爽澄金气，夜半残河插斗杓。", "嘉馔土人烹硕鼠，薄寒胡帽制丰貂。妖姬不解愁砧杵，马上琵琶手自调。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次儿辈戏商卿设醴韵二首","p":"","d":"宋代","a":"陈造","c":["将命长须脚未移，联翩客马已来齐。", "菊花旋采浮云液，罗{贴莫}宽围护麝脐。", "醉里有诗皆虎凤，区中无物不虫鸡。", "主宾等是龙津客，未分金鳞卧瓮虀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"早春即事","p":"","d":"宋代","a":"华岳","c":["杨柳丝丝弄淡黄，怯寒燕子未归梁。", "晓迷芳草骓骏湿，夜宿閒花蝶翅香。", "得句自惭非子美，赏音犹恐误中郎。", "愿言相约花前醉，莫放春容过海棠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次张正卿平江伯见赠","p":"","d":"宋代","a":"龚璛","c":["车马匆匆不我过，诗书亹亹奈君何。邻墙烛影夜未艾，客路梅花春渐和。", "佳士逢时文苑传，小人有分力田科。支颐送远阳湖上，急雪回风生意多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宿魝州次韵石沙侍御","p":"","d":"明代","a":"符锡","c":["一宿渔阳馆，新诗取次留。奚囊应渐满，民瘼荷兼□。", "日晏村烟薄，春深鸟韵柔。若为忧国虑，时共野人筹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"释善昭","c":["三头六臂擎天地，忿怒那吒扑帝钟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"止酒和陶靖节","p":"","d":"明代","a":"邝露","c":["止酒不可止，得酒性乃便。何世非大梦，何夜非长年。", "何天非梦梦，何帝非陶然。大饮盗海岳，醢龙酺麟肩。", "小饮盗沼沚，烹葵醊茎莲。嗒然既丧我，优哉复忘天。", "天岂与我违，太和同周旋。笑彼独清醒，怀沙甘湛渊。", "沐猴希万乘，封豕冠进贤。乘舆辱执盖，箕豆横相煎。", "手持一樽者，不受诸可怜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题淮山楼","p":"如梦令","d":"宋代","a":"苏轼","c":["城上层楼叠巘，城下清淮古汴。举手揖吴云，人与暮天俱远。魂断，魂断，后夜松江月满。"],"tags":["写景", "怀古", "抒情"],"z":"","y":"","s":"","k":"词"},
  {"t":"颂古十八首 其七","p":"","d":"宋代","a":"释师一","c":["孰云意在钁头边，一击圆通彻大千。大笑低头归去后，饥餐且莫与人传。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"双阙步云尾","p":"水调歌头","d":"宋代","a":"邵元实","c":["双阙步云尾，六阁上鳌头。侍臣冠底，英英人物是君侯。闻道东皇深意，回想西清往事，早晚启金瓯。丹扆伫宏略，黄阁待名流。九秋天，千岁日，一樽酬。策勋黄石，相期茅土更封侯。稳扈钩陈天仗，净扫搀抢氛祲，按辔入神州。收了卢龙塞，却访赤松游。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"顺安辞呈赵使君二首","p":"","d":"宋代","a":"刘著","c":["六朝兴废渡河年，旧国归来更黯然。", "八月边城山未雪，芦花藉藉已漫天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"茶瓶儿","p":"","d":"清代","a":"朱祖谋","c":["十载轻衫尘涴。逗乡心、玉梅疏朵。花魂谁与招清些，便料理、五湖单舸。", "雪窗月明愁卧。梦东风、灞桥春锁。熏笼偎夜培残火。", "尚暖得、数椒红破。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"试心石","p":"","d":"明代","a":"王世贞","c":["陡出三尺崖，下临千尺地。道人呼试心，无心可将试。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雁乙酉","p":"","d":"近代","a":"宗远崖","c":["群雁南飞日，孤舟北渡前。风波殊异路，会见待他年。", "尔自随阳去，吾宁向冷迁。颇闻菰米熟，矰缴满天边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠别太常李博士兼寄两省旧游","p":"","d":"唐代","a":"韩翃","c":["两年戴武弁，趋侍明光殿。一朝簪惠文，客事信陵君。", "简异当朝执，香非寓直熏。差肩何记室，携手李将军。", "玉镫初回酸枣馆，金钿正舞石榴裙。忽惊万事随流水，", "不见双旌逐塞云。感旧抚心多寂寂，与君相遇头初白。", "暂夸五首军中诗，还忆万年枝下客。昨日留欢今送归，", "空披秋水映斜晖。闲吟佳句对孤鹤，惆怅寒霜落叶稀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"皇后合五首","p":"淳熙六年春帖子词","d":"宋代","a":"崔敦诗","c":["风光天上倍常殊，花夺阑干昼影舒。", "虚几自临中令帖，明窗时展大家书。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"下皋杂咏 其二十三","p":"","d":"明代","a":"黄仲昭","c":["性癖情知与世殊，秪应归卧故山庐。山中亦有经纶事，朝课耕桑夕校书。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"佳人停板图","p":"","d":"明代","a":"唐寅","c":["仙娥记曲世无双，下直归来日满窗。", "随手托牙镂板在，低头不语暗寻腔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"泛舟自西海至万寿寺 其三","p":"","d":"清代","a":"弘历","c":["招提门枕碧溪流，月相瞻依偶憩留。忆我当年题句处，假山松栝绿阴稠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"唐有怀以九疑之茶分赠二首 其一","p":"","d":"明代","a":"王慎中","c":["永州太守清于水，囊携芳茗担还轻。却分囊茗过闽岭，重儗千钧未比情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和李峤杂咏诗百二十首韵 其七十四 帘","p":"","d":"清代","a":"弘历","c":["望处目疑水，垂来意满秋。碧珠文绣额，银蒜曲琼钩。", "暮雨西山卷，朝霞东户浮。君平开卦处，终日与天游。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"木兰","p":"四明山中十绝","d":"宋代","a":"戴表元","c":["七里黄泥红树冈，西风果熟一村香。", "居人只道山深好，三百年来是战场。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"磅大受赴选天官","p":"","d":"宋代","a":"邹浩","c":["元佑真人初御天，四门穆穆来忠言。", "阆风学士望朝野，即日赐环司谏垣。", "当时同列继登用，独先朝露归九原。", "位不酬身在孙子，嶷嶷诸子声名喧。", "叔也纵横五经内，娱目未始窥家园。", "苟闻某所有贤者，弊车趼仆从之奔。", "甘陵南北正分党，攘臂其间无怨恩。", "未见其止见其进，会须一反映收乾坤。", "素冠俛首琴复御，鹏飞九万方化鲲。", "于今怙恃只明主，肯与世俗均寒暄。", "旦年妙笔三千牍，矧已恸哭论元元。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"车中作愧诗谢潘克强潘乐乐贤父子并三江兄","p":"","d":"当代","a":"卢青山","c":["老人胸何广，豁豁横山川。碰壁夫何物，一蚊嗡其间。", "虎子亦刚烈，大眉如帚悬。得间秉其机，拯我危崖边。", "惭我醉如盲，所为不自观。复如梦游人，醒不记从前。", "苟非三江子，安复识所愆。作诗记其过，因以谢三贤。", "往者不可补，搁笔唯长叹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"遣兴五首 其五","p":"","d":"明代","a":"杨爵","c":["幽囚罪是吐忠肝，日见逻人向北探。圣主无劳关虑切，微臣不以死为难。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿皇太子 其二","p":"","d":"宋代","a":"赵彦端","c":["子晋吹笙未是仙，阿丕横槊少全篇。小吟青著梅梢句，一日东风四海传。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"与林止庵叶半隐分赋郡中古迹得鲁公祠右军","p":"","d":"宋代","a":"艾性夫","c":["遗像犹能立懦夫，悬知生气摄萑苻。", "三郎阿堵知何用，只识营州阿荦奴。", "昏昏水气吐玄云，自是先生笔有神。", "不洗从来姿媚态，可怜北面卫夫人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏日村居四十二首 其二十二","p":"","d":"明代","a":"于慎行","c":["开卷百年万里，连篇落日中原。一任骚坛定霸，争教学海穷源。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"释法言","c":["林下闲看水牯牛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋怀三首","p":"","d":"宋代","a":"周麟之","c":["江远莼鲈晚，迳荒松菊寒。", "近知秋信好，更觉旅怀宽。", "远杵风催急，横琴夜向阑。", "飘零莫惆怅，吾道久艰难。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"出郊即事","p":"","d":"宋代","a":"朱子恭","c":["经行阡陌日迟迟，桑柘才方吐绿枝。", "只为峭寒交节晚，村家却是拂蚕时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵陆南宫晨起有感","p":"","d":"宋代","a":"张镃","c":["骂坐非真豪，挂冠岂实高。", "畸迹烟雨埋，客气利禄鏖。", "曷若大丈夫，本志轻旂旄。", "无择眼界平，共馨等膻臊。", "机息箭自空，谍复论弓橐。", "先生博达姿，阂世江河滔。", "器吞子贡琏，才夺东方袍。", "出处日两忘，居朝隐蓬蒿。", "一代能几人，称提付郎曹。", "饭熟菜亦香，但教齿牙牢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"渔家傲 其一 夏日晓起","p":"","d":"明代","a":"杨慎","c":["鸡唱未圆天已旭。伯劳杜宇声相续。残月笼花风袅竹。", "眠未足。千金难买临明宿。", "叶上露华纷缀玉。青松雨后如膏沐。思爽神清来往独。", "幽径躅。休教踏破苔钱绿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"其一","p":"蜀道难","d":"南北朝","a":"萧纲","c":["建平督邮道，鱼复永安宫。", "若奏巴渝曲，时当君思中。"],"tags":["古诗三百首"],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆得","p":"","d":"元代","a":"范梈","c":["忆得佳人《白纻》词，几将天外数归期。自从落尽庭前树，夜夜秋声总不知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重经山店有感","p":"","d":"清代","a":"张鹏翮","c":["曾忆黄花过水滨，儿童惯见往来频。青山绕舍依然在，迎客门前少一人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和元少卿雪","p":"","d":"唐代","a":"徐铉","c":["朔风飞雪遍遥天，为瑞偏宜在腊前。有客棹舟将命友，何人高卧共称贤。", "瑶花散乱纷临席，玉树晶荧烂满川。閒想冰容比君子，始知姑射有神仙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋怀八首 其六","p":"","d":"明代","a":"李孙宸","c":["关河百二控神京，谁遣当关有横行。徒使至尊思猛士，不闻年少请长缨。", "纶扉上相仍敷阃，属国元戎未解兵。最是防秋宵旰急，可容官府釜镉成。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄题挹山楼","p":"","d":"近代","a":"彭鹤濂","c":["猛忆留溪感又生，山楼曾宿未忘情。白穿虚槛云归寺，绿抱孤村树作城。", "消夏凿池成梦想，匝阴补竹待承平。料知秦望山头月，照到床前分外明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"史太师入觐赐带以不知官高卑玉带悬金鱼为韵","p":"","d":"宋代","a":"释宝昙","c":["弥明晚不逊，不解世俗书。", "邻翁十升水，公无察渊鱼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"知机吟用康节韵","p":"","d":"明代","a":"罗洪先","c":["先物谓之几，旁行且入微。有无未分处，主宰不移时。", "得者须忘意，知之莫泥词。虽从静里得，却向动中知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"积雨作寒五首 其三","p":"","d":"宋代","a":"范成大","c":["熨帖重寻毳衲，补苴尽护纸窗。馀生雪鬓禅榻，昨梦云帆涨江。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠朱静芳大姐","p":"","d":"近代","a":"聂绀弩","c":["急人之急女朱家，两度汾河走飞车。刀笔纵横光闪闪，化杨枝水洒枯花。", "劝君更尽一杯茶，千里万里亦中华。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和徐子由题昼寂轩","p":"","d":"宋代","a":"黄公度","c":["木落孤城迥，苔封古寺深。", "结庐依近地，隐几惬幽心。", "细草秋仍绿，修篁晚更阴。", "红尘门外路，六辔漫如琴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"友人惠芍药并青梅一枝偶成三绝 其三","p":"","d":"宋代","a":"葛胜仲","c":["香雪一林初著子，和枝分饷不吾悭。含酸但止文园渴，青琐无人蹙远山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋兴 其三","p":"","d":"明代","a":"魏学洢","c":["天高着处可徜徉，日日优游日日忙。瘦菊倚风同客笑，短篁摇影共人长。", "旧疑西蜀诗无律，近信东皋醉有乡。薄暮凭阑清眺迥，水青云白淡秋妆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"光宣杂咏 其二十六","p":"","d":"近代","a":"冒效鲁","c":["雅词略近汪容甫，博学差同顾涧蘋。月旦过庭天下喻，北王南李两文人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百零二首","p":"","d":"宋代","a":"释绍昙","c":["山雨酿春寒，晓湿梅花重。", "结实较迟迟，且听香浮动。", "化工有意待重来。永为鼎鼐调羹用。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"薛岭","p":"","d":"宋代","a":"张翥","c":["衣冠陈氏族，桃李薛公园。场老遗文古，岩僧旧迹存。", "苔矶荒碛岸，金榜勒瑶琨。已怜松特异，尤喜石能翻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"文昌醮灯牌","p":"","d":"宋代","a":"阳枋","c":["牡丹枝上先春蕊，翠杏坛边未雨虹。知有文章光万丈，钟成佳气满黔中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"享太庙乐章。大成舞","p":"","d":"唐代","a":"魏徵","c":["周穆王季，晋美帝文。明明盛德，穆穆齐芬。", "藏用四履，屈道参分。铿锵钟石，载纪鸿勋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅花 其二","p":"","d":"宋代","a":"陈景沂","c":["从来造化有何私，自是梅花南北枝。只为北枝太寒苦，东君消息故应迟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄宋使君","p":"","d":"唐代","a":"贯休","c":["寺倚乌龙腹，窗中见碧棱。空廊人画祖，古殿鹤窥灯。", "风吼深松雪，炉寒一鼎冰。唯应谢内史，知此道心澄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"即事","p":"","d":"宋代","a":"郑刚中","c":["竹舆晓出见湖山，小室焚香暂得闲。", "帘动东风入双蝶，清愁何处不用关。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和益阳赵宰六首 其二","p":"","d":"宋代","a":"廖行之","c":["食黮从吾化，安舆本若情。有能奔晋盗，何用筑秦城。", "一邑诚天幸，三年赖政平。儒功固如许，仪舌漫纵横。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"桃源洞","p":"","d":"清代","a":"顾鉴","c":["路问桃花源，遥指白马渡。晻蔼云气深，秦人从此去。", "秦人去千载，白云长自护。何年灵境开，花源忽呈露。", "从此传人间，物外感生聚。我来已深冬，不见桃花雨。", "林深水无源，水绕山回互。草木净余芳，鱼鸟适幽趣。", "仿佛鸡犬声，远出云中树。奇踪托杳渺，欲觅曾无路。", "嗟彼武陵渔，津逮仍迷误。为问避世人，高举将焉赴。", "渊明结妙想，孤怀聊自寓。寓言非人间，惝恍何所慕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丁亥留节翁城，同诸公行长至礼","p":"","d":"明代","a":"张煌言","c":["几年卧节梦金銮，绵蕞犹班旧握兰。葭管初开周甲子，葱珩重见汉衣冠。", "嵩呼恍觉炉香近，海曙还疑扇影寒。惟有臣心冰雪净，誓将綵线续双丸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"生查子（梅）","p":"","d":"宋代","a":"晁补之","c":["青帝晓来风，偏傍梅梢紧。未放玉肌开，已觉龙香喷。", "此意比佳人，争奈非朱粉。惟有许飞琼，风味依稀近。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杜鹃鸟二首 其一","p":"","d":"当代","a":"卢青山","c":["凄鸣如不足，更傍吾身飞。我若能归去，安用子相催？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"冀馆春夕见月","p":"","d":"宋代","a":"王圭","c":["甚宠无如使牡行，曾同万里听秋声。黄金台下嘶宛马，木叶山前度汉旌。", "才到关南逢雁尽，重来海上见波平。故人临月应相望，一夕寒光特为明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"汤思退","c":["虞妃从梧野，启母祔稽山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"昨夕不知有雪而晨起四望远峰皆已变色再用元韵作两绝句 其一","p":"","d":"宋代","a":"朱熹","c":["朔风吹尽暮云平，室暖炉红睡达明。但怪朝来满山白，不知昨夜打窗声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"《女儿曲》脱稿即题其末","p":"","d":"当代","a":"卢青山","c":["偶尔相逢说古亭，为君长撰女儿行。一天荒月埋魂地，百代秋风捲梦人。", "但有平和能到死，更无歌哭可疗心。我而非主君非客，两坐闲看淡淡春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题画罗汉 其六","p":"","d":"清代","a":"戴梓","c":["偶逢一石，就之欲眠。岩草拥后，松风落前。西方东土，山隈海边。", "有此乐国，可以永年。如水出泉，清不费钱。梧桐一叶，临秋翩翩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和柯狮山大参山中十二景 其六 群峰送青","p":"","d":"明代","a":"黄衷","c":["江上兹山与岳尊，腾猿回鹤谩纷纷。帘端矗矗群峰翠，一笑真同列戟分。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂兴十二首","p":"","d":"宋代","a":"方回","c":["生世六六载，始获玷末科。", "选官六六载，仕少閒日多。", "逆旅脱兵火，专城免干戈。", "中原久隔绝，忽焉得经过。", "水涸梁山泊，淮流受黄河。", "往者故已矣，方来将若何。", "开岁七十一，聊拟自挽歌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"螃蟹咏","p":"","d":"清代","a":"曹雪芹","c":["铁甲长戈死未忘，堆盘色相喜先尝。", "螯封嫩玉双双满，壳凸红脂块块香。", "多肉更怜卿八足，助情谁劝我千觞。", "对兹佳品酬佳节，桂拂清风菊带霜。"],"tags":["咏物", "议论", "讽刺"],"z":"","y":"注释 铁甲长戈：比喻蟹壳蟹脚。宋代陈郁为皇帝拟进蟹的批答说：“内则黄中通理，外则戈甲森然。此卿出将入相，文在中而横行之象也。”见《陈随隐漫录》。 色相：佛家语，指一切有形之物。借用来说蟹煮熟后颜色好看。 “多肉”句：即“更怜卿八足多肉”。上一联已说螯满、膏香，故这句用“更”字说蟹脚多肉。怜，爱。卿，原本是昵称，这里指蟹。 “助情”句：意即“谁劝我饮千觞以助情”。觞，酒杯。助情，助吃蟹之兴。 兹：此。佳品：指蟹。酬：报答。这里是不辜负、不虚度的意思。佳节：指重阳。 桂拂清风：即“清风拂桂”。","s":"","k":"诗"},
  {"t":"偶题","p":"","d":"明代","a":"王世贞","c":["许由能乞万乘身，归卧箕山天地新。过宿翻为窃屦客，饮流仍遇弃瓢人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"庵中杂书四首 其二","p":"","d":"宋代","a":"陆游","c":["谋生安用苦区区，豆饭藜羹未遽无。若使天年犹合活，不妨自有谷于菟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏菊三首 其一","p":"","d":"当代","a":"崔荣江","c":["总道春温叫骨羸，秋风邀约向身吹。平明雨冷濡青领，更晚霜清挑白眉。", "云淡花开堪仰月，世昏人倦罢吟诗。较来篱上黄花瘦，隐忍多输那一枝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"览古五首 其二","p":"","d":"宋代","a":"方回","c":["读书以脩身，末惟利之渔。夏侯诧拾芥，桓荣陈其车。", "初学眯训诂，利心已炎如。为吏未识字，嗜贿不顾躯。", "青青陵陂麦，歌声何舒舒。金椎勿造次，恐伤口中珠。", "岂不事诗礼，所为乃凶渠。用世率此辈，生灵夫何辜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"林泉归隐图","p":"","d":"明代","a":"德祥","c":["居山岂为山，只爱此中闲。野菜何消种，柴门不要关。", "饭余听涧落，经罢看云还。恐有寒山句，多题藓石间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"初游黄山二首","p":"","d":"近代","a":"宛敏灏","c":["云谷松风送晚凉，披襟跣足话长廊。人生几得名山宿，梦里微闻百合香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠杜幼高","p":"","d":"宋代","a":"叶适","c":["杜子五兄弟，词林俱上头。", "规模古乐府，接续后春秋。", "奇崛令谁赏，羁栖浪自愁。", "故园如镜水，日日抱村流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"高生规当岁贡遇生日","p":"","d":"元代","a":"李延兴","c":["天风环佩响珊珊，瑶海秋高王母还。好著莱衣娱鹤发，要将董策觐龙颜。", "霞翻锦帜金鸾殿，日射丹墀玉笋班。待得瓦桥春雪霁，马嘶官路彩云间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏壁上尘","p":"","d":"清代","a":"敦敏","c":["软红何事傍闲居，入户穿帘费扫除。人去旗亭诗暗淡，烟昏古屋画萧疏。", "飞扬不受将军拜，依附偏宜贫士庐。识得庄生野马意，遥瞻环堵自如如。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"曾子固令咏齐州景物作二十一诗以献 其二十一 北渚亭","p":"","d":"宋代","a":"孔平仲","c":["高深极前临，苍莽接回眺。齐州景物多，于此领其要。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"示儿定孙二绝 其二","p":"","d":"宋代","a":"陈淳","c":["丈夫尚志志高明，勿效卑卑世俗情。从上一条平坦路，千贤万圣所通行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽钱贞庵","p":"","d":"明代","a":"徐庸","c":["海虞山水古今清，人物生成属地灵。刘汉宗支曾按谱，相君事业早传经。", "应时润泽同甘雨，文节昭明拟列星。名向世间崇闻望，□于乡里作仪刑。", "惟将籴米资凶岁，不逐纶音入内廷。吟咏性情居宅第，逍遥□□在林□。", "花边曙墅开棋局，竹底藏钩醉绿□。争羡寸心恒坦荡，不堪双鬓渐凋零。", "黄金鼎在宜脩炼，白玉楼□赴杳冥。千里竟闲骐骥足，九苞还振凤凰翎。", "董狐有待今为传，郭养无惭旧述名。白鹤不归华表柱，漆灯光冷夜台扃。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋夕怀子厚二首 其一","p":"","d":"宋代","a":"朱熹","c":["雨歇林气爽，月华湛遥晖。斋居玩物变，廓落沧洲期。", "焚香散碧虚，抚节陈清诗。抗志属云端，非君谅谁知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题社友诗稿","p":"","d":"宋代","a":"邓允端","c":["诗里玄机海样深，散于章句敛于心。", "会时要似庖丁刃，妙处应同靖节琴。", "韵胜想君言外得，字新令我意边寻。", "痴人说梦终难信，何日樽前取次吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书兴四首","p":"","d":"宋代","a":"汪炎昶","c":["兴逼不暇卧，蹑屐鸣难先。", "裛袂碧氛润，袭襟爽概繁。", "噫馁出故气，咽甘漱新泉。", "骨瘦易酸楚，骨虚觉轻便。", "樵子隔岭见，宁谓吾非仙。", "手持白羽扇，笑坐青崖巅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"八月十九日得董正翁寺丞书兵疫后城中故旧十","p":"","d":"宋代","a":"舒岳祥","c":["黄菊一瓶酒，青山四壁书。", "吾年余岁许，天意复何如。", "寒日沙禽并，风霜野果疏。", "山城询故旧，十九是丘墟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"度岭","p":"","d":"明代","a":"吴鼎芳","c":["林僧言别去，自憩松下石。", "红泉界空翠，巢居叫霜笛。", "夕光淡西水，千顷成一碧。", "冷信雁传来，秋容枫点出。", "闲云满怀袖，邀我过山脊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送彦斌弟还侍","p":"","d":"明代","a":"郑潜","c":["我方避地贫尤甚，子独还乡岁又阑。浮世风尘妨孝节，平生事业负儒冠。", "空怀鹤禁陪移步，远愧鸰原救急难。千里畏途当自爱，北堂珍重慰加餐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"扈从谒陵十咏 其二 沙河驻跸","p":"","d":"明代","a":"倪谦","c":["晓驻旌旗遍野红，貔貅百里卫行宫。山连北极三千刃，身在中坚十二重。", "散骑徐牵金络马，将军齐带宝雕弓。八珍已进天厨膳，甲帐弹棋啜紫茸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"平湖病中思南归六首 其三","p":"","d":"明代","a":"林光","c":["冬卧愁襟薄，跏趺付一卢。难将衰病骨，更听夜啼乌。", "地暖思南海，情真有旧徒。飘然决归策，争只为莼鲈。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和吏部薜员外见寄","p":"","d":"宋代","a":"王禹偁","c":["枨也好刚多悔吝，唯凭忠信自书绅。", "严陵知退遗荣利，只拟沧浪把钓纶。", "老去趁朝慵待旦，病来求假动经旬。", "西垣兴味更谙尽，一片乌纱满马尘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"岩桂花","p":"","d":"宋代","a":"郑仲熊","c":["天公怜我太岑寂，每岁殷勤两度开。", "收拾落英将底用，博山香裹荐清杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送沈琛笙归衡山 其四","p":"","d":"清代","a":"许南英","c":["清漳山水多生色，印住衡山老寓公。食不累官今闵贡，舂甘赁庑古梁鸿。", "秋高欲送伊人去，世乱应宜我辈穷！相士半生今有几，昂头欲捣碎虚空。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋兴亭","p":"","d":"宋代","a":"韩扬","c":["贾载尝为郡，名亭建此邦。", "近山连大别，远水接长江。", "待月凭东槛，来薰起北窗。", "四时皆有兴，秋兴独难降。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"微雨后风沙大作晚泊临清","p":"","d":"明代","a":"黄佐","c":["笑辞钟鼎向山林，去路尘沙苦见侵。万里舟航淹日月，九河风雨战晴阴。", "草堂花竹萦春梦，泽国鱼龙伴夜吟。心迹不教双寂寞，灯前呼酒漫开襟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"章几道将归小饮怀谢城父","p":"","d":"宋代","a":"叶梦得","c":["中年甚畏别交亲，况复云山旧结邻。涧谷何时同笑语，干戈已老更风尘。", "少留对榻聊分坐，多病持杯漫几巡。贾傅长沙知健否，洞庭波浪渺无津。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和津喜雪二首 其二","p":"","d":"宋代","a":"吴芾","c":["我爱平湖绕碧山，山光倒碧到樽前。同云何事迷千嶂，飞雪俄然蔽一川。", "纵使玉楼从地涌，便教银阙与天连。到头幻化非真实，争似湖山耐岁年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和钱孙叔委心亭二绝 其一","p":"","d":"宋代","a":"胡寅","c":["交衢尘雾祗相煎，回首山林去未缘。安得委心无一事，陪公清话许忘年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"解佩令 江州讯吴松严令君","p":"","d":"清代","a":"丁澎","c":["城临小别，无多听事，近潇湘、弄雨疏帘静。束带公庭，苦相对、督邮清冷。", "漫争夸、故人为令。行云赋手，善描神女，早吹来、阳台艳影。", "瓮发彯清。可钓有、槎头缩颈。趁烟波、晚楼同凭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵王信州","p":"","d":"宋代","a":"邓肃","c":["煤炱飞上天，沉沉三日雾。", "银河一压摧，狂雨恣横骛。", "我恐铁骑来，疾驰不纳屦。", "气豪如项羽，势猛似黥布。", "瀰漫江海接高穹，石牛未洗血泥红。", "天吴八首真奇怪，咄嗟平地作银宫。", "我贫家火不星灶，赤脚灭没泥涂中。", "目断晓风生少女，又复茅檐飞白龙。", "惭愧北来王夫子，籍籍声名满都鄙。", "朝吟千赋暮千诗，松腴亦须枯海水。", "莫倚文章似孟坚，未用风流追乐天。", "且以光芒破阴晦，挽回日色到桑田。", "乐岁天公有严约，斥落旄头沉贯索。", "从公日醉三百杯，不怕西风动旗脚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"故太原郡太夫人李氏挽歌诗二首 其一","p":"","d":"宋代","a":"赵鼎臣","c":["德配平原盛，家传相国亲。桂抽三笋茂，玉种两株成。", "化剑中秋冷，藏舟半夜惊。凯风从此去，忍听自南声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"将赴都门","p":"","d":"清代","a":"刘青藜","c":["十载长安道，风尘鬓欲皤。天宁哀志气，人尽笑蹉跎。", "日落汾丘垒，冰胶䩐勒河。又驱羸马去，惆怅意如何？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赋得江介多悲风用风字","p":"","d":"清代","a":"顾炎武","c":["素节乘云梦，清秋下渚宫。哀音生地籁，激楚入天风。", "落雁过山急，寒蝉抱树空。伤心干里目，愁绝百年中。", "郢路元依北，江关久向东。有人宗国泪，何地洒孤忠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山气","p":"","d":"清代","a":"黄钺","c":["山气夜沈郭，苍茫晓未收。寒风来绝塞，入夏尚重裘。", "盘马雪千里，射雕天尽头。平生极飞动，惜不壮时游。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄怀沈君接 其一","p":"","d":"明代","a":"沈守正","c":["与君灵鹫十年身，我别君留百感新。千里同舟淮角酒，一樽小坐断桥莼。", "君家春酿碧于水，此处山茶赤似唇。两志栯情兼有恨，梅花西碛少谁人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南岳纪游 其四","p":"","d":"明代","a":"黄廷用","c":["斋心净献玉坛文，前殿歌钟后殿闻。杳霭若承云旆下，西来又礼魏元君。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次敖静之九日言怀韵","p":"","d":"明代","a":"马中锡","c":["骑马闻鸡有底忙，一秋憔悴沈东阳。", "身随杖竹空存节，鬓比篱花不耐霜。", "帝载八年纷奏绩，王师六月苦周章。", "何须更落西风帽，黄叶填门独举觞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"胡歌","p":"","d":"唐代","a":"岑参","c":["黑姓蕃王貂鼠裘，葡萄宫锦醉缠头。", "关西老将能苦战，七十行兵仍未休。"],"tags":["边塞", "战士"],"z":"黑姓蕃王：指统辖一方的少数民族王侯或高级将领。黑姓，是西突厥的一个部族，唐开元、天宝时代，西突厥分为黄姓、黑姓两部。这里未必是确指，当泛指某少数民族将领。貂鼠裘：即韶皮袍子。\n葡萄宫锦：绣有葡萄图案的丝织品。宫锦，王宫中所用的名贵丝织品。醉缠头：唐人宴会时，常酒酣起舞，赠舞者以缠头。缠头，古时歌舞的人把锦帛缠在头上作妆饰，称为“缠头”。\n关西：指函谷关以西地区。汉代有“关西出将，关东出相”的说法。\n行兵：统兵作战。","y":"黑姓蕃王身穿貂鼠皮袭，酒醉起舞得来彩缎锦绸。\n关西老将惯于辛苦征战，年已老大仍然转战不休！","s":"诗的前两句写边镇少数民族将领的逸乐。从三个方面写黑姓蕃王的生活：一是穿着：貂鼠裘以示名贵；二是宴饮：写纵荡不羁；三是玩物：葡萄宫锦以示器物的奢侈。写边镇蕃王，不去写他的军事生活，而是选择一些细节写他的享乐生活，可以看出他们的地位，他们的骄纵。\n\n  诗的后两句写关西老将长期征战之苦。“能”，主要不是说具有能力，而是说其不得已。一个“苦”字，是关西老将全部征战生活的写照。“七十”，写出了老将年迈而非确指。“仍”概括了老将过去，现在和将来的征战生活，“苦”字自在其中。写“关西老将”专写其征战生活，与“黑姓蕃王”适成鲜明对照。“黑姓蕃王”逸乐如彼，“关西老将”苦战如此，诗人因而感慨。诗中仅把两种鲜明对照的现象作客观罗列，而写的实际是诗人所感。\n\n  岑参这篇作品以自己边地所见把“黑姓蕃王”与“关西老将”作鲜明对照，表现了汉、蕃两族将领的苦乐不均，这样，这首诗就上升到了政治层面，使诗歌境界得到了提升。","k":"诗"},
  {"t":"崖山大忠祠 其二","p":"","d":"明代","a":"沈周","c":["二公至此不能为，力尽堂堂是死时。一块肉同今日丧，孤儿事属老天知。", "弱流万里难容楫，清酤三行欲动旗。一殉毅然酬所养，厓山堪壮不堪悲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题方坦庵太史𤾂山语石","p":"","d":"清代","a":"智豁","c":["撑云吸露貌奇峰，声借流泉色借松。昔日点头今日语，生公应让海门龙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹊踏花翻 西秦车中携鹦鹉南归，数日飞去","p":"","d":"清代","a":"董元恺","c":["陇树秋深，秦宫月落，携将鹦鹉随归骑。归来水驿山程，听慧堪论，新诗读向闺人记。", "朱帘初捲忽开笼，青云直上堪垂翅。惊视。千里高飞难致。", "空辜负、主人情意。怎似燕燕相依，年年频至。好把奇毛秘。", "思乡莫便入函关，且教历尽江南地。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"踏莎行 秋怀","p":"","d":"清代","a":"周兰秀","c":["叶落平沙，云迷远树。山色模糊人唤渡。芙蓉笑摘上兰桡，轻鸥惊入波心去。", "衰柳含烟，凉蝉咽露。年年重觅王孙路。可怜人静玉楼空，满庭芳草家何处。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和陶答庞参军","p":"","d":"宋代","a":"苏轼","c":["留灯坐达晓，要与影晤言。下帷对古人，何暇复窥园。", "使君本学武，少诵《十三篇》。颇能口击贼，戈戟亦森然。", "才智谁不如，功名叹无缘。独来向我说，愤懑当奚宣。", "一见胜百闻，往鏖皋兰山。白衣挟三矢，趁此征辽年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"茶汤会乞颂","p":"","d":"宋代","a":"释法薰","c":["铺心无下亦无高，一等无心次第浇。", "便是口吞三世佛，沾化涓滴也难消。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过郑丞","p":"","d":"明代","a":"张元凯","c":["郑公门似水，杨柳绿如丝。自哂官阶小，那嫌堂构卑。", "飞花竟亡赖，归燕不愆期。投辖人皆醉，毋烦置驿为。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雪夕","p":"","d":"宋代","a":"陆游","c":["目视左（左目右荒）（左目右荒）耳聋，吾衰略与昔人同。", "移灯自看伶竮影，取酒时浇礧磈胸。", "东郭稍能师顺子，北山未敢笑愚公。", "空村雪虐风饕夜，袖手悠然政策功。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望江南 秋夜","p":"","d":"清代","a":"薛斑","c":["更漏永，起坐自伤神。嘹呖雁鸿悲远迹，凄凉砧杵响寒村。", "入耳总销魂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠同年邵文敬","p":"","d":"明代","a":"江源","c":["忆别杏园时，南北各命驾。屈指将十年，偶得一慰籍。", "示我珠玉篇，一气无漏罅。胸中小溟渤，笔底夺造化。", "譬之桓文师，节制雄五霸。又如养由基，百中仰神射。", "纸价贵洛阳，谁能不脍炙。君才出天然，我辈风斯下。", "三复不释手，秉烛到深夜。细嚼有馀味，何啻倒餐蔗。", "愿言继三百，袖然陋鲍谢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东坡祠","p":"横浦十咏","d":"宋代","a":"刘黻","c":["何年海上还，坐镇此山川。", "笔砚归京阙，衣冠带瘴烟。", "一生忠胆在，万古党名传。", "吾道多流落，西风问老天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送袁季源之婺州因简范经历","p":"","d":"宋代","a":"戴表元","c":["为山不愿高，为水不原深。", "水深蛟龙集，山高虎豹蹲。", "我有避人法，终日衣冠林。", "煌煌钱塘城，游尘书为阴。", "岂无青云交，难在相天心。", "岂弟袁大夫，寒窗理闲琴。", "峻坂为牛力，炎天九秋襟。", "胶漆四十年。龆龀以至今。", "天欲饥饿我，使子无黄金。", "劝仕拙不谐，驱耕弱难任任。", "低回向谁门，后生气骎骎。", "今晨积潦霁，乌乌有好音。", "约我共行役，东平步嵌嵌。", "皎皎婺女精，瀰瀰双溪浔。", "台有白马生，风棱共萧森。", "文林惜妄动，动必向所钦。", "吾评古毛义，志行近骞参。", "参府许辟召，屈身非禄淫。", "斯人我知旧，长髯吴吟。", "穴蚁梦离合，风花命浮沉。", "往者纳千贽，终然遗一簪。", "欲行又不得，出门失前禽。", "子往再拜问，何由振聋暗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寓寺八首","p":"","d":"宋代","a":"张耒","c":["翠眉长好何曾损，寄语啼禽漫不闲。", "应为残春足愁恨，长疑蹙破镜中山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"高丽炉一枚寄虎丘结","p":"","d":"宋代","a":"曹勋","c":["兹炉之先，鲸波空际。有国曰韩，以陶以器。奉之函丈，宝烟轻细。", "此一瓣香，用严报地。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送明守黄子由尚书赴召","p":"","d":"宋代","a":"孙应时","c":["灯火笙歌别海壖，诏书归觐九重天。", "已将清净安齐国，不使声名减颍川。", "题品人才看赞赞，夫持皇极在平平。", "文星旧与文昌亚，今贯三台更炳然。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋怀十首 其三","p":"","d":"宋代","a":"陈师道","c":["采薪墟墓间，行歌当归耕。向来轻薄子，怀谖以为荣。", "喘喘辕下犊，力尽官泥深。壮哉八百里，一割探其心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"富池江口夜泊（二首）〗","p":"","d":"明代","a":"郭奎","c":["草昧英雄望列侯，梦中三十六春秋。", "功名总被儒冠误，两岸啼猿一夜愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送李生南归寄戴笠王锡阐二高士","p":"","d":"清代","a":"顾炎武","c":["华山五粒松，寄向江东去。白云满江天，高士今何处。", "忆昔过湖滨，行吟两故人。潜龙犹在水，别鹤已来秦。", "江海多翻覆，林泉异栖宿。惊闻东市琴，涕陨堂前筑。", "去去逐征蓬，随风西复东。风吹兰蕙色，一夜落关中。", "五陵生蔓草，愁绝咸阳道。平生四海心，竟作终南老。", "送子出函关，南山望北山。洞庭多桂树，折取一枝还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谢袁子久观察赠马","p":"","d":"清代","a":"李嘉乐","c":["驴背寻诗味饱谙，拟将行李一囊担。驰名已觉输中驷，赠别偏劳释左骖。", "备位八驺君可致，起家五马我何堪。鞭丝遥指青州路，覂驾毋贻旧友惭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题曹怡轩樵笛吟稿四首 其三","p":"","d":"宋代","a":"萧立之","c":["吟到古人诗近道，洗空凡马画通神。浣花溪上惊人句，剪绿裁红不当春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"观园丁除草","p":"","d":"明代","a":"孙承恩","c":["中园种嘉蔬，地瘠蔬叶稀。蔓草杂其间，复尔缠绵之。", "六月盛炎暑，亭午张赫曦。园工力芟锄，根株俾无遗。", "造化普发育，雨露无偏私。去恶佑善良，人事理则宜。", "兰蕙生当门，斩刈不得辞。矧尔恶类繁，不去将何为。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题飞霞图为江鍊师赋","p":"","d":"明代","a":"刘崧","c":["海上群峰映紫霞，五云楼观是仙家。谁吹玉笛春风起，千树碧桃都作花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清平乐","p":"","d":"宋代","a":"石孝友","c":["山明水嫩。潇洒桐庐郡。极目风烟无限景。说也如何得尽。", "自怜俗状尘容。几年断梗飘蓬。借使严陵知道，只应笑问东风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵李似表县丞出示游西湖古风二首 其二","p":"","d":"宋代","a":"李纲","c":["李侯嗜学古，馀事皆远屏。昂昂鸾鹄姿，岂与凡禽并。", "捧檄来南州，初识浙江境。寻盟款吾庐，不待日中定。", "从容叩所得，响答如汲井。时方罗俊乂，宁久淹簿领。", "清秋雕鹗飞，大道骅骝骋。词章尤激昂，笔力可扛鼎。", "虚堂纵谈笑，霜月挂金饼。夜阑言愈微，至味嚼佳茗。", "古来会合难，岁月积俄顷。愿子谨所之，万里路方永。", "吾衰老閒旷，轩冕志已冷。栖迟丘壑间，此兴良自肯。", "他日来相遇，梁溪寻钓艇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题龙隐岩","p":"","d":"宋代","a":"王迤祖","c":["龙蟠此地不知年，飞去穿成万仞渊。", "霖雨四方今欲遍，后人空自想蜿蜓。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题孟氏惠麓小隐","p":"","d":"明代","a":"秦夔","c":["饥后家何在，归来始定居。丹心三尺剑，白首五车书。", "戚畹名犹在，云台业未疏。结庐来小隐，岁晚足耕锄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"哀故文节公 其一","p":"","d":"宋代","a":"宋祁","c":["早传黄石系，未伴赤松游。暴疹惊床蚁，深恩赐养牛。", "溪璜俄碎玉，川楫遂藏舟。萧相今无嗣，夫人绍酂侯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"定风波 无题","p":"","d":"当代","a":"许白凤","c":["薄薄春衫剪剪风。凋颜不媚杏花红。何处飞来双燕子。", "知是。隔墙人去画楼空。", "有约年时寻斗草。娇小。似曾相识唤聪聪。回首韶光都是恨。", "休问。落花无语水流东。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送安仪凤","p":"","d":"宋代","a":"田锡","c":["宣城相送思依依，正是红莲菡萏时。", "行色迎秋清似画，别情因景化为诗。", "人离湖水南边岸，蝉听槐花北向枝。", "天子文明是何地，丹霄岐路莫生疑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闺怨","p":"","d":"明代","a":"张博","c":["那年离别去，只道投京国。京国人不归，音书到塞北。", "少年夫妇不同欢，纵使封侯有何益。还家拜母心内伤，何不当时委道傍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"王承德四时花鸟图 其一","p":"","d":"明代","a":"王佐（汝学）","c":["杏花疏雨枌香深，朵朵迎风艳不任。老眼不谙花态度，从教春色付山禽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠梧窗先辈","p":"","d":"明代","a":"王渐逵","c":["亭亭青桐树，郁翠何森森。华滋荫朝露，丹葩耀阳林。", "孤根众所忌，摇落岁月侵。天涯有美人，窈窕盟素心。", "愿作清商操，为君膝上琴。出入两相随，自此双南金。", "固兹思与惠，永以助徽音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"光宗皇帝挽诗二首 其二","p":"","d":"宋代","a":"周必大","c":["仁爱周华夏，英聪贯古今。知人符日照，裕物称天临。", "閒退亲传子，忧劳旧损心。景光昭百世，昧谷谩西沉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自青诗 其八","p":"","d":"明代","a":"王世贞","c":["小道可观，致远则非。从臾如流，狂张若驰。嶭彼乔山，蹇拟陟之。", "爚彼烈炎，徒思炙之。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"斑鸠","p":"","d":"明代","a":"陈玺","c":["香禽自何处，共立枝头语。唤起晓耕人，西畴足春雨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"献李提军奠原三首 其三","p":"","d":"明代","a":"陈恭尹","c":["画角风清静海涛，郊坰共喜见干旄。金方气肃崆峒壮，南斗功成日月高。", "姬旦吐哺元自贵，卫青揖客不言劳。天涯贱子能扪虱，怀剌空惭有二毛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"琴曲四章","p":"","d":"清代","a":"曹雪芹","c":["风箫箫兮秋气深，", "美人千里兮独沉吟。", "望故乡兮何处？", "倚桂杆兮涕沾襟。", "山迢迢兮水长，", "照轩窗兮明月光。", "耿耿不寐兮银河渺茫，", "罗衫怯怯兮风露凉。", "子之遭兮不自由，", "予之遇兮多烦忧。", "之子与我兮心焉相投，", "思古人兮俾无尤。", "人生斯世兮如轻尘，", "天上人间兮感夙因。", "感夙因兮不可惙，", "素心如何天上月！"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"昨晚目录之句盖聊以为戏耳何分惠之甚速耶得非乞诸其邻乎","p":"","d":"宋代","a":"虞俦","c":["累累火齐忽堆盘，水里硫黄得饫餐。忆得旧时风味在，故人唯有一任安。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春晚用对酒韵","p":"","d":"宋代","a":"陆游","c":["吾今归哉复归哉，草堂正对湖山开。座铭漆园养生主，屏列柴桑归去来。", "一闲可敌八珍美，骊驹在门端可起。不缘老病日日增，世味从来淡如水。", "故人谁非白头新，况复眼中无故人。但馀一恨未免叹，掩关睡过今年春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"钱塘怀古","p":"","d":"明代","a":"王鸣雷","c":["越鸟偏从越客栖，哑哑飞过秣陵西。梦归杨柳多生水，心想芙蓉尽种堤。", "江色草侵吴地阔，月明帆隔楚天低。相招直向渔人问，棹入沧浪何处溪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"玉连环","p":"","d":"清代","a":"朱祖谋","c":["花翻歌扇衣香卸。梦云低亚。沙棠双桨绮罗尘，愁不耐、沧波泻。", "风定絮花凝榭。晚莺閒话。不辞高馆领春寒，坚坐看、斜阳下。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再用前韵","p":"","d":"宋代","a":"郭印","c":["我生垂四十，两鬓抽素发。", "声色不挂眼，岂羡凌波袜。", "唯有学道心，了不见超越。", "何由插羽翰，往造金门谒。", "反观金水性，端似天边月。", "本从无中来，一物肇恍惚。", "玉兔吐寒光，琪树遥清樾。", "亭亭照八弦，圆影射沧渤。", "斯言世岂闻，轻泄恐天罚。", "吁嗟夸毗子，自分无仙骨。", "狥财析秋毫，嗜酒醉深窟。", "一迷不复返，长病如中暍。", "空存玄牝门，金枢已摧阙。", "犹为儿女计，白首恋簪笏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九日与诸僚长登茱萸亭","p":"","d":"明代","a":"潘梅","c":["令节凭高引兴长，半天秋色落壶觞。茱萸亭畔濡凉露，砧杵人间捣夕阳。", "天碧纵横啼过雁，山青悲咽乱唫螀。不知此日龙山会，潦倒谁如落帽狂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉饯高尊师如贵道士传道录毕归北海 【录竹","p":"","d":"唐代","a":"李白","c":["道隐不可见，灵书藏洞天。吾师四万劫，历世递相传。", "别杖留青竹，行歌蹑紫烟。离心无远近，长在玉京悬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闲述","p":"","d":"明代","a":"王彦泓","c":["一径松声几菊丛，穷楼风味未全穷。买泉试点秋茶绿，僦骑停看晚树红。", "非睡即游铅椠少，吊归兼醉锦囊空。残编更把东轩烛，牛背斜阳读未终。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"喜雨十首 其六 雨舟","p":"","d":"清代","a":"弘历","c":["旱甚鱼遭竭泽忧，舟胶都类置杯舟。所欣大霈苏物命，讵为长川畅已游。", "桂棹筠篷方利济，明滩暗濑总增流。一帆书画襄阳似，风片烟丝卒未休。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"黄鹤谣寄吴季谦侍郎时季谦自德安入城予适以","p":"","d":"宋代","a":"岳珂","c":["卢山白鹤归来双，缟衣素袂玄为裳。", "翅如车轮夜横江，风声曾走淮淝羌。", "戛然长鸣下柴桑，芝田啄粒遥相望。", "何人纲罗倏高张，上决云汉旁八荒。", "一随鹏鹍惊远翔，低头不肯谋稻粱。", "一罹置弋沮泽旁，局身筠笼翅摧藏。", "鹦鹉洲畔葭苇乡，水云苍苍江茫茫。", "九皋欲闻声不扬，回雇鸥鹭羞颜行。", "忽闻缑笙度宫商，红尘俯视有底忙。", "矶头刷羽今正黄，欲捶此楼呼酒狂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和俞几先喜雨二首 其二","p":"","d":"宋代","a":"曾协","c":["自嗤宦况局寒蝉，已觉归心决大川。勿使山灵长谢客，幸馀溪友旧忘年。", "无心欲羡千钟禄，有意初谋二顷田。雨足年丰无一事，春蚕将老只思眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"兰","p":"","d":"元代","a":"郑元祐","c":["恊以鼓琴，世谁知音？采苢纫佩，湘江水深。兰生棘中，如石轥玉。", "玉受不瑳，幽香满谷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"罟里瞿良士属题先德子雍先生柴门临水图蒋子延所绘二首 其一","p":"","d":"清代","a":"夏孙桐","c":["水边林屋清无尘，惟许访书来问津。通德高门世所仰，先生原是菇芦人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"箜篌引","p":"","d":"明代","a":"胡应麟","c":["良时率已迈，蟋蟀鸣我床。眷言召亲友，旨酒罗中堂。", "东邻饰妖女，南陌招名娼。绡衣随风举，罗袜自飘扬。", "秦声被金石，楚曲流宫商。清谈蔚霞烂，妙舞若云翔。", "颓阳倏西落，明月出东方。飞轩历层囿，改席临洞房。", "华灯吐芳焰，列宿澄清光。齐心怀令德，四坐咸尽觞。", "芳辰谅难再，嘉会讵可常。人命一朝尽，奄速如秋霜。", "乐哉今日宴，百岁遥相望。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"表忠卷为宁德李太华死倭难次韵三首 其一","p":"","d":"明代","a":"庞嵩","c":["百里郎官正属贤，闽山漳浦遘烽烟。撄城厉剑思酬主，裹革旋缰誓死边。", "林木夜寒归宿燕，野郊春尽忍闻鹃。浮名敢拟垂身后，独秉丹心一寸全。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和二十二弟不相遇之作","p":"","d":"宋代","a":"晁说之","c":["秋云欲遘雨，恼此山河凉。柴门试一出，矫目叹林光。", "孔鸾势自远，鸿雁意亦长。先后日云间，俗眼安得常。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"少工艺文","p":"沁园春","d":"宋代","a":"刘克庄","c":["少工艺文，朱丝练弦，黄流在璋。值虞廷戛击，箫韶之乐，周王寿考，追琢其章。汾水雁飞，鼎湖龙远，魂返今无异域香。浮生短，更两轮屋角，来去荒忙。人言八十鹰扬。笑千岁如何尺捶量。但负图龟马，藏之为宝，舐丹鸡犬，去不能将。友鲁申公，师浮丘伯，尚可教书村学堂。投老泪，瞻越山紫翠，陵树青苍。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"魏夫人与众真吟诗二首 其二 十二月一日夜南岳夫人作与许长史","p":"","d":"魏晋","a":"佚名","c":["灵谷秀兰荣，藏身栖岩京。被褐均衮龙，带索齐玉鸣。", "表盘幽辽里，掷神太霞庭。霄上有陛贤，空中有真声。", "抑我曲晨飞，案此绿轩軿。下观八度内，俯叹风尘萦。", "解脱遗波浪，登此眇眇清。扰竞三津渴，奔驰割尔龄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"少年游 织锦声","p":"","d":"清代","a":"黄钧宰","c":["年来花样喜翻新，越锦复吴绫。镫晕摇风，波纹逗雨，此意有谁听。", "西楼娇女笼纤玉，寒重梦初惊。只有疏篱，吟秋络纬，相和到天明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"客中逢乡人得家中消息","p":"","d":"明代","a":"邓雅","c":["去家不忍别，久客遂忘还。忽见故乡人，与语增戚颜。", "比邻害疵疠，群从亦凋残。所幸一室安，卫生良独艰。", "语终对斜日，一鸟鸣空山。意存恍惚际，心在悲喜间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"眼儿媚 呈周斡臣","p":"","d":"元代","a":"王恽","c":["桑榆晚景日＊＊。莫厌数相寻。静怜幽境，闲谈情话，与涤烦襟。济时幸有诸公在，乡社好浮沉。闲云却恐，西风吹去，认做商霖。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"京华元夕诗 其十","p":"","d":"明代","a":"邓云霄","c":["酒态同推阮步兵，谁论中圣浊和清。六街金界开黄道，一夜瑶京变赤城。", "朋辈连镳堪玩赏，风光转眼几阴晴。柏浮且尽杯中物，身后休誇百代名。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"主•奴才•奴隶","p":"","d":"当代","a":"何永沂","c":["功成赖假大天才，先把河山夺过来。唱罢人民当作主，笑抛诚信在蒿莱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"【双调】落梅风_太乙宫探梅","p":"","d":"元代","a":"赵善庆","c":["太乙宫探梅", "冰花艳，水月魂，斗诗坛醉翁笔阵。自南枝漏泄了湖上春，问东风几番花信？", "江楼晚眺", "枫枯叶，柳瘦丝，夕阳闲画阑十二。望晴空莹然如片纸，一行雁一行愁字。", "秋晴", "秋声定，微雨歇，透疏棂纸窗风裂。孤灯儿似知愁恨切，照离人半明半灭。", "暮春", "寻芳宴，拾翠游，杏花寒禁烟时候。叫春山杜鹃何太愁，直啼得绿肥红瘦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"旅寓岑寂中园丁送花四品因赋五绝","p":"","d":"宋代","a":"杨公远","c":["西蜀名花别样芳，玉环睡起试新妆。", "化工还有无情处，只与胭脂不与香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和张周玉访别","p":"","d":"宋代","a":"吴泳","c":["白露下百草，年光惊易徂。", "邮亭人折柳，别浦雁衔芦。", "社瓮应藏酒，秋盘好斫鲈。", "贤渠陶靖节，晚岁觉迷涂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"说谜三绝 其一 帘","p":"","d":"宋代","a":"吴儆","c":["满身珠翠间花钿，舞到梁州最可怜。一捻宫腰如束素，清风明月画堂前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"木哀十首 其一","p":"","d":"明代","a":"李江","c":["蟠桃秋叶落风寒，叶落风寒鼻亦酸。阆苑云空仙梦断，瑶池月落酒杯乾。", "韶华已付随流水，好合何期隔远峦。恼杀春花长不住，蟠桃秋叶落风寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"癸卯元日晴继复雪亦不废出谷日复晴归乡涂宿上元观灯野庙随所赋得十绝 其三","p":"","d":"元代","a":"刘诜","c":["市门处处系冰花，灯影蛾云动绛纱。走马城中三日雪，不知春已入谁家。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长相思 其一","p":"","d":"明代","a":"释函可","c":["长相思，来何迟。荆山鼎就紫清归，六宫粉黛化作泥。", "王母高居在瑶池，无数仙人进玉饴。千秋万岁以为期，何不驾六龙中天飞。", "青鸟衔书到海涯，杲杲出日，浮云蔽之。长相思，不可知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄南文德纯家","p":"","d":"明代","a":"邢宥","c":["山外平湖水接天，渔竿放下又耕田。相过暇日多贤达，诗酒优游忘岁年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"台湾八景","p":"","d":"清代","a":"高拱乾","c":["海上看朝日，山间尚晓钟。天开无际色，人在最高峰。", "紫阁催妆镜，咸池骇浴龙。风流灵运句，灼灼照芙蓉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏潭柘寺竹","p":"","d":"清代","a":"玄烨","c":["翠叶才抽碧玉枝，经旬清影上阶墀。凌霜抱节无人见，终日虚心与凤期。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄浮图慧海","p":"","d":"宋代","a":"岳飞","c":["湓浦庐山几度秋，长江万折向东流。", "男儿立志扶王室，圣主专师灭虏酋。", "功业要刊燕石上，归休终伴赤松游。", "丁宁寄语东林老，莲社从此著力修。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蜀府遇夏时教谕次韵叙德言怀","p":"","d":"明代","a":"方孝孺","c":["周道昔沦丧，凤鸟收其声。纷纷徇世士，各以智术鸣。", "仲舒起西都，蜀汉有孔明。下帷谈正谊，濡走济群生。", "二子苟遇时，惠泽𬒳孤茕。惜其遭逢谬，不见礼乐兴。", "迩来一千年，文献鲜有徵。岂无辅相贵，未免利禄婴。", "鄙夫何所知，浪窃当世名。致君事莫及，好古心徒倾。", "身疲道路长，兴入江山清。偶随群臣后，获见百代英。", "神姿俨渊肃，雄论极醇精。德政尚宽和，西土臻治平。", "福善固天理，愿治本民情。昔叹贤豪稀，今见德位并。", "寄言同袍子，拭目王化行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"代李叔介挽杨参政","p":"","d":"宋代","a":"王质","c":["运泰风云合，名高泰华秋。杓衡方北指，江汉已东流。", "寡祐良臣死，钟情志士忧。惊心波浪里，不见济川舟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"月上海棠","p":"","d":"清代","a":"赵我佩","c":["曲屏移过斜阳影。怨黄昏、一霎林烟暝。小立苍苔，隔花阴、袜尘香凝。", "湘帘捲，深院月明人定。", "暮云春树诗怀冷。似天公、付我伤心病。梦里闲愁，怕思量、旧时风景。", "红楼笛，忍把离魂唤醒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南乡子","p":"","d":"明代","a":"文徵明","c":["香暖透春肌，满眼新娇睡起迟。燕子不来三月尽，依依，手撚残花玉一枝。", "风袅鬓云垂，无限闲愁隐翠眉。好梦不成春自去，相思，只有青团扇子知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病剧就养城北玉清道院作三章 其三","p":"","d":"清代","a":"姚燮","c":["悔乃愤之几，何如慎诸后？自镜平生端，炯象毕呈丑。", "猛警同晨钟，尘去复奚帚？鬼神惕我危，相待益徵厚。", "坦掌偶失持，势遂邻械杻。命无侥倖存，正以顺为受。", "岂真石作罂，其坚逊陶缶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"四和林卿槟榔韵一首","p":"","d":"宋代","a":"刘克庄","c":["似椰内贮杯中物，非曲谁篘瓮面春。百粤姻盟常主约，三彭谗舌竟无神。", "浪云软饱元枵腹，暂借酡颜戏写真。此遣两行红袖去，锦潮亭下草如茵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄武冈宰宋雪岩","p":"","d":"宋代","a":"张炜","c":["柳下分攜须影苍，好风吹梦过都梁。", "诸蛮帖化花阴静，一骑飞尘荐墨香。", "书就几曾逢驿使，公余应不冷奚囊。", "云情鹤态元如旧，应倚株梅忆锦乡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大梁候吴明卿不得闻尚留里中赋此促之","p":"","d":"明代","a":"王世贞","c":["一往除书岁月深，怪来鸿信误追寻。三朝老共思家梦，万里归偏薄宦心。", "客笑元长宁寂寂，人窥夥涉莫□□。□□□□□□□，□□□□□□□。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病中别沈子嘉则之扬州","p":"","d":"明代","a":"王世贞","c":["溽炎始见蠲，微痾俄相逐。故人弃我去，使我惊局促。", "杂绪难尽言，轻帆易辞目。惆怅离后思，广陵雨中绿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和闲来","p":"","d":"宋代","a":"邵雍","c":["以身观万物，万物理非遥。", "马为乘多瘦，龟因灼苦焦。", "能言谢鹦鹉，易饱过鹪鹩。", "伊洛好烟水，愿同渔与樵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题历山舜祠","p":"","d":"唐代","a":"杜荀鹤","c":["昔舜曾耕地，遗风日寂寥。世人那肯祭，大圣不兴妖。", "殿宇秋霖坏，杉松野火烧。时讹竞淫祀，丝竹醉山魈。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"田家","p":"","d":"清代","a":"周馨桂","c":["每当秋熟尚啼饥，况此河乾尘欲飞。买得前村钓溪水，归来典尽箧中衣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"暮春寄怀曹南通任寺丞","p":"","d":"宋代","a":"林逋","c":["跌荡情怀每事同，十年曹社醉春风。", "弹弓园圃阴森下，棋子厅堂寂静中。", "赤脚我犹无一婢，黑头君合作三公。", "江湖今日还劳结，目送归飞点点鸿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"六月廿七日诸君子会予草堂次前韵四首 其一","p":"","d":"明代","a":"孙承恩","c":["重订茅堂约，无嗔折简招。追游匪公等，意气向谁消。", "村酿分邻瓮，山蔬荐菊苗。安期如可访，欲去海门樵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送陈亨叔县丞","p":"","d":"宋代","a":"刘克庄","c":["已折仙桂到月宫，安知再转瘴烟中。", "坐看管□封孤□，却使崔丞对二松。", "此士鼻端何待垩，老生指血至今红。", "祝君努力鸣昭代，切勿呻吟学冻蛩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送彦立兄游太学以恩袍草色动为韵","p":"","d":"宋代","a":"王之道","c":["梅花破朝寒，似欲壮行色。", "骎骎小骊驹，回首便数驿。", "一鹗在云路，鸷鸟空累百。", "从令马宾王，不是新丰客。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"熙宁五年归至旧山伤己感时作诗奉呈升卿黄丈 其二","p":"","d":"宋代","a":"吕南公","c":["彬树湖前流水远，石城街左乱山苍。滩深潭浅无由问，竹秀松枯不可常。", "物理自应随变动，道心聊欲寄存亡。唯君坐占忘言境，珍重诗编与酒觞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送祖印忠师南归","p":"","d":"宋代","a":"苏颂","c":["扰扰京华客，营营不自间。", "胡为丘壑者，亦到市朝间。", "孤月无留影，归云靡定山。", "东南清胜处，羡子一舟还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"刘孺人挽诗","p":"","d":"宋代","a":"叶适","c":["嗃嗃当年女手缝，一家从此更雍雍。", "性安於善行无迹，儿自为铭笔有踪。", "闻说湖清见龙首，还疑墓长羃云峰。", "哀情变化何级极，留泽凌霄绛绕松。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"王中立","c":["醉袖舞嫌天地窄，诗情狂压海山平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闻周孟","p":"","d":"宋代","a":"魏野","c":["乙巳暮春天，端居忽怆然。一名伤圣祖，三榜作遗贤。", "我自空弹指，君谁可比肩。何由销此恨，独坐落花前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长相思二首 其二","p":"","d":"南北朝","a":"徐陵","c":["长相思。好春节。梦里恒啼悲不泄。帐中起。窗前髻。", "柳絮飞还聚。游丝断复结。欲见洛阳花。如君陇头雪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春波书屋为屠司寇赋","p":"","d":"明代","a":"王鏊","c":["平湖渺渺春波绿，榆柳低垂洲渚曲。洲旁茅屋是谁家，言是屠公旧书屋。", "屠公致身廊庙里，犹有读书心未已。牙签缥轴置两头，充栋多还比邺侯。", "湖水平，春日晴，船头置书蓬底读，吾伊声和沧浪曲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"玉泉双柏行","p":"","d":"当代","a":"幻庐","c":["西来何意碧眼胡，静照以心独跏趺。满驮经卷任撕破，庭前唯指双柏株。", "一株叶细供瀹茗，一株枝茂藏栖乌。时非乌去销爪迹，清茗年年说空无。", "月地潜聆堕子实，悟开当下逋斯须。佛元在心心即佛，渠定是我我逢渠。", "法门微妙弃文字，拈花默会花同殊。青莲冉冉萦篆冷，沈水名香爇宣炉。", "营卫遐龄之丹灶，洗伐毛髓之醍醐。枯蕊春泥掌中示，尘虑宁将一日疏。", "桓侯剑门翠云蔽，将军汉武嵩阳初。合与少陵重梁栋，兴感毋用久踟蹰。", "凛然夭矫戴霜雪，千尺黛色淩斗枢。不涸不盈到池定，护持八部神龙居。", "异代衣履几曾识，甘泉长浸波心珠。苦茶心清心化苦，古者为师今为徒。", "柏林座中三让毕，真笔再著形传摹。急扫风雨焦墨透，世间清奇古怪图。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送人游天台","p":"","d":"元代","a":"邓文原","c":["此去兰亭修禊后，平明驱马试征衣。海边山尽天无尽，花底春归人未归。", "一雨潮生鱼入市，远岩月上鹤投扉。旧游二十年前路，孤负东风赋《采薇》。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"好事近（雪中携酒过元长）","p":"","d":"宋代","a":"赵鼎","c":["春色遍天涯，寒谷未知消息。且共一尊芳酒，看东风飞雪。", "太平遗老洞霄翁，相对两华发。一任醉魂飞去，访琼瑶宫阙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠王将军贞伯二章 其一","p":"","d":"明代","a":"胡应麟","c":["镇北威名著，安东将略长。援枹肝胆赤，仗钺鬓毛苍。", "置阵分鹅鹳，连镳控骕骦。旌旗萦析木，樯橹散扶桑。", "草檄屯兵地，分题结客场。荀吴元破敌，段颎旧平羌。", "巨碣祁连外，高牙敕勒傍。煌煌麟阁燕，兽锦出明光。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送叶成夫还闽中","p":"","d":"明代","a":"许天锡","c":["南征白雁叫秋旻，送尔归骖忆故人。月旦有评惭许劭，婚姻不断羡朱陈。", "山间松叶他时醉，洞口榴花几度新。怀梓况逢多病后，梦中鱼鸟递相亲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"二月二十三日犹在仪真馆二首 其二","p":"","d":"元代","a":"郝经","c":["二月还如夏，炎蒸郁震惊。迅霆侵骨冷，飞电透心明。", "海气沾衾湿，江声拍枕平。从今休禁火，一雨万家生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读赤壁赋前后二首 其一","p":"","d":"宋代","a":"文天祥","c":["昔年仙子谪黄州，赤壁矶头汗漫游。今古兴亡真过影，乾坤俯仰一虚舟。", "人间忧患何曾少，天上风流更有不。我亦洞箫吹一曲，不知身世是蜉蝣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望柳","p":"","d":"当代","a":"崔荣江","c":["柳丝如我思，春始便垂长。千缕为君发，一心缘别伤。", "风泠酸望眼，雨细淡红妆。有燕何持剪，双飞绞断肠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"仲春宜八里国道中","p":"","d":"明代","a":"释宗泐","c":["芭蕉叶开大如席，石榴花发红满枝。子规何似苦啼血，正是行客东还时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水龙吟 挽吕小薇先生","p":"","d":"当代","a":"傅义","c":["忽惊噩耗飞来，西江痛失吾元老。无多硕果，君何竟去，玉楼幽渺。", "千里频飘，一灯独守，冰心雪抱。叹半生侘傺，昊天不吊。", "薤歌彻，奎星杳。", "忆昔初窥隽藻，便深钦易安才调。韶华方茂，遽临衰迈，始瞻芝貌。", "卧疾频年，体羸神旷，尚相言笑。又凝情北望，倚篁衔泪，抚千秋稿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"证道歌","p":"颂证道歌","d":"宋代","a":"释印肃","c":["后人得道何穷数，万别千差同此路。", "成人者少败人多，达理契经无作做。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"包中香黍分边角","p":"菩萨蛮","d":"未知","a":"陈义","c":["包中香黍分边角。彩丝剪就交绒索。樽俎泛菖蒲。年年五月初。主人恩义重。对景承欢宠。何日玩山家。葵蒿三四花。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"用之相访忽忆汉孙不得一脉以死用前韵","p":"","d":"宋代","a":"李石","c":["叩门剥啄涕沾襟，忽忆僧孙病骨侵。", "壁上卧龙香线断，柱间题凤墨痕深。", "仓皇不瞑思君眼，辗转犹希住世心。", "真意自天渠信否，赠篇聊当阁中箴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和沈演公夜坐韵","p":"","d":"近代","a":"李洸","c":["一例肠如九曲盘，谁教愁绪入毫端。好春已觉寻游懒，恶抱争知湔韨难。", "楼外车声同雨闹，客中酒味胜梅酸。年时踪迹还相似，短烛残书坐夜阑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"征粮至浮河宿詹氏书斋次壁间韵","p":"","d":"清代","a":"孔毓玑","c":["雨过青山翠万重，浮河新水浸芙蓉。入门先拭题诗壁，裁句时闻隔院钟。", "只愿康衢酬帝力，敢期褒德启侯封。明年幸免催科累，载酒携筐劳尔农。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满江红 其二 勖受军训诸生","p":"","d":"近代","a":"卢前","c":["一息尚存，应未忘、匹夫之责。天下事、危如累卵，万千苦厄。", "患难迫人当大任，鞠躬尽瘁吾何惜。看中吴、当日小周郎，匡时策。", "尽汝力，完天职。心不死，血终热。念江山信美，旧时踪迹。", "尝胆卧薪师勾践，冲天奋翼怜萧特。补金瓯、誓我十年期，书诸褶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和韵 其二","p":"","d":"宋代","a":"韩淲","c":["酴醾一架煖争开，投老看花得几回。兴以芳时寻醉去，诗从永日送香来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"得吕山人报","p":"","d":"明代","a":"陈迁","c":["忽闻消息百忧攒，书到飞邮不忍看。蛮土岂终埋侠骨，白头何事泣南冠。", "呼朋问酒心先醉，垂死怜君胆未寒。莫向词林赋鹦鹉，妒人风雪易凋残。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"江头绝句 其十二","p":"","d":"明代","a":"程本立","c":["孰知中国外，民俗乃驺虞。舞意存千羽，歌情在裤襦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"安稳道中","p":"","d":"明代","a":"江源","c":["戒晓星轺度翠微，不堪野雾湿征衣。长桥跨涧水千尺，古庙依山树四围。", "愁我岖崎坡上路，爱他潇洒竹间扉。前程去去知何许，啼鸟声中又落晖。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵朱新仲省宿十首 其九","p":"","d":"宋代","a":"刘才邵","c":["与作先秋蒲，岂若经霜竹。坚脆随所养，古人戒多欲。", "年来铅汞鼎，丹火犹未伏。更须形中神，各各司其局。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闻王子房中丞死寇志感","p":"","d":"明代","a":"黎遂球","c":["都城鹫峰寺，忆尔隔垣看。生死七年易，勋劳千古难。", "忠魂应自吊，社稷信谁安。涕泪遥堪寄，秋墟汴水寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"富春舟中","p":"","d":"明代","a":"佘翔","c":["寒云落木晚萧萧，人与孤舟对寂寥。忽见西风吹五两，月明还趁浙江潮。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜过谢池小酌戏继前韵示诸友","p":"","d":"宋代","a":"欧阳澈","c":["为忆莲娃夜叩门，恐缘芳草怨王孙。眉弯海峤初生月，鬓亸巫峰欲坠云。", "金粟花残将委烬，香丝篆破不成文。朦胧月映人如玉，尔汝忘形共一樽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和西湖竹枝词","p":"","d":"元代","a":"朱庸","c":["小姑疑郎去不归，为郎打瓦复钻龟。青山尚有飞来日，不信人无相见时。", "阿奴采莲湖上舟，阿郎贩豆辽东州。一心愿逐东流水，流送辽东古渡头。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"出塞二首 其二","p":"","d":"明代","a":"王世贞","c":["不断穹庐色，檀槽压酪浆。俄闻五校至，去逐六骡亡。", "蒲类天如赭，燕支月似霜。前军又铙吹，生得左贤王。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浯亭望横山","p":"","d":"宋代","a":"游九功","c":["峨峨岸东山，躣来势奔虬。", "横约一溪水，抱邑止复流。", "近郭看逾好，向望此其尤。", "翠展曲屏宽，一目千里收。", "此山此水水，我歌我来游。", "知不市声杂，亦忘溪上幽。", "方将解其缚，于焉我何求。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"七月十六日晚雨已而月出","p":"","d":"宋代","a":"周紫芝","c":["将雨日已晏，既晴天亦曛。风从莽苍来，云向西南奔。", "忽于苍玉玦，拥此黄金盆。我居在山顶，升沉阅冰轮。", "三年东冈头，入我圭窦门。平生金兰友，老去无一存。", "愿言结神交，相与论素心。素心不可说，月亦终无言。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吴中友人惠蟹","p":"","d":"宋代","a":"宋祁","c":["秋水江南紫蟹生，寄来千里佐吴羹。", "楚人欲使衷留甲，齐客何妨死愿烹。", "下筯未休资快嚼，持螫有味散朝酲。", "定知不作蟛蜞悮，曾厕西都博士名。"],"tags":[],"z":"","y":"","s":"","k":"诗"}
];